DELETE FROM `quest_template_locale` WHERE `ID` = 7 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7,'zhTW','剿滅狗頭人','你的第一個工作是去清除一些敗類，$n。一群狗頭人佔據了北邊的森林。去那裡解決所有你看到的狗頭人惡黨。減少他們的數量好讓我們有一天能把他們驅逐出北郡。','殺死8隻狗頭人惡黨，然後向治安官瑪克布萊德覆命。','','到艾爾文森林的北郡修道院找治安官瑪克布萊德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 15 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (15,'zhTW','迴音山調查行動','$n，我的斥候告訴我說，狗頭人出沒的範圍遠大於我們的想像。一群狗頭人工人剛剛在北邊的回音山礦坑附近駐紮。$B$B到礦坑那裡，把他們都除掉。那裡至少有8隻狗頭人工人，殺了他們，看看他們的數量是否不止這麼多，完成之後向我回報。','殺死8隻狗頭人工人，然後向治安官瑪克布萊德回報。','','到艾爾文森林的北郡修道院找治安官瑪克布萊德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 21 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (21,'zhTW','迴音山清剿行動','你上次的調查證實，回音山礦坑需要一次清剿行動。回到礦坑那邊，幫我們清除那裡所有的狗頭人吧。$B$B抓緊時間，$n。狗頭人無所顧忌地盤踞在礦坑裡的時間越長，它們在北郡的據點也就越穩固。','殺死8隻狗頭人苦力，然後向北郡修道院裡的治安官瑪克布萊德覆命。','','到艾爾文森林的北郡修道院找治安官瑪克布萊德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 33 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (33,'zhTW','林中的群狼','這些狼群所感染的病毒無論怎麼也揮之不去。隨著日子一天一天過去，生病的狼群數量增加了。請人撲殺這些野生動物，對我來說是個痛苦的決定，但是我們必須在疫情擴大之前，趕快殺掉這些染病的幼狼。$B$B殺掉山谷中染病的幼狼，並且把牠們的皮帶來給我，作為你行動的證據。','帶8片染病的狼皮交給北郡修道院外的伊根·派特斯金納。','','到艾爾文森林的北郡山谷找伊根·派特斯金納。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 67 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (67,'zhTW','斯塔文的傳說','斯塔文?讓我查查鎮裡的記錄。$b$b斯塔文...斯塔文...讓我找找...啊，找到了!這裡有份斯塔文·密斯特曼托的檔案。記錄上最後地址是在月溪鎮的學校裡。哎呀，都是過時的東西了!$b$b朋友，你能幫我個忙嗎?如果你碰巧路過月溪鎮的話，也許能找到一些有關這個傢伙的新消息，別忘了告訴我一聲，好讓我更新檔案。','到月溪鎮的學校尋找關於斯塔文的新資訊，給書記員官達特利。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 69 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (69,'zhTW','斯塔文的傳說','哎呀!我上次肯定漏掉這個了。斯塔文檔案中的第一個地址下面還有另一個地址，這個地址被擦掉了一部份。看起來他好像去閃金鎮的獅王之傲旅店了。去那裡查查看吧，$n。','到獅王之傲旅店去問問那裡的人，看看他們是否聽說過斯塔文這個人。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (174,'zhTW','觀測星星','我的地精朋友考格答應過要幫我製造一個可以用來觀察星星的裝置。除了魔法之外，我相信還有別的理由可以解釋發生在這片森林中的奇怪變化。$b$b根據考格的設計圖，我們的第一步得先去找根由手藝高超的工程師所做的青銅管。','夜色鎮的維克托·安特拉斯要你給他一根青銅管。','','到暮色森林的夜色鎮找維克托·安特拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (177,'zhTW','觀測星星','那隻單眼透鏡是我最珍貴的寶物，不過在發生了一件事情之後...我就把它丟在穀倉後面了。有個瘋狂的食屍鬼曾經在那一帶徘徊，可能是它把東西給撿走了。有人說那個邪惡的傢伙住在靜謐花園墓場。','從瘋狂的食屍鬼那裡拿回盲眼瑪麗的單眼透鏡，把它交給夜色鎮的維克托。','','到暮色森林的夜色鎮找維克托·安特拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (245,'zhTW','蜘蛛的威脅','你好啊，$c。你有沒有看到過在西邊出沒的那些蜘蛛?這些八條腿的東西實在是太多了，多到我們沒法應付，指揮官又沒有多餘的人力可以從夜色鎮派來協助我們。$b$b我實在是不好意思向你開口，不過...看樣子你好像能對付它們。我不能承諾給你什麼貴重的寶貝，不過如果你幫助我們除掉這些骯髒的臭蟲，我肯定會獎賞你的。$b$b哦，對了，給你個忠告:盡量別碰到它們的毒液。','殺死15隻小型結網毒蜘蛛。然後向暮色森林的守夜人道茨報告。','','到暮色森林找守夜人道茨。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (540,'zhTW','保全書籍','那些野蠻的巨魔現在就駐紮在奧特蘭克廢墟，一想起他們會把那裡的書籍怎麼樣，我就感到毛骨悚然。你一定要盡力去完成我給你的任務!$B$B進入奧特蘭克廢墟，找到巨魔奪走的書籍。把你找到的所有東西都帶給我，特別是這本書:《格里雷克之臂》。這本書裡寫著食人妖的古老學說，我一定要學。奧特蘭克是完整保存這本書的唯一地方。','把5本失而復得的書籍和包含《格里雷克之臂》的破舊的皮書帶給南海鎮的博學大師迪布斯。','','到希爾斯布萊德丘陵的南海鎮找博學大師迪布斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (542,'zhTW','向米爾頓回覆','我得花點時間來研究你帶回來的《格里雷克之臂》，不過我敢說密爾頓已經等不急要把你找回來的另一些書放到暴風城的圖書館裡去了。$B$B這些就是你從奧特蘭克廢墟帶回來的書，我已經按照目錄分類整理過了。把它們帶給暴風城的密爾頓·西弗，他一定會很感激你的。','把奧特蘭克的書籍帶給暴風城的密爾頓·西弗。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10787,'zhTW','飛龍之末的龍','如果我們要面對他，我們必須做些會激怒苟克的事情。\r\n\r\n現在你釋放了&&&，我想我知道要做什麼了!\r\n\r\n當你準備好時，讓我知道，而我將要求&&&載你飛到其中一個被刺穿在飛龍之末岩石上的龍的屍體處。\r\n\r\n取回屍體，並把它帶回來這裡給我，這樣我們就能創造一些必定可將苟克從隱藏中帶來出來的東西!','雷克薩已經要求你跟他講關於騎乘&&&出去到飛龍之末去收回一具黑龍屍體的事。當你收回屍體時，返回到劍刃山脈之雷神要塞的他那裡。','','到劍刃山脈的劍刃庭園找雷克薩。','','','','',0);
-- Fill in zhTW quest_template_locale fields that were left empty (fell back to enUS in the objective tracker)
DELETE FROM `quest_template_locale` WHERE `ID` = 25 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25,'zhTW','冷靜一下','你真該看看的，$c！$b$b精靈們認為銀風避難所牢不可破。擁有這樣的重裝防禦與水元素軍隊，他們的想法幾乎是正確的。$b$b幾乎。$b$b我們的一個法師成功召喚出一個扭曲變形的元素，作用是讓其他元素陷入混亂與暴怒之中。$b$b啊，看看他們臉上的表情！$b$b<塔坎大笑。>$b$b很不幸地，可以控制那個元素的法師死在戰場上了。現在我需要一個人去撂倒這個變形的元素。','銀風避難所的塔坎隊長要你到密斯特拉湖，打敗泰德雷斯與12個污濁的水元素。','在密斯特拉湖上的眺望台中偵查聯盟的前哨站。','去梣谷找碎木崗哨的馬斯托克·維爾西斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 75 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (75,'zhTW','斯塔文的傳說','我剛搬進來的時候發現樓上的箱子裡有一捆羊皮紙，我想看看那些羊皮紙上寫了什麼，但是我的視力卻讓我只能看到一團迷濛。$B$B幫我這個快瞎了的老人一個忙吧，去檢查一下樓上箱子裡的東西，看看有沒有什麼有關那個斯塔文的資訊。我記得有一頁褪色的日記，你肯定會對它感興趣的。把它拿過來，我會盡力幫助你的。','治安官哈迦德要你從樓上的箱子裡找出一頁褪色的日記。','','去艾爾文森林找東谷伐木場的治安官哈迦德。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 99 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (99,'zhTW','阿魯高的愚行','在我對阿魯高的魔法越來越瞭解的同時，我對這個蠢貨的鄙視與輕蔑也日益加深。我已經快要完成對他所謂的「拯救行動」研究。$B$B在我瞭解到底是什麼樣的巫術導致了焚木村的奇怪現象之後，我就算是完全瞭解透徹了。白天，那些農民們都是好端端的人。但太陽一下山，他們就變成了月怒狼人。$B$B我需要從阿魯高給他們戴上的附魔鐐銬中汲取一些能量。帶6副焚木鐐銬來給我， $N 。','帶6副焚木鐐銬給瑟伯切爾的達拉爾·織曦者。','','去銀松森林找瑟伯切爾的達拉爾·道恩維沃爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (166,'zhTW','迪菲亞兄弟會','你只剩下最後一個任務需要去完成。我們必須除掉艾德溫·范克里夫。雖然對一個活生生的人宣判死刑實在令我非常難過，但為了西部荒野人民的利益，我不得不讓范克里夫永遠安息。當你完成這件事之後，就把他的頭帶來給我。','殺死艾德溫·范克里夫，把他的頭交給格里安·斯托曼。','','去西部荒野找哨兵嶺的格里安·斯托曼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (167,'zhTW','我的兄弟……','那時我們正在西部荒野的一個大礦坑中工作，就是那個隱藏在月溪鎮的穀倉底下的礦坑……沒人知道當時那些可惡的 $C 是那從那裡出現的。總之礦道突然坍塌了，我逃了出來……可是其他人……就再也沒聽到過其他人的下落了。$B$B你看起來運氣可能會比我們好一點。如果你能幫我找到我弟弟的話，我會非常感謝你的。他總是戴著他的探險者協會徽章。如果你找不到他的話，那塊徽章至少還能給我帶來一些安慰……','將工頭希斯耐特的探險者協會徽章帶回去給暴風城的維爾德·希斯耐特。','','去找暴風城的維爾德·薊草。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (168,'zhTW','收集記憶','我的許多朋友都在那次可怕的礦坑倒塌中送掉了性命。如果你的冒險正好需要到月溪鎮的那個礦坑的話，請幫忙留意一下有沒有什麼可以辨認他們身份的標誌或是物品。如果你恰巧找到他們的礦業工會會員卡的話，請一定要帶回來給我，好讓他們的家人可以明白那場恐怖的意外結果。','找回4張礦業工會會員卡並送回給暴風城的維爾德·薊草。','','去找暴風城的維爾德·薊草。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (170,'zhTW','新的威脅','我希望你是到這裡來助我們一臂之力的， $C 。在上一次穴居怪襲擊之後，我們的人手就明顯不夠了。$B$B我聽說他們現在已經遍佈我們的國土，看來寒脊山谷也不例外。東南部的山區和湖畔已經到處都是穴居怪的身影了。$B$B糟糕的事情還不只是這些，幾天前，他們襲擊並佔領了我們西邊的營地!$B$B我們這兒人手有些不足，小姑娘，我們需要強大的武力幫助我們趕走這些傢伙。','巴爾林·霜錘要你去殺死6個石齶穴居怪和6個壯實的石齶穴居怪。','','去丹莫洛找寒脊山谷的巴爾林·霜錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (179,'zhTW','矮人服飾','嘿，你是新來的吧?看來你需要些暖手的東西，對嗎?$B$B我想你應該想要一副保暖的手套。我是個熱心腸，很願意給你一副手套，不過我有個條件。$B$B你幫我弄些狼肉來，我保證你不會被凍掉手指頭。你覺得怎麼樣?','斯登·粗臂想要8塊硬狼肉。','','去丹莫洛找寒脊山谷的斯登·粗臂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (182,'zhTW','食人妖的威脅','那些食人妖正在行動，我得說他們比平常還要活躍。我們以前就看過他們組成戰鬥的隊伍，但這一次實在......不一樣。$B$B然而，更重要的是，如何繼續保護安威瑪。我不想讓安威瑪把注意力轉移到穴居怪身上時，被這些食人妖從側翼攻擊。去削減一下他們的數量。他們得知道我們並非毫無防衛之力。','殺死10個小霜鬃食人妖。','','去找丹莫洛的格瑞林·白鬚。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (183,'zhTW','獵殺野豬','沒什麼能比得上用一整天的時間去打野豬更讓人愉快的了，對吧?不過，寒脊山谷裡的野豬太多了，你幾乎已經不可能在那裡再感受到狩獵的樂趣。你根本不需要去激怒它們，因為它們早就是怒氣衝天，隨時準備用獠牙把你拱上天了!事實上，這些過剩的野豬已經對我的日常狩獵形成了威脅。$B$B長話短說吧，如果你能幫我殺掉些野豬，我真的會非常感激你的。','塔林·銳眼讓你去殺掉12隻小型峭壁野豬。','','去丹莫洛找寒脊山谷的塔林·銳眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (185,'zhTW','獵虎大師','當我還只是個小女孩的時候，我的父親就開始訓練我捕獵老虎的技巧。$B$B你會發現虎崽子特別容易追蹤和獵殺。你在探險隊的營地附近很容易就能找到虎崽。$B$B讓我們來測試一下你的追蹤技巧，看看你是否能獵殺這些野獸。','殺死10隻小荊棘谷猛虎。','','去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (186,'zhTW','獵虎大師','年輕老虎是一回事，成年的猛虎又是不同的狀況了。獵殺成年的荊棘谷猛虎將會是更困難的挑戰。$B$B那些成年的大貓通常都在河岸東邊、庫爾森的營地南邊打發時間。','獵殺10隻荊棘谷猛虎。','','去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (187,'zhTW','獵虎大師','老年荊棘谷猛虎是虎群中最強壯的。死在牠利齒與巨爪之下的 $R  $C 亡魂可不只一個。$B$B如果艾耶克知道你打敗這些老虎的話，一定會興奮到發抖。數量最大的虎群就在南邊，荊棘谷海岸邊境的大裂層附近。','獵殺5隻老年荊棘谷猛虎。','','去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (188,'zhTW','獵虎大師','根據傳說，有一隻難以捉摸的母老虎...一隻強力的大貓，甚至讓成年的雄虎顯得矮小。奈辛瓦里探險隊的獵人們都沒能成功狩獵她。許多獵人在她耙一般的爪子下淪為獵物，他們的屍體在格羅姆高營地北邊的山丘腳下腐朽。$B$B他們將那野獸稱為辛達爾。$B$B你得下決心去做從來沒有 $R 做到過的事:狩獵、殺死辛達爾，並取得牠的爪掌。','獵殺辛達爾並帶回牠的爪子。','','去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (189,'zhTW','血頂族的耳朵','該死的食人妖!他們不斷的殺死我們派到叢林裡去的人!和他們的衝突已經讓我損失太多優秀的護衛了。我們的花費也因此節節上升!要我怎麼向大財主里維加茲解釋呢?$B$B是該做決定的時候了……想想看，科博克……你可不是被派到這裡來整日無所事事的……啊，有啦!你……你就是 $N ，是不是?你會幫我的，對不對?這份工作的獎勵可是很豐厚的哦!$B$B條件如下，幫我弄15個血頂食人妖的耳朵來，我會重重地酬謝你的。','拿15個血頂食人妖的耳朵回來給藏寶海灣的科博克。','','去荊棘谷找藏寶海灣的科博克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (190,'zhTW','獵豹大師','如果你想加入由小赫米特領導的頂尖狩獵隊，就必須先證明自己是一個能幹的獵豹高手。一開始不會太難的:先把目標放在小獵豹身上。等到你的狩獵經驗成長了以後，你自然就會找些更加危險的獵物。$B$B就從東邊開始，等你成為一個獵豹大師之後再回來找我。','獵捕10隻小獵豹。','','去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (191,'zhTW','獵豹大師','最年輕的黑豹完全不是你對手。年齡稍長的黑豹，漸漸變得更強壯、更敏捷，也更難被擊敗。你必須拿牠們當下一個目標。$B$B那些較大的黑豹通常在西邊。','獵殺10隻黑豹。','','去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (192,'zhTW','獵豹大師','接下來的部分可就比較困難了。豹長大之後，將會變得更加詭計多端，和牠們周遭的環境交融在一起，變得更難以察覺。這些狡猾的豹名為「深喉獵豹」，因為牠們喜歡突然從黑暗中現身...張著滿是利牙的血盆大口。$B$B如果你想證明自己是個真正的獵豹人，獵殺深喉獵豹是你唯一的方法。','獵殺10隻深喉獵豹。','','去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (193,'zhTW','獵豹大師','你幾乎證明自己是一位優秀的獵豹高手了。但仍有一隻豹逃過了你的掌握。$B$B歌謠傳頌著一隻名叫巴爾瑟拉的豹。你該去試著用自己的技巧獵殺這頭強大的野獸，通常在巨魔洞穴上方的倒樹附近。$B$B將巴爾瑟拉的牙齒帶去給艾爾加丁應該足以證明你是大師級的獵豹獵人。','取得巴爾瑟拉的牙齒。','','去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (194,'zhTW','迅猛龍專精','你覺得你的狩獵技術是最頂尖的?我馬上就能檢驗一下，看看你是不是在騙人。到叢林裡去殺十隻荊棘谷迅猛龍，這樣一來我們就知道你是不是所謂的王牌獵人了。$B$B至於在哪裡才能找到牠們，我是絕對不會告訴你的!追蹤野獸本身就是挑戰的一部分。','獵殺10隻荊棘谷迅猛龍。','','去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (195,'zhTW','追蹤迅猛龍','現在讓我們看看你能不能應付更大的挑戰吧。深入叢林裡，去幹掉十隻殘暴的鞭尾迅猛龍。這些迅猛龍絕對比你之前對付過的還要強壯。$B$B鞭尾迅猛龍主要待在這裡的東南邊。靠近卡萊廢墟的位置。','獵捕10隻鞭尾迅猛龍。','','去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (196,'zhTW','迅猛龍專精','過了這條河之後，在南邊的森林裡，棲息著一種非常狡猾的迅猛龍，當地人稱之為「叢林潛獵者」。牠們遠比你之前試著捕獵的目標更難追蹤和獵殺。獵殺十隻這種叢林潛獵者，那一定能成為你營火旁的好故事。','獵殺10隻叢林潛獵者。','','去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (197,'zhTW','迅猛龍獵手大師','在回到奈辛瓦里探險隊營地之前，你得完成不可能的任務:狩獵從沒有其他獵人能夠捕捉的一隻迅猛龍。那野獸的名字叫泰希斯，牠統治了北荊棘谷東南隅。$B$B將泰希斯的爪子帶去給那個矮人獵手應該能證明你不是普通的 $R 。','獵殺泰希斯。','','去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (198,'zhTW','送補給物資給士兵托爾森','嗯。沒錯，我這裡確實有件適合你做的事。目前佈署在荊棘谷北部的多倫中尉和他的部下需要我們的定期補給。$B$B由於食人妖的攻擊，這些補給物資一直沒有送出去，我得找人來幫我處理這件事。多倫的營地就在從暮色森林進入荊棘谷的道路西北方，你只要把補給品交給士兵托爾森就行了，如果他不在營地裡，那可能是他在營地的南邊巡邏。他會處理好這些東西的。$B$B提醒你，如果你失敗了的話，就得賠償我們的損失。','將各式各樣的哥布林補給品交給士兵托爾森。','','去找荊棘谷的列兵索爾森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (201,'zhTW','調查營地','我收到一條報告說，有一群獵人在風險投資公司營地所在的納菲瑞提湖上游建立營地。通常我根本不會在意這件事，但當我聽說小赫米特·奈辛瓦里也是那群獵人中的一員時，我改變了想法。他絕對是個構思周密的人，如果你瞭解我的意思的話，你永遠不會有把握的。$B$B你為什麼不去那片營地裡偵察一下呢， $N ，去看看他們到底想幹什麼?','找到獵人營地並向藏寶海灣的克拉茲克報告這個營地的位置。','找到獵人的營地','去荊棘谷找藏寶海灣的克拉茲克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (202,'zhTW','庫爾森上校','你一次又一次地證明了自己的能力，而你的足智多謀略似乎甚至能與庫爾森媲美。如果……如果你願意徹底投身到與庫爾森鬥爭的事業中去的話……也許你將成為我們反抗軍的救星!$B$B他就躲在那個名叫「儲藏室」的洞穴深處發號施令。你必須進入那個洞穴，幹掉他身邊的保鏢，最終把庫爾森和他的副官們都給除掉。$B$B出發吧， $N 。我們的生命與希望，如今都已經全部掌握在你的手中了。','殺掉6名庫爾森精英和4名庫爾森副首領，並將庫爾森的頭顱交給反抗軍營地裡的多倫中尉。','','去荊棘谷找反抗軍營地的多倫上尉。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (203,'zhTW','以彼之道還施彼身','我們正在與庫爾森進行一場艱難的戰鬥。他是個非常優秀的戰術大師，而且他的手下士兵的數量是我們的十倍!如果我們想要勝利的話，就必須使用他擅長的戰術來對付他。$B$B到他在東邊設立的營地裡去，殺掉他的士兵，越多越好，然後在增援趕來之前撤退。','殺死15名庫爾森叢林戰士，然後向反抗軍營地的尤瓦中士覆命。','','去找荊棘谷反抗軍營地的尤瓦中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (204,'zhTW','庫爾森的藥物','要想和庫爾森搏上一搏，我們就必須削弱他們的醫療隊伍。他在那裡聚集了大批醫療人員，他們能用密林藥劑治療自己的部隊，並用毒草汁液對我們的人下毒。$B$B我們要用這些藥物來治療我們自己的戰士，同時我們也需要一份毒液的樣本來研製解藥。到庫爾森的營地去把這兩樣東西找來吧，藥品應該就在那些醫療人員或密林戰士的身上，而毒草汁液大概是保存在營地中的一些物資箱裡。','給反抗軍營地裡的尤瓦中士帶回7份密林藥劑和1份毒草汁液。','','去找荊棘谷反抗軍營地的尤瓦中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (205,'zhTW','食人妖巫術','在我研究這些食人妖傳說的時候，我希望你能幫我收集一些食人妖們施展邪惡魔法時必備的法器。到南邊的那個劈顱食人妖部族的地盤上去，從他們的巫醫和秘法師那里弄一些劈顱食人妖的神像回來吧。','給反抗軍營地的尼麥茲修士帶回4只劈顱食人妖的神像。','','去荊棘谷找反抗軍營地的尼麥茲修士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (206,'zhTW','麥佐斯','庫爾森的確是該死，不過……到底是誰將他帶上了這條邪惡的道路呢?通過研究，我已經找到了真相:是一個名叫麥佐斯的巨魔法師幹的。他住在荊棘谷東部的巨魔山中，據說他擅長心靈控制魔法，我也確信正是他使得庫爾森上校墮落的。$B$B如果麥佐斯繼續活在這世上，他的邪惡法術就有可能影響到更多人，或許又會出現另一個庫爾森上校。$B$B殺死他，把他的心靈之眼帶回來，這正是他用來誘惑他人墮落的物品。','將心靈之眼交給反抗軍營地裡的尼麥茲修士。','','去荊棘谷找反抗軍營地的尼麥茲修士。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (207,'zhTW','庫爾森的秘密','庫爾森上校曾是個偉大而高貴的人，我必須得找到讓他墮落至此的原因!他一定是被食人妖的魔法給控制了。要想搞清楚這一點的話，我們就得先研究一下食人妖的傳說故事。$B$B據說荊棘谷中的食人妖遺跡中隱藏著四塊石板，我必須得看看這些石板上到底記述了些什麼東西!你去給我拓一份這些石板上的文字來，把拓片都交給我。$B$B第一塊石板在巴拉爾廢墟裡，第二塊石板在暗礁海的海底，第三塊和第四塊應該都在祖昆達廢墟裡。','找到4塊石板並將上面的內容帶回去交給尼麥茲修士。','','去荊棘谷找反抗軍營地的尼麥茲修士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 208 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (208,'zhTW','王牌獵人',' $N ，你成為了一位夠格進入我們狩獵隊的獵手。無論是羅德隆的戰場還是危機四伏的叢林，我都鮮少見到有誰能像你這樣擁有如此強大的戰鬥能力。$B$B你成功地殺死了殘忍的辛達爾，隱密的巴爾瑟拉和狡詐的泰希斯。但對於這片叢林中的獵人們來說，虎王邦加拉西的頭才代表著至高無上的榮耀。這隻白虎正是我來這裡的原因...但目前還只能眼睜睜看著牠待在南方的居處。如果你能殺死虎王邦加拉西，那麼你無疑是這裡最優秀的獵人。','小赫米特·奈辛瓦里要你將大白虎，虎王邦加拉西的頭帶回來給他。','','去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 209 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (209,'zhTW','劈顱食人妖的獠牙','靠不停地獵殺老虎來保證對南海島嶼的虎牙出口實在是苦差事，不僅難度高，而且花費也高。幸虧我們找到了一種替代品，就是這些劈顱部族的食人妖的獠牙。$B$B嘿，只要你不說，買家就不會知道，對吧?給我搞一批食人妖獠牙來吧，這樣我們就能應付每月一次的供貨啦!','給藏寶海灣的科博克帶回18根劈顱食人妖的獠牙。','','去荊棘谷找藏寶海灣的科博克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (210,'zhTW','克拉茲克的烹調鍋','在營地裡，我是專門負責伙食的。過去的活真的很多，讓我每天都要忙到死，直到我從藏寶海灣的哥布林商人那裡買了台多功能機械烹調鍋才有所改觀。這鍋實在是太棒了!它節省了我許多的時間……我是說，在它壞掉之前!$B$B你能幫我把這鍋帶到那個哥布林商人那裡去，讓他給我修理一下嗎?他的名字叫克拉茲克。','把克拉茲克的烹調鍋帶給藏寶海灣的哥布林克拉茲克。','','去荊棘谷找藏寶海灣的克拉茲克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (213,'zhTW','惡性競爭','太倡狂了!吉爾里茲把貿易親王們指定的要員們都從這裡趕了出去，這件事已經夠糟的了，現在他居然還和那些聲名狼籍的海賊們往來!$B$B里維加茲不會坐視不理的，他允許我按自己的方式來解決這些問題。$B$B我的方式是什麼?偷!最近，風險投資公司的地質學家們正在研究他們從礦裡挖出的一種奇怪的藍色水晶，從那群地質學家手裡搞些樣本回來給我，當然，我不關心你用怎樣的手段去搞。','給藏寶海灣的科博克帶回8塊打磨過的水晶。','','去荊棘谷找藏寶海灣的科博克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (214,'zhTW','紅色絲質頭巾','迪菲亞兄弟會的人都會戴著一種紅色的頭巾，這顯然已經是個盡人皆知的秘密了。但我們又瞭解到，這個頭巾的材料是他們的成員在幫會內部地位的象徵。$B$B既然如此，那麼我希望你出馬殺死一些兄弟會的高階成員。他們的最高階成員無疑都躲在范克里夫的秘密藏身處附近。作為證據，你要給我帶回10條紅色絲質頭巾來，這樣我才能給你獎勵。祝你好運， $N 。','給哨兵嶺哨塔的斥候瑞爾帶回10條紅色絲質頭巾。','','去找西部荒野的哨兵瑞爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (217,'zhTW','果斷的一擊','我的計畫成功了。這幫洛克莫丹的怪物好像是由一個叫格勞姆格的酋長領導的，不過格勞姆格身邊守衛森嚴，兩個精英守衛納什爾和布勞勒爾從不離他左右。$B$B如果你想證明自己的價值的話， $N ，我希望你能接下殺掉格勞姆格和他那兩個手下的任務。去吧!等我把這裡的事情搞定再與你會合。','殺掉穴居人首領格勞姆格及他的兩個守衛，納什爾和布勞勒爾。然後回到南部警戒塔向拉格弗斯上尉報告。','','去洛克莫丹找國王谷的拉格弗斯上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (218,'zhTW','冰與火','索林派你出去偵查真是找對人了。你帶回一些很有用的消息。$B$B問題是，這只讓我們有更多工作要做。那些混亂的食人妖仍然想把矮人給踢出寒脊山。我絕對不會讓那些著火的惡魔，把我們覆滿白雪的山谷變成一個山中湖。$B$B那個食人妖首領、他的僕從、以及那個火焰生物應該都在東南方的山洞裡。把他們全宰了。','殺死冷酷的格瑞克尼爾、10個格瑞克尼爾的僕從、以及遊蕩的火元素。','','去找丹莫洛的格瑞林·白鬚。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (224,'zhTW','保衛國王的領土','我們要保衛洛克莫丹， $N !國王的士兵都在遙遠的戰場上英勇作戰，我們的家園卻變得危機叢生。穴居怪源源不絕地從每個一條裂縫裡斷冒出來!四處橫行的他們已經成了鐵爐堡最大的威脅，我們一定要消滅這些噁心的怪物!$B$B我們需要像你這樣的勇敢冒險家來幫忙消除穴居怪的威脅。殺掉6個石裂穴居怪和6個石裂斥候，然後回來向我彙報。你會在南邊山脈的隧道裡找到許多這種害蟲。','塞爾薩瑪的巡山人庫伯弗林特要你殺掉6個石裂穴居怪和6個石裂斥候。','','去丹莫洛找南部警戒塔的巡山人庫伯弗林特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (237,'zhTW','保衛國王的領土','巡山人庫伯弗林特總是在我面前稱讚你， $C 。因此現在我要交給你一個極其重要的任務，你必須不斷給那些入侵的穴居怪施加壓力，直到我們的兄弟們從聯盟前線回來。$B$B到南部的丘陵去，殺掉10個石裂擊顱者和10個石裂先知。你的行動可以為我們贏得一點時間，完成任務後就回來向我報告。','南部警戒塔的巡山人格拉維戈要你殺掉10個石裂擊顱者和10個石裂先知，然後回去向他彙報。','','去洛克莫丹找國王谷的巡山人格拉維戈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (255,'zhTW','雇傭兵','我等了兩個月才得到了從鐵爐堡傳來的消息，說是會有少量士兵來幫助我們防守塞爾薩瑪，不過他們還得再等兩個月才能到這兒來!我們的鎮子沒人守衛已經夠糟了，但是我們的挖掘場和水壩─這些地方都隨時面臨著被襲擊的危險。$B$B看來我已經沒有選擇了，必須臨時徵召一點士兵才行。$B$B你怎麼樣?你看起來挺合適的， $C 。有一群巨魔在洛克湖的東北方安營紮寨，你能不能幫我們把那些傢伙趕走呢?','塞爾薩瑪的鎮長埃羅恩·鈍鼻雇你去殺掉4個莫格羅什巨魔、4個莫格羅什蠻卒和4個莫格羅什執行者。','','去找洛克莫丹的鎮長埃羅恩·鈍鼻。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (256,'zhTW','懸賞令:卓克蘇爾','以塞爾薩瑪鎮長之令:$B$B卓克蘇爾，襲擊塞爾薩瑪鎮、巨石水壩及挖掘場的巨魔的領導者和組織者。現要求不惜採用一切手段殺死卓克蘇爾。$B$B若有人呈上殺死卓克蘇爾的證明，鎮長將給予巨額獎金。$B$B卓克蘇爾最後一次出現是在洛克莫丹東北部的巨魔營地裡。','殺了卓克蘇爾，把他的頭顱帶給塞爾薩瑪的鎮長埃羅恩·鈍鼻。','','去找洛克莫丹的鎮長埃羅恩·鈍鼻。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (257,'zhTW','自豪的獵人','你覺得自己可以和勇敢的達瑞爾相提並論?我可不這麼認為，當然囉，如果你不服氣的話，完全可以試試看。我會讓你去做一件非常困難的事情，困難到以你的能力恐怕根本沒法擺平，所以就算你完成不了也用不著氣餒。$B$B有群禿鷲在洛克莫丹這裡築了巢，你何不試著把牠們解決掉?告訴你吧，如果你能完成這個任務，我就把我的弓或是火槍送給你。<他輕蔑地上下打量著你。>$B$B反正你看起來也沒什麼可以輸掉的東西。','殺死8隻山地禿鷲，然後回到遠行者小屋找年輕的達瑞爾。','','去洛克莫丹找旅行者營地的年輕的達瑞爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (258,'zhTW','獵人的挑戰','你叫 $N 啊嘶，對吧?看得出來，你對自己的狩獵本領變得非常自傲，對吧?那沒什麼了不起。$B$B你應該試試去捕殺野豬。相信我，這和捕殺寒脊山谷裡那些野豬可不一樣，所以你最好當心點。$B$B失敗了也別難過。不過如果你成功了，我就把我的襯衣脫下來給你!$B$B我有沒有跟你說過我這個著名的傷疤是怎麼來的?沒有?好吧，兩年前的一天...','殺掉10隻老山豬，然後回到遠行者小屋找年輕的達瑞爾。','','去洛克莫丹找旅行者營地的年輕的達瑞爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (261,'zhTW','血色之路','坦率地說，我們現在正在與天譴軍團交戰。他們是一群致力於腐化我們的人民、污染我們的土地的惡魔。我們一定要在他們將我們最後的堡壘徹底血洗、將我們的世界徹底拖入黑暗之前阻止他們。我們血色十字軍發誓要奉獻出全部身心，與天譴軍團鬥爭到底。$B$B如果你也如此宣誓了的話，鼓起你的勇氣並證明你的忠誠─去與淒涼之地的不死生物劫毀者們作戰吧，它們都聚集在那個地區南部的白骨之谷裡。$B$B只有這樣，十字軍才會接納你。','殺掉30個不死生物劫毀者，然後向尼耶爾前哨站的安東修士覆命。','','去淒涼之地找尼耶爾前哨站的安東修士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (263,'zhTW','保衛國王的領土','巡山人告訴我你很勇敢也很能幹， $N 。我們這兒就需要像你這樣的 $R 。穴居怪的問題一點也沒有好轉，預備軍都被派到前線去了，我們在這兒孤立無援。不過現在我們有你這樣一個經驗豐富的 $C ，就看看你能做什麼吧。$B$B去殺掉8個石裂斷骨者和8個石裂薩滿，讓我們瞧瞧你是不是名副其實的穴居怪殺手。','南部警戒塔的巡山人沃爾班要你殺掉8個石裂斷骨者和8個石裂薩滿。','','去丹莫洛找國王谷的巡山人沃爾班。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (267,'zhTW','穴居怪的威脅',' $C ，你可能知道也可能不知道矮人的領地正面臨穴居怪的威脅。鐵爐堡的預備部隊被派到聯盟前線去了，只有很少一部分留下來負責保衛這裡的安全。我的部隊負責看守這裡的大門，提防隨時可能到來的攻擊，我們絕不能因為害怕遭到入侵而離開崗位。$B$B不過我們得向潛伏在山裡的那些穴居怪施加點壓力。如果你能勝任這個工作，就去幹掉這些穴居怪，然後帶8顆穴居怪的石牙回來作為勝利的證明。','給南部警戒塔的拉格弗斯上尉帶去8顆穴居怪的石牙。','','去丹莫洛找南部警戒塔的拉格弗斯上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 271 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (271,'zhTW','維林的報復','不曉得你有沒有興趣報復一下他的冒失個性?我不願意承認，但達瑞爾是有點能耐。$B$B一年前，整個遠行者小屋裡的獵人都在捕獵一隻巨熊，不過沒有一個人成功。所以，達瑞爾想去試試身手。他的努力只換來一道劃過眼睛的可怕傷疤。$B$B若你殺了那隻熊，我敢說就算是達瑞爾也會啞口無言。$B$B那隻熊名叫奧爾蘇迪，你會在北方洞穴附近找到牠的巢穴。','殺掉奧爾蘇迪，把牠的頭顱帶給遠行者小屋裡的達瑞爾。','','去洛克莫丹找旅行者營地的年輕的達瑞爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 273 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (273,'zhTW','挖掘場的補給品','現在還不算太晚，你還可以去找胡達爾。他不大可能走得太遠，儘管米蘭和賽恩都很壯實，但是他們帶著幾隻大桶是沒法走太快的。$B$B他們走的是補給車隊常走的路線，從鎮子出發，沿著洛克湖的邊緣往南走。$B$B只要他們還沒走到挖掘場，你就應該可以在路上找到他們。','和胡達爾談話。','找到胡達爾、米蘭和賽恩','去洛克莫丹找洛克湖邊的胡達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (275,'zhTW','大地上的膿皰','我不知道是怎麼回事，但是墮落正在濕地上蔓延。沼地蠕行者出現了，他們就像是腐爛而危險的膿皰。要制止這些膿皰，就必須把他們驅散開，把它們趕回沼澤。$B$B這些沼地蠕行者一般都在濕地的水道裡活動。','殺死8隻沼地蠕行者，然後向濕地的『綠色守衛者』雷希耶爾覆命。','','去濕地找綠帶草地的綠色守衛者雷希耶爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (276,'zhTW','踐踏之爪','蘚皮豺狼人在濕地平靜地生活了許多年，但如今他們的數量卻膨脹了不少。他們的腳正踐踏著沼澤地中的灌木與花朵，他們污濁的斧頭也砍伐了太多的樹木。$B$B他們已經令這裡的自然失去了平衡。為了濕地的安寧，必須削減這些豺狼人的數量。$B$B去殺死15名蘚皮豺狼人和10名混血蘚皮豺狼人，他們就在南邊的奧加茲隘口附近活動。完成任務之後再回來向我覆命。','殺死15名蘚皮豺狼人和10名混血蘚皮豺狼人，然後向濕地的『綠色守衛者』雷希耶爾覆命。','','去濕地找綠帶草地的綠色守衛者雷希耶爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (277,'zhTW','火焰管制','蘚皮豺狼人們正在大量地砍伐濕地的樹木，用樹幹和樹枝當柴火來燒。我不能再容忍這樣的行為了!$B$B把蘚皮豺狼人生火用的打火石都給我搶過來。除了年幼的蘚皮豺狼人和混血蘚皮豺狼人以外，其他所有的蘚皮豺狼人身上都會帶著打火石。','給『綠色守衛者』雷希耶爾帶回9塊粗製打火石。','','去濕地找綠帶草地的綠色守衛者雷希耶爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (278,'zhTW','黑暗危機逼近','你必須立刻去收集拆彈用的原料， $N 。你可以在附近的土生蜘蛛身上找到潛伏者的毒液。鱷魚的眼淚在洛克湖裡的鱷魚身上就有。不過莫格羅什水晶很難找到。東北邊礦坑裡的巨魔開採這種水晶，不過即使在那裡，莫格羅什水晶也不常見。$B$B我們必須要作好準備才能粉碎黑鐵矮人的計畫!你找齊了這些材料之後就立刻回來找我，我會準備進行混合。','莫格羅什營地的阿胥蘭‧暗石要你收集潛伏者的毒液、狂熱之血和一塊莫格羅什水晶。','','去洛克莫丹找巨石水壩的主工程師辛德維爾七世。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (279,'zhTW','海中的魚人','可惡的魚人正在從深海裡源源不斷地爬出來，它們沿著海岸線建立自己的村莊和定居點。這些傢伙給我們的漁民和商人帶來了極大的困擾，我們必須要阻止這種行為。$B$B它們當中有一個叫高布勒爾的頭目最近一直帶著一群藍鰓魚人埋伏在道路旁，搶劫過往的商旅，得手之後又馬上撤回它們的村子。現在我們的通商道路非常危險，所以我們想要通過懸賞來解決這個問題。$B$B高布勒爾和它的跟班們就躲在北邊的河口附近。找到它，把它幹掉，然後把它的頭給我帶回來。','殺掉12個藍鰓魚人。','','去濕地找米奈希爾港的卡爾·波蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (287,'zhTW','霜鬃食人妖要塞','我快要來不及提交報告了，你能幫我一下嗎， $N ?我只想知道這些食人妖躲在什麼地方，不過我看見這麼多的食人妖就怕得不敢進去了。$B$B你要做的是...進到山洞裡，在裡面到處走走，幹掉一些食人妖，然後再回來。$B$B順著向北的路離開卡拉諾斯，當你走到一座橋前的時候，再沿著冰凍的河流向西一直走到湧冰湖。你會發現烈酒村就在湖的西岸，而食人妖要塞就在村莊的西南邊。','偵察霜鬃食人妖要塞，替卡拉諾斯的森內爾‧白鬚殺掉5個霜鬃獵頭者。','對霜鬃巨魔要塞進行詳細的偵查','去丹莫洛找閃光嶺的森內爾·白鬚。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (288,'zhTW','第三艦隊','我曾經是浪花女神號上的大副─浪花女神是庫爾提拉斯第三艦隊的主力戰艦。這是一支多災多難的艦隊，說它多災多難是因為……它在最後一次出航中遇到了紅龍的襲擊。這些龍是被獸人控制的!$B$B紅龍噴出的火焰對我們的戰艦來說簡直是毀滅性的……我們的艦隊在這片海域被燒得一乾二淨，全軍覆沒。我是那次災難的唯一倖存者……$B$B……哦，我的頭疼得像鼓錘在敲!我需要一些讓我頭腦清醒的東西，好讓我繼續講述我的故事。','為大副菲茲莫斯買一份壺裝蜜酒。','','去濕地找米奈希爾港的大副菲茲莫斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (289,'zhTW','被詛咒的船員','<緩過氣來的菲茲莫斯繼續講述他的故事……>$B$B我是這支倒楣的庫爾提拉斯第三艦隊中唯一的倖存者，整支艦隊都在北方的海岸附近覆滅了。不過，雖然我是艦隊中唯一活著的人，卻不是唯一一個依然在這裡出現的人!因為，在一條已經沉沒的船裡，藏有巨大的、可怕的寶藏，它所擁有的可怕魔力將我的弟兄們的靈魂束縛在被海水侵蝕的船體裡。$B$B如果你能超渡我的那些被詛咒的弟兄們，也許你就能破除那個詛咒。','殺死13個被詛咒的水手、5個被詛咒的水兵和大副斯涅利格。把斯涅利格的鼻煙盒交給米奈希爾的大副菲茲莫斯。','','去濕地找米奈希爾港的大副菲茲莫斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (290,'zhTW','解除詛咒','為了破除詛咒，解救我所有的兄弟，就必須要把裝在我船上的那個鬼東西拿回來進行淨化!我不知道它是什麼，但我知道它被存放在船上的保險箱裡，而保險箱的鑰匙一向是由哈林多爾船長保管的。$B$B我的老船長仍時常出現我的夢裡，在我的那艘已毀滅了的無畏號的甲板上走來走去……去找到鑰匙，用它打開無畏號上的保險箱。$B$B然後，在你獲得那件被詛咒的東西以後，把它交給鎮上的牧師，戈羅林·鋼眉。','從哈林多爾船長那裡拿到無畏號的保險箱鑰匙。','','去濕地找無畏號的保險箱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (294,'zhTW','奧莫爾的復仇','目前我們所面臨的形勢十分嚴峻，這已經是眾所周知的事了。我們剛挖出這些骨頭，它們就招來了一大群迅猛龍。這些兇殘的野獸殺光了我的弟兄們，並把我、麥琳和可憐的勘察員困在了這上面。$B$B幫我把濕地裡的這些迅猛龍都給殺光， $N 。雜斑迅猛龍和雜斑尖嘯龍就在山崖的西邊，要是你有能力對付它們的話，每種都給我殺上十隻。$B$B這只不過是我對它們的復仇計畫的開始而已!','維爾加挖掘場的奧莫爾·鐵衣要求你殺死10隻雜斑迅猛龍和10隻雜斑尖嘯龍。','','去濕地找維爾加挖掘場的奧莫爾·鐵衣。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (295,'zhTW','奧莫爾的復仇','現在是時候讓這些該死的迅猛龍為它們的嗜血而後悔了。在懸崖下面還有一些雜斑刺喉龍和雜斑鋸齒龍，每種都給我殺10隻，它們要為自己的所作所為付出代價!','奧莫爾·鐵衣要求你殺死10隻雜斑刺喉龍和10隻雜斑鋸齒龍，然後回到維爾加挖掘場向他覆命。','','去濕地找維爾加挖掘場的奧莫爾·鐵衣。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (296,'zhTW','奧莫爾的復仇','在你下到懸崖底部的時候，我碰巧發現了有一隻很特別的迅猛龍在那邊站著休息。它比一般的迅猛龍的體形要大得多，看起來也特別兇猛。我敢打賭它就是那群迅猛龍的首領，就是它帶著手下來這裡毀了整個挖掘場。$B$B我現在交給你最後一個任務， $N 。以正義的名義，審判薩爾圖斯!當然，考慮到它所犯下的重罪，它唯一能得到的判決就是死刑!把它的一隻爪子給我帶回來作為它已死的證據。','維爾加挖掘場的奧莫爾·鐵衣要求你殺死薩爾圖斯，並在任務完成之後帶著它的一隻爪子向他覆命。','','去濕地找維爾加挖掘場的奧莫爾·鐵衣。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (297,'zhTW','收集塑像','前一陣子，就在穴居怪出現於此區之前，我們發現一大批奇特的塑像。但是我們還來不及研究它們，穴居怪就把我們從廢墟裡趕了出來!這些塑像對穴居怪有種奇特的影響。它可以讓那些穴居怪變得更加瘋狂!$B$B給我拿8個塑像回來，我希望研究它們，也希望它們離開穴居怪的手!整個挖掘場裡都是穴居怪，你可以從他們身上拿到這些塑像。','帶8個石刻塑像到鐵環挖掘場給麥格瑪爾‧落斧。','','去洛克莫丹找鐵環挖掘場的麥格瑪爾·落斧。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (299,'zhTW','發現歷史','在迅猛龍大舉入侵之前，我找到了一塊名叫戈奧茲之石的巨大石碑。我翻譯好的文字被分成了四部分，散落在挖掘場中的四個不同的地方。這些文字描述的是一個「神聖的計畫」和一個「註定的命運」。$B$B我們應該馬上把它們都收集起來，而不是繼續在這裡浪費時間。但是我已經很老了，恐怕沒辦法再殺出去跟那些兇猛的野獸作戰了。但是你不同，你年輕而強壯。$B$B到挖掘場裡去搜索這四片失落的石板:阿度斯石板、莫德爾石板、高爾姆石板和奈爾魯石板。它們應該被藏在某些古董器物裡，另外你也得留意土壤鬆動的地方。把它們拿回來給我，這樣我才能揭開這個秘密!','勘察員維爾加要求你在挖掘場中搜索4塊石板的碎片，它們是阿度斯碎片、莫德爾碎片、高爾姆碎片和奈爾魯碎片。','','去濕地找維爾加挖掘場的勘察員維爾加。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (303,'zhTW','黑鐵戰爭','戰火席捲了整個世界。當許多精銳的矮人士兵們為了聯盟而犧牲在前線時，我們自己的土地卻淪為了這群邪惡的黑鐵矮人覬覦的目標。他們已經攻陷了薩多爾大橋，丹莫德也岌岌可危。$B$B我們要你去聚集起一股力量，並將戰線推回去。如果你能殺死10名黑鐵矮人、5名黑鐵隧道工、5名黑鐵破壞者和5名黑鐵爆破兵的話，就能為我們組織反擊爭取到寶貴的時間。$B$B兵貴神速，快出發吧!','丹莫德的莫特雷·加瑪森要求你殺死10名黑鐵矮人、5名黑鐵隧道工、5名黑鐵破壞者和5名黑鐵爆破兵。','','去濕地找丹莫德的莫特雷·加瑪森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (304,'zhTW','艱鉅的任務','我手下的大部分士兵都在丹莫德的戰役中死去了，我的親兄弟也在薩多爾峽谷上的西橋被毀的時候不幸犧牲。唉，黑鐵矮人真是個像惡魔一般邪惡的族群。根據羅戈收集到的情報，這群在濕地四處肆虐的暴徒的領袖是一個名叫巴爾加拉斯的術士。他是個十分膽小謹慎的傢伙，在把手下的士兵送上戰場執行命令的時候，他往往卻躲藏在自己位於東南方惡鐵嶺的營地裡。$B$B如果你能找到這個懦夫，殺了他，把他的耳朵拿來給我，我會給你支付可觀的酬勞的， $C 。','殺死邪惡的巴爾加拉斯，把他的耳朵帶給丹莫德外的布萊德·長鬚。','','去找濕地的布萊德·長鬚。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (307,'zhTW','骯髒的爪子','東邊的銀泉礦坑很久以前就枯竭了。礦工聯盟把它改造成了儲藏庫，不過現在狗頭人佔據了那裡，用牠們的骯髒爪子染指我們矮人的精良工具!$B$B我們很快就能把這些害蟲趕走，但是礦工聯盟要求我們在衝進去大開殺戒之前，先把洞裡的礦工裝備拿出來。這是個艱難的任務，你也許需要幾個幫手。$B$B他們的裝備就散佈於礦坑四處，裝在礦工聯盟的木箱裡，祝你好運。','到銀泉礦坑去收集6套礦工裝備，然後向巡山人雷矛覆命。','','去洛克莫丹找奧加茲崗哨的巡山人卡爾·雷矛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (309,'zhTW','護送貨物','我們得把炸藥粉送到鐵環挖掘場，但這台車哪都去不了。要靠我們運這麼多炸藥太困難了，這附近又很危險。而且有賽恩跟他們一伙，誰知道那幫黑鐵矮人打算對我們做什麼?$B$B如果有你幫我照料這些東西，我會感覺好得多。當你和我在保護貨車時，米蘭可以負責卸載火藥桶。','保護胡達爾和鐵環車隊，然後通知勘察員基恩薩·鐵環。','護送米蘭去挖掘場','去洛克莫丹找鐵環挖掘場的勘察員基恩薩·鐵環。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (312,'zhTW','馬克格拉恩的乾肉','我原本儲備了一個月的乾醃肉準備過冬，為了防止野熊把肉銜走，我把它們鎖在了儲藏櫃裡。但是在我外出打獵的時候，一個叫做冰鬚的野獸偷走了我的儲藏櫃!可笑的是那個蠢貨撬不開這只用瑟銀鑄成的櫃子。$B$B但是如果拿不回這些肉，我就會餓死的。你的身手看來不錯，也許你能幫我取回儲藏櫃?你瞧我拖著這條廢腿也沒辦法把那只櫃子搶回來……','從冰鬚的洞穴裡拿回裝有馬克格拉恩的乾肉的儲藏櫃。','','去丹莫洛找烈酒村的圖德拉·馬克格拉恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (313,'zhTW','被迫從遠處觀察','災變迫使穴居怪成群湧向地表，也因此逼得霜鬃食人妖們不得不逃亡。不幸的是，他們決定跑到我們家門前落腳順便為我們製造麻煩。$B$B我派了巡山人登斯坦和他的小隊到城鎮西南方的灰色洞穴，監視住在裡面的雪怪們，但現在我必須將他召回卡拉諾斯。找到他們並且告訴他們，將地精們提供的遙控式觀察機器人佈署好，然後回到卡拉諾斯。','將薩蘭上尉的命令傳達給灰色洞穴裡的巡山人登斯坦、巡山人雷溫，和巡山人瓦爾葛蘭姆。','','去丹莫洛找鋼架補給站的駕駛員迪恩·石輪。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (315,'zhTW','完美的烈酒','我正在尋找可以釀製完美烈酒的方法。我知道我能做到－釀酒就像我的本能一樣。我缺的只是一份正確的釀酒配方...$B$B霜鬃食人妖在西北邊的閃光嶺上種植了一種叫做微光草的植物。他們通常在奇怪的部族儀式才會用到它。我們還沒有發現這種草有太多的用途，不過它有種非常獨特的味道...我要試驗用這植物釀造我的酒!$B$B取得微光草可能會很危險，但不管你從食人妖的籃子裡「借」來多少，我都會好好付給你報酬。','將7束微光草交給卡拉諾斯的雷傑德·麥酒。','','去丹莫洛找寒風峽谷的雷傑德·麥酒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (317,'zhTW','貝爾丁的補給','我正在準備為攻城坦克旅執行一項任務。這次任務會持續很長時間，所以我得預先收集能夠維持一個月的物資。貝爾丁正忙著修理我的坦克，你能幫我去弄一些東西來嗎?$B$B我需要一些毛皮來做床墊，還要一些野豬肉作為食品儲備。豬肉當然是從野豬身上割下來的，最好的毛皮是熊皮……在灰色洞穴南部的雪地上到處都是這兩種動物的蹤跡。','收集4大塊野豬肉和2張厚熊皮，把它們交給鋼架補給站的駕駛員貝隆費茲。','','去丹莫洛找凍土嶺的駕駛員貝隆·風箱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (319,'zhTW','艾沃沙酒的要求','我有一桶釀製好的艾沃沙酒，不過……你能幫我個忙嗎?烈酒村急需人手去對付在村子附近溜達的野獸。有時它們離我們非常近，那真是太危險了。$B$B我們並不害怕這些熊啊，豹啊，野豬啊─任何一個有自尊的矮人都不會害怕─不過，如果你能替我把它們搞定的話，我就能騰出更多的時間來釀酒了。','殺掉6頭冰爪熊、8隻老峭壁野豬和8隻雪豹，然後回到烈酒村的雷傑德·麥酒那裡。','','去丹莫洛找寒風峽谷的雷傑德·麥酒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (338,'zhTW','荊棘谷的青山','如果奈辛瓦里知道了這一切，他一定會很生氣的!$B$B出於對我的信任，他讓我來校對他的小說《荊棘谷的青山》的手稿。一開始事情進行得非常順利，但昨天一陣大風吹過了營地，結果把手稿吹得滿天都是!$B$B我已經很努力地找回了大部分的書頁，但還是有幾頁被吹進了叢林中。請你幫我把這四章裡的掉落的那幾頁書都給收集起來吧。$B$B等這四章手稿都搜集齊了以後，把它們還給我。','收集《荊棘谷的青山》的手稿中丟失的頁面。在集齊四章書之後，將它們還給巴尼爾·石罐。','','去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (339,'zhTW','荊棘谷的青山 - 第一章','第一章實在是太精彩了，令人欲罷不能!奈辛瓦里設定了小說的背景，而且在小說裡提到了他的同伴們，甚至包括我!$B$B不過，糟糕的是……有幾頁好像弄丟了。似乎第1頁，第4頁，第6頁和第8頁落在叢林中的什麼地方了!','將奈辛瓦里的小說《荊棘谷的青山》的第1頁，第4頁，第6頁和第8頁帶給巴尼爾·石罐以湊齊第一章。','','去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (340,'zhTW','荊棘谷的青山 - 第二章','第二章是整個激動人心的狩獵故事的楔子。可是裡面也有幾頁找不到了，我真想踢自己幾腳!$B$B看來我必須得找到第10頁，第11頁，第14頁和第16頁才能湊出完整的第二章。','將奈辛瓦里的小說《荊棘谷的青山》的第10頁，第11頁，第14頁和第16頁帶給巴尼爾·石罐以湊齊第二章。','','去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (341,'zhTW','荊棘谷的青山 - 第三章','第三章是我最喜愛的部分。裡面詳細講述了艾爾加丁爵士和羅歐克女士使用矮人步槍完成的第一次狩獵。而且第三章的結尾也寫得極好，為什麼?因為實在是太扣人心弦了!$B$B不過，讓我看看，似乎我們仍然要需要找回第18頁，第20頁，第21頁和第24頁來湊齊這一章。這些書頁不知被風吹到哪裡去了……','將奈辛瓦里的小說《荊棘谷的青山》的第18頁，第20頁，第21頁和第24頁帶給巴尼爾·石罐以湊齊第三章。','','去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (342,'zhTW','荊棘谷的青山 - 第四章','啊，第四章，大結局!多麼精彩的結局啊!$B$B第四章裡我們只丟了3頁，也就是第25頁，第26頁和第27頁。','將奈辛瓦里的小說《荊棘谷的青山》的第25頁，第26頁和第27頁帶給巴尼爾·石罐以湊齊第四章。','','去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (348,'zhTW','荊棘谷熱疫','我病了...病得...非常厲害...$B$B我...染上了...荊棘谷熱疫...致死的疾...疾病...$B$B...只...只有吃下...野人莫...莫...莫克...的心臟...才...才有救...那...是...一隻殘忍而...狡猾的...野獸。$B$B...巫醫安巴格瓦...是...唯一會...召喚...它...的人...$B$B找到...住在南邊...靈魂...洞穴...裡的安巴格瓦...$B$B...快點...我就要死了...就要死了...','找到巫醫安巴格瓦並要求他召喚出野人莫克，然後將野人莫克的心臟交給芬·菲茲拉克。','','去荊棘谷找藏寶海灣的芬·菲茲拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (354,'zhTW','阿加曼德家族','阿加曼德家族曾是提里斯法林地中最富有的家族。我過去曾在他們的磨坊裡工作……當然，我是說在瘟疫降臨之前。$B$B天譴軍團入侵的時候，阿加曼德家族的人們加固了他們的莊園，並說服了在他們家做工的人留下來幫助他們抵抗天譴軍團。我們實在是太蠢了，但我們至少是愚蠢而忠誠。$B$B而阿加曼德家族用榮耀之類的幌子讓我們去送死，結果現在他們倒成了天譴軍團的走狗!$B$B為了被遺忘者，你必須去剿滅墮落於瘟疫之中的阿加曼德家族!把他們的屍體帶回來給我。','把格里高的遺骸、妮薩的殘骸和薩爾曼的遺骸交給布瑞爾的庫勒曼·法席恩。','','去提瑞斯法林地找布瑞爾的庫勒曼·法席恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (356,'zhTW','巡查後方','亡靈壁壘上的衛兵們時刻都在提防著從瘟疫之地潛入提里斯法的敵人，但仍有些天譴軍團的士兵能躲過這樣的警戒線。$B$B我們必須專注在一個戰線上才有辦法在亡靈壁壘獲得勝利!我們絕對不能腹背受敵，更不能容許補給線遭到切斷。$B$B往西邊巡邏過去，消滅你所找到任何的天譴軍團爪牙。特別注意一下巴尼爾農場，那裡已經充斥著天譴軍團的爪牙了。','殺死8個可怕的血殭屍和8個遊蕩的幽靈。','','去找提瑞斯法林地的亡靈衛兵林奈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (358,'zhTW','盜墓賊','北邊的加倫鬼屋你去過嗎?那個地區的西南角是一大片亂葬崗，裡面葬著提里斯法一帶的大量因瘟疫而死的人。$B$B那邊墳墓裡的屍體大多沒能變亡靈，但最近天譴軍團派出了一群腐皮豺狼人到那裡去收集屍體，以此來壯大他們的軍隊。我們不能允許這樣的事情發生!$B$B你的任務有兩個:殺光躲在亂葬崗和加倫鬼屋裡的腐皮豺狼人，並把他們身上的防腐劑搶回來，正是這種防腐劑使他們活過來的。','殺死腐皮盜墓賊和混血腐皮豺狼人。','','去提瑞斯法林地找布瑞爾的執政官塞弗倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (362,'zhTW','鬧鬼的磨坊','代弗林·阿加曼德是阿加曼德家的兩個男孩中最小的一個，但這兩個男孩子卻完全不像是兄弟。薩爾曼身材高大而且待人彬彬有禮，而他的弟弟代弗林卻身體虛弱，而且嘴巴很刻薄惡毒。$B$B當阿加曼德磨坊遭遇瘟疫的時候，他是第一個被感染的。現在，只要你靠近通向阿加曼德磨坊的道路，就仍能聽見他那喋喋不休的囈語。$B$B我正在收集阿加曼德家族所有人的遺骸，首先，我想弄到可憐的代弗林的屍骨。找到並摧毀他，然後把他的遺骨帶回來給我。','殺死代弗林·阿加曼德，然後將代弗林的遺骸交給布瑞爾的庫勒曼·法席恩。','','去提瑞斯法林地找布瑞爾的庫勒曼·法席恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (364,'zhTW','無腦的殭屍','從第一個被遺忘者從墓穴中爬出那時開始，我們就在與巫妖王的天譴軍團作戰，那支大軍包含了被死靈法術喚起的不死生物部隊、生長於大陸北方的愚蠢野獸，還有永遠遭受痛苦折磨的幽靈。$B$B巫妖王已不再君臨冰封王座之上，但這個村莊的北部仍有他的奴隸們在四處橫行。消滅他們。儘管他們可能曾是我們的兄弟姐妹，也絕對不要留情。','殺掉5個無腦的殭屍和5個悲慘的食屍鬼。','','去提瑞斯法林地找喪鐘鎮的暗影牧師薩維斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (365,'zhTW','悲傷之地','看看誰來了?你看起來是個菜鳥 $C 吧。如果你想向黑暗女王陛下證明自己的實力，就得先學會我們被遺忘者行事的幾條基本原則。$B$B這裡的西邊有個農場，人類寄生其上有如腐屍身上的黴菌。更糟糕的是，血色十字軍會從他們的哨塔到附近巡邏。給這些渣滓們好好地上一課吧，把他們的寶貝南瓜給我偷10顆來。$B$B偷到10顆南瓜以後，就把它們交給布瑞爾的藥劑師喬漢。','從位於布瑞爾西邊、喪鐘鎮北邊的農場中偷10顆南瓜來，把它們交給布瑞爾的藥劑師喬漢。','','去提瑞斯法林地找布瑞爾的藥劑師喬漢。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (367,'zhTW','新的瘟疫','希瓦娜斯大人最近交給了我們皇家藥劑師學會一項很有挑戰性的命令。黑暗女王相信我們的知識與新發明的魔法將會是她擊敗阿薩斯的有力武器，她要求我們研製出一種新的瘟疫，這種瘟疫要比以前出現在艾澤拉斯大陸上的任何一種疾病都要更加猛烈，它會把阿薩斯和他的天譴軍團徹底毀滅。$B$B我的研究結果表明，野獸的血液也許是一種重要的藥引。給我帶回五瓶黑暗犬的血液來，我要驗證一下自己的理論。','布瑞爾鎮裡的藥劑師喬漢要求你收集5瓶黑暗犬的血液。','','去提瑞斯法林地找布瑞爾的藥劑師喬漢。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (368,'zhTW','新的瘟疫','在你幫我收集樣本的同時，我的實驗報告也出來了。看來我還需要更多的材料來進行進一步的研究，適當加強這種新瘟疫的傳染能力。毒殺個把倒楣鬼，那是小孩子才玩的把戲，只有將瘟疫傳遍整個世界才算得上是有意義的事。$B$B我需要5片邪鰭魚人身上的鱗片，在北邊或者西邊的海灘上應該就能找到那些魚人。','布瑞爾鎮裡的藥劑師喬漢要求你收集5片提里斯法林地的邪鰭魚人的鱗片。','','去提瑞斯法林地找布瑞爾的藥劑師喬漢。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (369,'zhTW','新的瘟疫','在你出去收集鱗片的時候，我已經在我的藏書中找到了一些古老而有趣的文章。這些文章裡面提到，以前曾有一種古代的瘟疫殺死過成百上千的人，而後來又有人發現在夜行蜘蛛的毒液中就能提取到這種瘟疫的致病物質。$B$B給我帶些夜行蜘蛛的毒液來，讓我完成這個實驗。我想知道毒液中的感染性元素是否能和我最新研製出來的瘟疫病原體共存。據說這種蜘蛛一般在提里斯法林地的東部出沒。','布瑞爾鎮裡的藥劑師喬漢要你去收集4份邪惡的夜行蜘蛛的毒液樣本。','','去提瑞斯法林地找布瑞爾的藥劑師喬漢。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (370,'zhTW','與血色十字軍的戰爭','執行官阿倫的檔案中對如何清除這群在我們土地上肆虐的人類問題作了詳細的部署。情報表明，血色十字軍派遣了派瑞恩隊長以及足有一個整編旅的部隊進駐了布瑞爾西南方的廢塔。$B$B去殺掉派瑞恩隊長、3名血色十字軍狂熱者和3名血色十字軍傳教士，然後向我回報。','布瑞爾的執行官塞加德要求你殺掉派瑞恩隊長、3名血色狂熱者和3名血色傳教士。','','去提瑞斯法林地找布瑞爾的執行官塞加德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (371,'zhTW','與血色十字軍的戰爭','我們仍然處於戰爭狀態中，而且血色十字軍正在逐漸壯大。執行官阿倫給我的報告中提到，在瓦松隊長的指揮下，血色十字軍正以提里斯法東南部巴尼爾農場附近的那座廢塔為據點肆意劫掠。$B$B去殺掉瓦松和5名血色十字軍苦行修士，這對十字軍來說將是一次沉重的打擊!','布瑞爾的執行官塞加德要求你殺掉瓦松隊長和5名血色苦行修士。','','去提瑞斯法林地找布瑞爾的執行官塞加德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (372,'zhTW','與血色十字軍的戰爭','血色十字軍已經從提里斯法林地北部的廢塔出發，穿過了法奧之墓。根據目前我們所掌握的情報，一個名叫麥拉其的軍官指揮著這支邪惡的部隊，他是個非常殘忍的傢伙。$B$B我相信你能完成這個非常重要而又危險的任務。以黑暗女王陛下的名義，殺死麥拉其和他的兩名保鏢!','布瑞爾的執行官塞加德要求你刺殺麥拉其隊長及他的兩名保鏢。','','去提瑞斯法林地找布瑞爾的執行官塞加德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (374,'zhTW','死亡證明','執行官塞加德告訴我說你最近和血色十字軍交戰，提里斯法林地裡現在到處都是這幫討厭的傢伙。$B$B黑暗女王麾下的瓦里瑪薩斯大人計畫將人類這種艾澤拉斯大陸上的渣滓與垃圾徹底清除掉。但目前的狀況是，人類當中最麻煩的一群傢伙─血色十字軍─已經殺入了提里斯法林地，我們必須得面對他們的挑釁。$B$B去吧，去給這群該死的血色十字軍一點顏色看看， $C 。給我帶回10枚血色十字軍徽記之戒，以此證明你對偉大的黑暗女王陛下與瓦里瑪薩斯大人的忠誠。','給布瑞爾的亡靈衛兵伯吉斯帶回10枚血色十字軍徽記之戒。','','去提瑞斯法林地找布瑞爾的亡靈衛兵伯吉斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (375,'zhTW','死亡之寒','好冷啊...可怕的瘟疫正如冰冷的毒蛇一般在我的血管中逡巡，也許很快我就會徹底失去意志，但這世上沒有任何東西能夠阻止我為我們偉大的黑暗女王效命。一接到命令，我就開始為希瓦娜斯大人軍隊中那些死去的戰士縫製屍袋。$B$B但現在我的手卻因為寒冷而顫慄不已。如果你能給我帶回五張夜行蝙蝠的毛皮和一些粗線的話，我就可以給自己縫條毯子了。幫幫我， $N ，這樣我就可以繼續為黑暗女王陛下的事業效力了。','給布瑞爾的格雷森·戴德馬帶回5張夜行蝙蝠的毛皮和一些粗線。','','去提瑞斯法林地找布瑞爾的格莉絲·戴瑪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (376,'zhTW','被詛咒者','我的任務包括照料受傷的士兵，縫製鎧甲和衣服，還有為暗影牧師薩維斯提供任何他可能需要的支援。$B$B看起來，你也即將加入到為他效力的隊伍中...我猜是要獵殺那些沒腦子的傢伙。好吧，如果你還想留著你的小命的話─我想你一定是的─也許我能幫助你。我這裡沒有足夠的狼爪子和蝙蝠翅膀了，如果你能幫我弄一些來的話，我會幫你找幾件鎧甲。在這裡的西北方可以找到大群的狼和蝙蝠。','取得4只食腐狼的爪子和4張夜行蝙蝠翼。','','去提瑞斯法林地找喪鐘鎮的新兵艾爾雷斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (377,'zhTW','罪與罰','貴族議會好像嫌他們對暮色森林的漠不關心還不夠過分，現在他們居然無視夜色鎮議會的存在，決定把迪克斯特·瓦德囚禁在暴風城，而不是按照埃伯洛克大人的判決將這個惡棍斬首!$B$B迪克斯特·瓦德是在把墓地裡的屍體賣給摩本特·費爾時被抓住的，這理應是死罪。可是暴風城卻認為他們才擁有對他的處決權!$B$B去暴風城的監獄把瓦德殺掉，把他的手給我帶回來作為證明，我會獎賞你的。','夜色鎮的米爾斯泰普議員要你殺死迪克斯特·瓦德，並把他的手帶回來作為證明。','','去暮色森林找夜色鎮的議員米爾斯迪普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (378,'zhTW','積怒已久','你已經向我們展示出了你對麥格尼陛下的忠誠， $C 。而且我也深刻地感受到了你對那些黑鐵矮人的仇恨。$B$B我必須要堅守崗位，因此，我不得不把一個本應由我親自去完成的重要任務交給你。根據羅戈收集到的情報顯示，卡姆·深怒正是襲擊薩多爾大橋的元兇。由於他所布下的邪惡計畫，長鬚才失去了他的親人。$B$B這個劊子手由於某些政治原因被扣押在了暴風城的監獄裡。我要他死， $N 。為了長鬚!殺死卡姆·深怒，把他的腦袋給我帶回來!','丹莫德的莫特雷·加瑪森要求你把卡姆·深怒的頭顱交給他。','','去濕地找丹莫德的莫特雷·加瑪森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (380,'zhTW','夜行蜘蛛洞穴','我們的一項最重要的任務就是獲取賴以生存的自然資源。即使在當年聯盟最鼎盛的時候，黃金資源也是非常缺乏的。$B$B這裡的西北面有一處金礦，我們需要礦坑裡的資源，但是那裡蜘蛛橫行，我們根本無法進去採掘金礦。我手上沒有人可以去完成這項任務，所以我們只有一步一步慢慢地來。去那裡看看吧，也許你能做些什麼……','執行官阿倫要你去殺掉8隻小夜行蜘蛛和5隻夜行蜘蛛。','','去提瑞斯法林地找喪鐘鎮的執行官阿倫。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (381,'zhTW','血色十字軍','得知我們在金礦的進展非常順利，你一定很開心吧?得益於你的幫助，我們終於可以把注意力放到別的事情上了。$B$B我的斥候報告說，一支血色十字軍的小分隊在東南方建立了營地。血色十字軍是一個卑鄙的組織，他們視我們為死敵，只要有一個不死生物─無論是巫妖王的爪牙還是我們被遺忘者─還活著，他們就不會停止追殺我們的行動。所以我們必須先發制人!$B$B你要多加小心，這些邪惡而狂妄的十字軍是一群非常危險的傢伙。','從血色信徒和血色新兵身上收集12枚血色十字軍臂環，把它們交給執行官阿倫。','','去提瑞斯法林地找喪鐘鎮的執行官阿倫。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (382,'zhTW','十字軍信差','布瑞爾那邊的上級發來給我的檔案顯示，有一個從血色修道院出發的血色十字軍斥候已經潛入了喪鐘鎮。有報告說這個人攜帶著非常重要的情報。至於更多的細節，我不得而知。但不管怎麼樣，我們必須得到這份情報!$B$B你是我眼前能配合調動的最適人選， $N 。找到那個信差，帶回你能取得的任何情報。','到十字軍營地去殺掉信差邁文·考加爾，將你發現的情報交給執行官阿倫。','','去提瑞斯法林地找喪鐘鎮的執行官阿倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (384,'zhTW','啤酒烤豬排','啤酒烤豬排是我的老主顧們最喜歡的大餐!問題是，為我提供豬排的獵手被國王徵募去打仗了。$B$B也許你能幫幫我?如果你可以給我弄六塊峭壁野豬肋排，外加一杯酒店裡賣的狂想麥酒的話，我就把祖傳的啤酒烤豬排的烹飪方法教給你，而且我還可以讓你免費品嘗我做出來的美食!秘密就在麥酒裡!','卡拉諾斯的拉格納‧雷酒需要4塊柔嫩豬肋排和1杯狂想麥酒。','','去丹莫洛找閃光嶺的拉格納·雷酒。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (385,'zhTW','捕獵鱷魚','很多獵人到洛克莫丹來都是為了捕獵這裡的鱷魚。總有一些商人專門尋找這種鱷魚皮，用它們來製作衣物或是護甲，還有些人則喜歡品嘗鱷魚肉。$B$B我們一直在進行這種貿易，但交易量並不是很大，因為鱷魚很兇猛，而且它們一般都盤踞在洛克湖中的小島上。嘿，別被我的話給嚇倒了，和鱷魚較量一番對你來說也是一種歷練。$B$B你看能不能...','收集5塊鱷魚肉和6張鱷魚皮，把它們交給遠行者小屋裡的馬雷克‧鐵心。','','去找洛克莫丹的馬雷克·鐵心。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (386,'zhTW','伸張正義','可怕的塔高爾是加塞爾佐格手下的一個高級殺手。他殺人的手法十分殘忍，即使以獸人的標準來看也是殘暴無比。那些為了保衛國家而奮勇作戰的戰士們落在他手裡都會被他折磨致死。這個惡棍現在被關在暴風城的監獄裡，被判處了死刑。不過，這件事情好像出了點小差錯。一個官僚習氣十足的貴族延遲了處死他的日期。我敢打賭這裡面一定有鬼。$B$B處死塔高爾吧， $N 。到暴風城的監獄裡去，在他玩出什麼把戲之前把他幹掉。','把塔高爾的頭顱帶給湖畔鎮的衛兵伯爾頓。','','去赤脊山找湖畔鎮的衛兵伯爾頓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (387,'zhTW','鎮壓暴動','我們必須把暴動給鎮壓下去!我需要你的幫助。如果外面的人知道監獄裡面已經失去了控制，我一定會丟了飯碗的!這是我所見過最無聊的鬧劇了。現在最重要的是逼迫這些囚犯投降，這樣才能保證暴風城的安全。$B$B叛亂的代價就是死亡。去殺掉一些囚犯，這樣叛亂才能得到控制!','暴風城的典獄官塞爾沃特要求你殺死監獄中的10名囚犯、8名罪犯和8名叛軍。','','去找暴風城的典獄官塞爾沃特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (388,'zhTW','鮮血的顏色','痛苦如同冰冷的河水一樣從我的血管中流過。我的孫子麥克是個多好的孩子呀，他只有14歲。當暴風城的軍隊被派往前線的時候，麥克也拿起了武器去守衛城市。他是監獄的守衛，那座監獄裡關押著許多迪菲亞兄弟會的成員。有一些囚犯們把他們的羊毛毯改織成他們組織的頭巾，麥克把這件事情上報了，結果他遭到了報復，被人從後面刺了一刀。$B$B我要報仇。給我帶回10條迪菲亞 $C 們的羊毛頭巾，像鮮血一樣殷紅的那種。','暴風城的尼科瓦·拉斯克要你取得10條紅色毛紡頭巾。','','去暴風城找舊城區的尼科瓦·拉斯克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (391,'zhTW','監獄暴動','讓我們把話挑明瞭說吧， $N :我不信任你。但是，現在的情況緊急，我也管不了那麼多了。$B$B你到下面去幹掉那個該死的斯瑞德，把他的腦袋砍下來帶給我。$B$B還有，如果你膽敢跟他合計什麼把戲，或者你不上來了的話……只要被我抓到你，就準備跟那群蛆死在一塊吧。','殺死巴基爾·斯瑞德，把他的頭帶給監獄的典獄官塞爾沃特。','','去找暴風城的典獄官塞爾沃特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (398,'zhTW','懸賞:蛆眼','懸賞:蛆眼!$B$B這只名叫蛆眼的豺狼人臭名昭著，即使是在它的同類眼中都顯得非常邪惡而污穢，它因為對被遺忘者們犯下了不可饒恕的罪名而被判處了死刑，這只卑鄙的野獸為巫妖王的軍隊偷盜了無數的屍體。上次有人看到蛆眼作惡是在布瑞爾北邊的加倫鬼屋。$B$B布瑞爾鎮將為執行這項判決的勇敢者提供一份高額的獎金。完成任務之後，請將這只野獸的爪子交給執行官塞加德。$B$B只有弱者才會有憐憫之心。','殺死蛆眼，並將他的爪子交給布瑞爾的執行官塞加德以換取酬勞。','','去提瑞斯法林地找布瑞爾的執行官塞加德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (404,'zhTW','腐爛的爪子','有一小撮天譴軍團的士兵已經滲入了提里斯法林地，在布瑞爾以西一帶的舊橋附近活動。$B$B到那邊去增援我們的部隊，擊退所有你見到的腐爛的死者和破碎的屍體。拆散他們的骨頭，然後把他們那腐爛的爪子給我帶回來，亡靈衛兵會獎勵你的。','給布瑞爾的亡靈衛兵迪林格爾帶回7隻腐爛的爪子。','','去提瑞斯法林地找布瑞爾的亡靈衛兵迪林格爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (408,'zhTW','家族墓穴','如今阿加曼德磨坊已經成了天譴軍團的一處重要據點，其中防守最為堅固的地方就是阿加曼德的家族墓穴了。天譴軍團的一個兵團就駐守在那裡，他們由一個名叫達高爾隊長的骷髏領導著。他們還利用某種通靈術復活了阿加曼德家族的死者們，並打算利用它們來對付我們。$B$B我們絕對不能允許這種事情發生，你必須阻止它。到阿加曼德家族墓穴去，戰勝那些還魂的阿加曼德家族的死屍們。$B$B還有，把達高爾隊長的顱骨也給我帶回來。','殺死8個哀嚎的鬼魂和8個腐爛的古屍。','','去提瑞斯法林地找布瑞爾的執政官塞弗倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (409,'zhTW','證明忠誠','你說你沒有被巫妖王控制住自己的思想，這一點已經由比索在我書上灌入的魔法證實了。但是，你仍然得先證明自己是天譴軍團的敵人，這樣我才會徹底相信你。$B$B在這座島嶼的南方海邊有一個古老而血腥的祭壇，由一個強大的天譴軍團斥候莉莉絲·奈法拉所佔據著。$B$B從我身邊的木箱裡拿出一根誘靈蠟燭，在祭壇上點燃蠟燭，莉莉絲就會醒來。消滅莉莉絲，我就相信你確實是巫妖王的敵人。','取得一根誘靈蠟燭。','','去提瑞斯法林地找十字軍前哨的岡瑟爾·阿坎努斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (412,'zhTW','協動齒輪','透過對諾姆瑞根現狀的進一步分析，我們發現不但那些該死的穴居怪沒有被消滅，反而有更多的地精變成了喪心病狂的、邪惡的麻瘋地精。$B$B我和奧齊希望用我們的最新發明「自動淨化器」來扭轉這種局面。這台機器即將大功告成，不過我們急需一些多檔齒輪和協動齒輪才能搞定最後的部分，請從諾姆瑞根的麻瘋地精那裡弄些過來吧。','收集6個多檔齒輪和6個協動齒輪，把它們交給卡拉諾斯的拉索·滑鏈。','','去找丹莫洛的拉茲·滑鏈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (416,'zhTW','補鼠行動','我們在西邊遇到了點麻煩。坑道鼠狗頭人在那裡的丘陵地帶建起了巢穴，把我們的土地弄得烏煙瘴氣!$B$B我們必須把他們給消滅掉。捕殺那些坑道鼠狗頭人，把他們的耳朵拿回來給我，我就會給你賞金。$B$B坑道鼠狗頭人最大的巢穴就在東邊的銀泉礦坑一帶。','收集12只坑道鼠的耳朵，把它們帶給奧加茲崗哨的巡山人雷矛。','','去洛克莫丹找灰爪山的巡山人卡德雷爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (417,'zhTW','駕駛員的復仇','莫里‧鐵鑽在他的日記中寫著，他遭到一頭名叫癩爪的巨型冰爪熊的攻擊。他趕走了這隻野獸，不過自己也已身受重傷。$B$B從莫里屍體上的傷痕判斷，癩爪一定在之後又回來殺死了他。$B$B無論如何，莫里在他的日記中寫下了他最後的遺願:$B$B殺死癩爪，為我復仇。','殺死癩爪。','','去丹莫洛找北門哨崗的駕駛員塞克·錘足。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (418,'zhTW','塞爾薩瑪血腸','塞爾薩瑪這兒饑腸轆轆的人可真不少，有跑進跑出的孩子，也有在挖掘場忙了一整天的工人。我們這兒有一道出名的菜色: 血腸，你大概還沒嘗過吧?$B$B沒有?在這兒要吃飯就得幹活，別以為你是個出色的 $C 就可以例外。$B$B我需要的只有熊肉，其他東西都已經準備好了。弄一些熊肉過來，煮飯的事就交給我維德拉好了!','收集8塊熊肉並交給塞爾薩瑪的維德拉‧壁爐。','','去洛克莫丹找灰爪山的維德拉·壁爐。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (421,'zhTW','證明你的價值','希瓦娜斯主人已經授命瓦里瑪薩斯大人全權負責征服南方的人類和矮人的領土。$B$B但阿魯高那個蠢貨─過去他是達拉然的大騙子，現在他是影牙城堡裡一隻中了詛咒的困獸─他那不計後果的魔法給銀松森林裡那座極具戰略意義的要塞帶來了一場大浩劫。$B$B我需要一些擁有優秀戰鬥技巧的人幫我把阿魯高留下的爛攤子給收拾掉。殺死5隻月怒白頭狼人以證明你的實力吧，這些野獸一般都在山腳下的道路兩旁遊蕩。','瑟伯切爾的達拉爾·織曦者要求你殺死5隻月怒白頭狼人。','','去銀松森林找瑟伯切爾的達拉爾·道恩維沃爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (422,'zhTW','阿魯高的愚行','阿魯高這樣一個施法能力比一張紙還要淺薄的傢伙居然能夠得到祈倫托的承認，這讓我實在難以想像。$B$B現在最重要的是，搞清楚阿魯高究竟使用了什麼魔法，這樣一來我才能對付他，並為黑暗女王平定銀松森林。$B$B阿魯高曾經住在橋北的麥田旁，一名亡靈哨兵回報說，他發現了阿魯高擁有的幾本法術書，但無法偷取它們。把其中一本名叫《阿魯高的拯救》的法術書從其他書裡找出來，並帶回來給我。','為瑟伯切爾的達拉爾·織曦者找回《阿魯高的拯救》。','','去銀松森林找瑟伯切爾的達拉爾·道恩維沃爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (423,'zhTW','阿魯高的愚行','在我研究過阿魯高的書以後，我最壞的設想不幸被證實了。祈倫托竟在那個連給達拉然的法師們掃屋子都不配的傢伙幹出那種愚昧行徑的時候完全不聞不問，一群蠢貨!$B$B阿魯高使用了附有魔法的物品來加強他薄弱的施法能力。我需要儘快研究一下這些物品。去殺掉一些月怒暴食者和月怒黑暗之魂狼人，收集他們身上帶著的魔法鐐銬供我研究之用。這些污穢的生物在北邊和東邊到處都是。','給瑟伯切爾的達拉爾·織曦者帶回6副暴食者鐐銬和3副黑暗之魂鐐銬。','','去銀松森林找瑟伯切爾的達拉爾·道恩維沃爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (424,'zhTW','阿魯高的愚行','看來想揭開隱藏在阿魯高所用的巫術中的黑暗秘密並不簡單，這比我想像中要花掉的時間多出很多。$B$B但與此同時，我需要你來幫忙處理一下我們的亡靈哨兵發現的一個小問題。似乎阿魯高的魔法已經控制了東南方山中的深埃連礦坑。$B$B這座礦坑對瓦里瑪薩斯大人的推進有著非常重要的意義。$B$B我希望你能幹掉礦坑裡的工頭，蒼白的格瑞姆森。只要他一死，礦坑就是我們的了。','殺死蒼白的格瑞姆森，把他的頭帶給瑟伯切爾的達拉爾·織曦者。','','去銀松森林找瑟伯切爾的達拉爾·道恩維沃爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (425,'zhTW','邪惡的伊瓦','我正在和哥哥奎恩執行偵察銀松森林的任務，並準備向高階執行官哈德瑞克復命。但我們進行得不太順利─我們穿過這座農莊的時候，被食屍鬼伊瓦襲擊了。$B$B我們從伊瓦那裡逃了出來，但他還是重創了奎恩。喝了你給他的藥水以後，哥哥正逐漸痊癒，但這段時間裡伊瓦仍可能會過來。$B$B殺死伊瓦，以保證奎恩有足夠的時間復原吧。伊瓦一般都躲在穀倉那裡，在我放鬆警戒的時候它就會開始行動。','殺死邪惡的伊瓦，並將伊瓦的頭顱帶給伊瓦農莊的蘭妮·尤瑞克。','','去找銀松森林的蘭妮·尤瑞克。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (426,'zhTW','磨坊告急','天譴軍團正試圖在阿加曼德磨坊那邊建立起一座前哨基地。如果他們得逞了，那麼他們在提里斯法的軍事行動將得到有利的支援。$B$B上頭已經發話下來了，必須將磨坊那邊的天譴軍團勢力全部清除乾淨。$B$B到磨坊那邊去，從斷骨士兵和碎顱士兵身上收集凹槽肋骨，再從暗眼骸骨法師身上收集焦黑的顱骨。$B$B你只需沿著道路一直向西走，過橋以後在第一個岔路口轉向北就行了。當你看到風車的時候，戰鬥隨時都會開始。','收集5根凹槽肋骨和3個焦黑的顱骨，然後向布瑞爾的亡靈衛兵迪林格爾回報。','','去提瑞斯法林地找布瑞爾的亡靈衛兵迪林格爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (427,'zhTW','與血色十字軍的戰爭','執行官亞倫大人提供給我們的資料中正是我們與那些卑劣的血色十字軍進行的戰爭中所要的突破點。我們現在知道他們在整個提里斯法林地的確切位置了。$B$B但亡靈衛兵還有其他更艱鉅的任務，巫妖王的軍隊每個夜晚都在逐漸的壯大著。我們需要一些像你這樣的志願者來把那群血色十字軍送進墳墓。$B$B順著鎮外的道路向西走，穿過索利丹農場到廢塔那裡去，殺死10名血色十字軍戰士。以此來證明你有足夠的能力為黑暗女王陛下服務。','布瑞爾的執行官塞加德要求你去殺掉10名血色十字軍戰士。','','去提瑞斯法林地找布瑞爾的執行官塞加德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (429,'zhTW','荒野之心','我的哥哥奎恩被食屍鬼伊瓦打成了重傷，我不知道在沒有魔法幫助的情況下，他是否還能痊癒。儘管我不是一個藥劑師，但我知道我們的藥劑師能用變色的狼心製作治療藥水。$B$B幫我收集一些心臟並帶給南邊墳場的藥劑師倫弗利爾，然後把做好的藥水帶回來。$B$B這附近和東邊的瑪爾丁果園之間有不少座狼在到處遊蕩。','收集6顆變色的狼心，把它們交給瑟伯切爾的藥劑師倫弗利爾。','','去銀松森林找瑟伯切爾的藥劑師倫弗利爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (432,'zhTW','該死的穴居怪!','那些該死的穴居怪，他們把我的工作地點變成了一片廢墟!看那裡，又一個火藥桶!$B$B啊啊啊啊啊，我真想鑽到地底下去扭斷他們那豆芽一樣的脖子!我要把他們趕盡殺絕!$B$B即使這樣也無法消除我的憤怒...他們留給了我什麼?什麼也沒有!$B$B我要親手殺了他們，不過我的胳膊已經不再那麼有力了!到採石場去，幹掉那幫該死的傢伙!我會獎賞你的!只要你去幹掉他們!','在古博拉採掘場裡殺死8個石齶擊顱者和8個石齶斷骨者。','','去找丹莫洛的工頭喬尼·石眉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (433,'zhTW','公僕','作為參議院與探險者協會的一員，我決定負責調查這個採石場的情況。穴居怪發瘋了!$B$B他們把古博拉採掘場搞了個天翻地覆。當我們挖掘礦石的時候，他們突然出現，毀壞了我們的設備，將我們許多的礦工困在地底。$B$B我們必須把礦工救出那裡。我讓一群法師日以繼夜地製作這些歸來符文。如果你能將它們帶去給受困的礦工，他們就能安全回到地面了。','到古博拉採掘場裡去，將歸來符文交給7名受困的礦工。','','去找丹莫洛的參議員梅爾·聖石。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (435,'zhTW','護送埃蘭德','外面的狼群看來是不想離開了，而且我每次走出屋子的時候，它們都惡狠狠地盯著我。這些野狼顯然是餓極了，它們把我當成了大餐!$B$B我得通知我的隊友，亡靈哨兵蘭妮·尤瑞克。也就是說，我要到她那裡去，得先找人幫我搞定這群狼。$B$B請護送我吧!不過，這邊的狼也實在是多了點，如果你還有別的朋友的話…再好不過……','護送亡靈哨兵埃蘭德避過群狼，直到他找到蘭妮·尤瑞克。','埃蘭德必須到達蘭妮·尤瑞克身邊','去找銀松森林的蘭妮·尤瑞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (437,'zhTW','亡者農場','我們在銀松森林的斥候回報說，腐皮豺狼人在北邊一處叫做亡者農場的地方建立了一個基地。我們曾經派遣了一小隊突襲隊去對付他們，但他們每次都會得到女妖奈塔拉什的支援，我們的部隊每次都被她的魔法所擊潰。$B$B我們必須殺掉奈塔拉什。$B$B到亡者農場去突襲那裡的腐皮豺狼人。如果沒有看到奈塔拉什的話，就繼續屠殺腐皮豺狼人直到她出現為止，然後擊敗她。$B$B她的靈魂將會變成塵土。把這些塵土帶回來，作為你殺死她的證明。','殺死亡者農場的腐皮豺狼人。','進入亡者農場。','去銀松森林找瑟伯切爾的高階執行官哈德瑞克。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (442,'zhTW','突襲芬里斯島','現在是把天譴軍團徹底趕出銀松森林的時候了。$B$B你必須再去一次那個島，殺死圖勒·鴉爪，把他的頭顱提來見我!$B$B這個任務非常危險，但是你也應該知道它的重要性， $N 。所以你只能成功，不能失敗。','將圖勒的頭顱帶回給瑟伯切爾的高階執行官哈德瑞克。','','去銀松森林找瑟伯切爾的高階執行官哈德瑞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (443,'zhTW','腐皮豺狼人的膿液','在我們對芬里斯島展開一次突襲行動之前，我們必須得弄清楚誰是腐皮豺狼人背後的真正主人，我們的藥劑師們相信它們的體內發生了某種神秘的變化。$B$B到破舊渡口東邊的芬里斯島去，收集一些腐皮豺狼人身上流出的膿血，然後把膿液交給瑟伯切爾外的藥劑師倫弗利爾。','給瑟伯切爾的藥劑師倫弗利爾帶去8瓶腐皮豺狼人的膿液。','','去銀松森林找瑟伯切爾的藥劑師倫弗利爾。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (447,'zhTW','致命配方','阿薩斯的手下越來越多。不過，只要再來一次新的瘟疫，我們就可以一勞永逸地同時根除天譴軍團和人類。$B$B我的研究已經證明，將灰熊心臟中提取出的毒素和蜘蛛血混合在一起，就可以製成一種致命的毒藥。從西北方的粘絲洞中的蜘蛛身上和銀松森林中遊蕩著的熊身上採集一些樣本回來，然後把它們送給幽暗城皇家藥劑師學會裡的藥劑大師法拉尼爾。','收集6個灰熊的心臟和6份粘稠的血液樣本，並將這些東西送給幽暗城的藥劑大師法拉尼爾。','','去找幽暗城鍊金房的大藥劑師法拉尼爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (450,'zhTW','致命配方','其實你還能為皇家藥劑師學會再做一些事情， $N 。$B$B當初阿魯高在整個森林中施展了他那可惡的魔法時，我們當中一位最有前途的成員─藥劑師博拉爾德，也被他詛咒了。現在博拉爾德已經變成了一個忠於阿魯高的傀儡，換句話說，他對我們已經徹底沒用了。但是他的研究成果可能對我們非常有用，因為他在多年以前曾經研究過一種殺死了洛丹米爾湖中所有生物的瘟疫。$B$B將伯納德的日記從他在焚木村旅店中的研究室裡偷出來，然後把日記交給藥劑師倫弗利爾。','從焚木村的旅店中找到伯納德的日記，把它交給瑟伯切爾的藥劑師倫弗利爾。','','去銀松森林找瑟伯切爾的藥劑師倫弗利爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (451,'zhTW','致命配方','根據博拉爾德的研究日記，採自湖岸蠕行者和潛藏者身上的苔蘚會對我們製造出這種瘟疫大有助益。這些野獸就棲息於東邊的洛丹米爾湖中的群島上。$B$B他還提到曾在一隻邪鰭魚人身上發現了一種非常稀有的硬瘤，顯然這種瘤很難得到，博拉爾德也只找到了一個。$B$B收集一些苔蘚和那種稀有的瘤，把它們帶給幽暗城的藥劑大師法拉尼爾。','收集6份湖岸蠕行者苔蘚的樣本、6份湖岸潛藏者苔蘚的樣本和1塊硬瘤，把它們交給幽暗城的藥劑大師法拉尼爾。','','去找幽暗城鍊金房的大藥劑師法拉尼爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (455,'zhTW','丹奧加茲告急','龍喉氏族的獸人在濕地有了一處巢穴，現在他們的勢力已經快擴展到丹奧加斯了!我們可絕不能讓他們在這裡立足，不然，我們在濕地唯一的港口與要塞─米奈希爾港與洛克莫丹的聯繫將會被切斷。$B$B穿越丹奧加茲到濕地那邊去，向米奈希爾港的瓦斯塔格·鐵齶報到，路上順便殺它幾個獸人玩玩!$B$B米奈希爾就在丹奧加茲的另一邊，只要先順著路向北，然後在岔路口轉向西邊就是。$B$B我們寄希望於你， $N 。可別讓我們失望。','翻越丹奧加茲。','翻越丹奧加茲','去濕地找米奈希爾港的瓦斯塔格·鐵顎。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (456,'zhTW','自然的平衡','你好， $N 。我是管理員伊爾薩萊恩。我的職責是維護幽影谷一帶的自然平衡。$B$B今年的春雨似乎比往年來得都要連綿不絕，這導致了森林中某些動物的過度繁殖，而其他動物就遭了殃。$B$B其中，夜刃豹和草刺野豬的族群已經過於龐大了，幽影谷無法為它們提供更多的食物。去吧，年輕的 $C ，去減少野豬和夜刃豹的數量，以保證自然的和諧。','殺死3隻小夜刃豹和3隻小草刺野豬。','','去泰達希爾找幽影谷的管理員伊爾薩萊恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (457,'zhTW','自然的平衡','削減幽影谷中幼獸的數量是一個很好的開始， $N ，但這還遠遠不夠。$B$B如果問題不能得到根本解決的話，森林中的資源還是很快就會被耗盡的。為了所有共享這片大地的生物著想，殺死野生的獸類是一件必要之惡。進入幽影谷的東北方，為了自然的平衡，清除一些癩皮夜刃豹和一些草刺野豬。','殺死6隻癩皮夜刃豹和6隻草刺野豬。','','去泰達希爾找幽影谷的管理員伊爾薩萊恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (459,'zhTW','惡魔小偷','惡毒的小劣魔!他們又從我們的食物店裡偷東西。$B$B如果你不介意幫個忙，他們偷走的東西一定是散落在整個西邊的劣魔營地裡。如果你能把它們全部帶回來給我，我將會非常樂意地給你報酬。','找回德黎菈被偷走的豆子、德黎菈被偷走的水和德黎菈被偷走的袋子。','','去泰達希爾找幽影谷的塔琳德拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (464,'zhTW','龍喉旌旗','按理說，龍喉氏族的獸人應該已經在第二次獸人戰爭中全部被消滅乾淨了呀。那時，他們失去了對紅龍的控制，而被奴役了許久的紅龍對獸人極度仇恨，所以就到處獵殺他們。只有一小部分龍喉獸人從格瑞姆巴托逃了出來，躲進了維爾加挖掘場東邊的山裡。$B$B現在他們的族群似乎又恢復了興盛，有線報說他們在米奈希爾的東北方建立了一座營地。$B$B我們要你去進攻那座營地，並帶回一些旌旗作為功勳評定的證據。','給斯托菲隊長帶回8面龍喉旌旗。','','去濕地找米奈希爾港的斯托菲隊長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (466,'zhTW','火岩礦石','我聽說最近在濕地一帶發現了一種特別稀有的礦石，大家管它叫火岩，那礦坑就在奧加茲隘口西北方的一處洞穴裡。火岩礦石非常不穩定，它很容易爆炸，但我敢說，如果加工方法正確的話，它就可以用來製作威力強大的砲彈!$B$B給我搞一些火岩礦石的樣本來，我可以去找個夠膽的傢伙來對它進行實驗。$B$B哦，要想採集到這些礦石的話，你可得懂點採礦技術才行。如果你完全不懂的話，那麼……就找個懂行的朋友一起去吧!','給丹莫洛的駕駛員迪恩·石輪帶回6份火岩礦石。','','去丹莫洛找鋼架補給站的駕駛員迪恩·石輪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (470,'zhTW','搜尋軟泥怪','我每週都要去鐵鬚之墓做例行的拜訪。然而，上次過去的時候，我竟然遭到了那些可怕的軟泥怪的攻擊，我當時自然是嚇壞了。$B$B我身上也沒帶武器，只好抓起背包丟它們，不過那完全沒有用!軟泥怪很輕鬆地把我的背包給吞掉了……不過，幸運的是，這也為我爭取到了逃跑的時間。$B$B但是我現在很需要背包裡的東西!$B$B我已經忘記把包扔進哪隻軟泥怪裡了，它們看起來都是一模一樣的!所以呢，你恐怕得多殺個幾隻才能找到我的背包。鐵鬚之墓就在東北方，丹奧加斯附近。多謝你啦!','鐵鬚之墓中的某隻軟泥怪身上有塞達的背包，奪回背包，把它送還給米奈希望港的塞達。','','去濕地找米奈希爾港的塞達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (471,'zhTW','學徒的職責','我把我的學徒派到了沼澤那邊去，希望他能給我搞到一些著名的巨型鱷魚的皮回來。然而他一直都沒回來，我只好親自去找他……怎麼說呢，反正我當時看到了一些比較慘的場面。$B$B醫生說他很快就會恢復健康的，但現在，我仍然急需鱷魚皮!$B$B……要是你能幫我殺幾條這種兇猛殘忍的大鱷魚，從它們身上給我剝幾張皮下來，我會非常高興的。沿著海岸北上，走過了那些魚人搭建的簡陋小屋之後就能找到鱷魚了。','為米奈希爾港的詹姆士·哈洛倫帶回6張巨型鱷魚的皮。','','去濕地找米奈希爾港的詹姆斯·哈洛蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 474 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (474,'zhTW','擊敗納克羅什','現在所有的投石車都被燒掉了，找到納克羅什酋長，把他幹掉。','殺掉納克羅什酋長。','','去濕地找米奈希爾港的斯托菲隊長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (479,'zhTW','調查安伯米爾','達拉爾正在嘗試著定位出達拉然巫師們施法時的能量流向。現在，我們必須要盡我們一切努力來暫緩他們的進程……$B$B那些咒術師、法師和保衛者恐怕會拼死保護墜飾。你必須清除掉這些阻礙，並把飾物搶到手。$B$B沿著大路向南走，在岔路口轉向東邊就可以到安伯米爾了。','為瑟伯切爾的暗影牧師奧利斯特搶到8個達拉然墜飾。','','去銀松森林找瑟伯切爾的暗影牧師奧利斯特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (480,'zhTW','法師的頭領','一位具有強大法力的大法師正在監管著啟動節點的行動。在目前的形勢下，我們只有殺死那個大法師才有可能阻止他們了。這將是個艱鉅的任務，無疑會有許多法師與守衛層層護衛著他。$B$B你必須出發了，儘快結果掉他。大法師死了以後，把他的法杖帶回來給我。現在就去，快!','殺死達拉然大法師，並把他的法杖交給瑟伯切爾的暗影牧師奧利斯特。','','去銀松森林找瑟伯切爾的暗影牧師奧利斯特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (483,'zhTW','喚醒聖物','瘤背部族的熊怪正在西邊山丘的班奈希爾獸穴肆虐。$B$B除非我們伸出援手，否則那些正在沉睡的德魯伊將永久地陷於翡翠夢境中，對即將降臨的噩運渾然不覺。只有拿到所有的喚醒聖物，我們才能將休眠儀式打斷。$B$B到獸穴裡去幫我找回鴉爪神符、黑色羽毛、天藍寶石和築巢符文。德魯伊們把這些聖物藏在神聖的箱子裡，把它們帶給我，我要準備進行喚醒儀式。','尋回喚醒聖物。','','去找泰達希爾的阿斯瑞達斯·熊皮。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (484,'zhTW','小鱷魚皮','我是皮匠詹姆士·哈洛倫。我用鱷魚皮做東西的手藝可是艾澤拉斯第一流的，每天都有大船把我的產品一箱一箱地運到世界各地的港口去。$B$B你見過埃納爾了吧?他也是專門為我提供新鮮鱷魚皮的諸多獵人之一。$B$B最近我這裡的小鱷魚皮供應量在直線下降，鑒於目前我真的很缺貨，如果你能幫我弄些小鱷魚皮回來，我會給你開出一個非常不錯的價碼。你可以在鎮外的沼澤裡找到那種小鱷魚。','為米奈希爾港口的詹姆士·哈洛倫帶回4張小鱷魚皮。','','去濕地找米奈希爾港的詹姆斯·哈洛蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (486,'zhTW','『大槌』烏薩爾','現在我們要去解救猛禽德魯伊了。如果我們失敗，他們將永遠迷失於夢境中。$B$B我將做好甦醒儀式的準備。為了進行這個儀式，必須殺死造成現在這種混亂局面的罪魁禍首。$B$B干擾我們同胞呼喚的就是『大槌』烏薩爾，只有讓他為此付出代價，猛禽德魯伊才能重獲自由。順著道路往西北方，找到往北方進入山崖的小徑。烏薩爾的巢穴就在那兒。','殺掉『大槌』烏薩爾。','','去找泰達希爾的阿斯瑞達斯·熊皮。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (487,'zhTW','達納蘇斯之路','我們必須保證通往達納蘇斯的道路的安全。有報告說，路上的旅人經常受到腐化瘤背熊怪的殘忍襲擊。$B$B每天都有無數來自達納蘇斯的重要資訊在這條路上進行傳遞，因此我們絕不能容忍有這幫腐化熊怪恐嚇無辜的旅者。$B$B以神聖森林的名義拿起武器， $C 。熊怪們的巢穴就在北方道路的另一端。去殺死這些瘤背伏擊者再回來向我報告。','殺掉8個瘤背伏擊者。','','去找泰達希爾的哨兵阿瑪拉·夜行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (488,'zhTW','賽恩的要求','我知道你渴望工作，對你來說今天是個幸運的日子，因為我只能靠你這個乳臭未乾的 $C 來幫忙了。$B$B你知道， $N ，我可以使你非常幸福。我可以讓你擁有你從未想過的好東西。但是首先，你必須給我帶些東西來。$B$B我在森林裡的工作需要一些...材料。給我拿來夜刃豹的牙齒、巨翼梟的羽毛和樹林蜘蛛絲。$B$B這是我們的小秘密， $R 。','給多蘭納爾外面的賽恩‧腐蹄帶去2顆夜刃豹的牙齒、2根巨翼梟的羽毛和2份樹林蜘蛛絲。','','去找泰達希爾的賽恩·腐蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (489,'zhTW','尋求救贖!','森林議會聽說你幫助了賽恩‧腐蹄，這個險惡的薩特是森林的敵人。作為一個 $R ，你應該更清楚我們不能殺害自然的生物，玷污聖潔的森林。$B$B如果你希望繼續做泰達希爾的朋友的話，你就必須在眾人的關注下挽回這個過錯。$B$B給賽恩‧腐蹄一個教訓，你就可以得到原諒。魔錐果是從樹上掉落的腐壞的種子，一般都冒著綠色的煙氣。$B$B給賽恩帶去3個魔錐果，他會以為那些只是無害的點心。','收集3個魔錐果。','','去找泰達希爾的賽恩·腐蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (496,'zhTW','受難藥劑','唉，又在塔倫米爾度過了倒楣的一天。這裡的新鮮空氣讓我渾身都不舒服， $N 。$B$B我們最好早點給這些人類下毒。我一直在仔細研究我的藥物裡可能用到的致命藥劑。$B$B如果你想幫忙的話，就給我收集這些東西:10個灰熊的舌頭，還有非常稀少罕見的食苔蛛的毒液。塔倫米爾周圍到處都是熊和食苔蛛。','塔倫米爾的藥劑師林度恩要你去收集10個灰熊的舌頭和一些食苔蛛的毒液。','','去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (500,'zhTW','破碎嶺巨魔','破碎嶺巨魔在奧特蘭克城廢墟附近的山上挖了一座小丘。我的斥候告訴我，他們現在還佔領了那片遺跡。$B$B我們可不能讓他們在那兒享福，一旦他們覺得在那兒生活很安全，下一步就會轉移到丘陵地帶，然後就是我們南海鎮了!$B$B到北方的奧特蘭克山去獵殺幾個巨魔。把他們那骯髒的指節骨帶回來，我會給你獎賞的。','從奧特蘭克山的破碎嶺巨魔身上收集9個骯髒的指節骨，把它們帶給南海鎮的治安官雷德帕斯。','','去希爾斯布萊德丘陵找南海鎮的治安官雷德帕斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (501,'zhTW','痛苦藥劑','哦， $N ……希爾斯布萊德的花都開了，空氣這麼清新，讓我不得不沉湎在這種痛苦之中。我從骯髒的窗子裡望出去，渴望著那一天早點到來，讓整個世界都感染上新的瘟疫，讓他們得到應有的報應。$B$B我喜歡整天坐在這裡思考，而現在黑暗女王賦予我的使命正在召喚我，請你幫幫我吧。我的研究表明，山地獅的血液可以製作出最棒的毒酒來。給我找一點來，讓我們做點有趣的事吧。','收集10瓶山地獅的血液，把它們交給塔倫米爾的藥劑師林度恩。','','去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (504,'zhTW','破碎嶺好戰者','你已經和破碎嶺巨魔打過交道了，現在我要你去好好教訓教訓他們……$B$B到奧特蘭克遺跡去獵殺那些破碎嶺好戰者。我希望你多幹掉一些─只有這樣才能讓這幫畜生離聯盟的領土遠一點。','殺死10個破碎嶺好戰者，然後回南海鎮向治安官雷德帕斯報告。','','去希爾斯布萊德丘陵找南海鎮的治安官雷德帕斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (505,'zhTW','辛迪加刺客','我是南海鎮的新鎮長，前一任鎮長被刺殺之後，我剛剛上任。那些刺客一直都沒有找到，不過據我們調查，幾乎可以肯定他們是由辛迪加雇傭的─辛迪加是一個由邪惡的貴族掌管著的 $C 組織，而那些貴族則是已經陷落的奧特蘭克王國的遺老遺少。$B$B辛迪加在索菲亞高地及考蘭之匕各設有一個營地，就位於部落佔據的塔倫米爾的北方及西方。殺掉所有你在這些營地看到的辛迪加成員。','殺死12個辛迪加劫匪和8個辛迪加盜賊，然後回到南海鎮向赫尼·馬雷布鎮長報到。','','去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (512,'zhTW','貴族之死','我擔心辛迪加的幕後首腦想要毀滅南海鎮，因此我們必須在他們的計畫得以實現之前幹掉這些頭目。$B$B你去北邊奧特蘭克山裡的斯坦恩布萊德廢墟調查一下，我們覺得那裡是辛迪加的指揮部。$B$B我們知道這幫刺客是以前的奧特蘭克貴族指使的，貴族們可能會打扮成普通辛迪加密探的樣子，不過通過他們手上戴著的徽記之戒就能很容易地判斷他們是不是貴族了。$B$B把他們的璽戒給我拿來。','為南海鎮的赫尼·馬雷布鎮長收集7個奧特蘭克璽戒。','','去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (516,'zhTW','博倫的巢穴','我收到報告說，一群天譴軍團的不死生物正在附近集結，準備對我們進行一次襲擊。既然得到了這樣的情報，我們就本應該先下手攻擊他們，把他們的計畫粉碎在繈褓中才對。$B$B但不幸的是，我的情報十分有限，只知道他們在一個名為博倫的巢穴的山洞裡集結。確切的位置我也不清楚，但應該在安伯米爾附近的山區中。$B$B我相信以你的能力和才智，一定可以找到他們，幹掉他們。','找到博倫的巢穴，殺死6名鴉爪苦工和6名鴉爪守護者，然後向瑟伯切爾的暗影牧師奧利斯特彙報。','','去銀松森林找瑟伯切爾的暗影牧師奧利斯特。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (523,'zhTW','男爵之死','你找到的契約是瓦杜斯男爵簽署的，他是以前的奧特蘭克王國的貴族，並且一向以冷酷和殘暴而著稱。這件事的背後由瓦杜斯這樣的人主使，我對此一點也不感到奇怪。$B$B去找到他，讓他受到正義的制裁。他一定在辛迪加經常出沒的地方活動，也許在斯坦恩布萊德的廢墟，也許在廢墟北面的山谷裡。','把瓦杜斯男爵的頭帶給南海鎮的赫尼·馬雷布鎮長。','','去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (530,'zhTW','丈夫的復仇','瓦德雷曾經是我的好朋友，但他也是殺害我妻子的兇手。雖然我已經不知道悲傷為何物了，但我復仇的念頭卻一直沒有改變。去幫我殺了瓦德雷，把他那雙邪惡的手帶給我，我會獎賞你的。$B$B我最後一次聽到他的消息時，他正準備從銀松森林南部的葛雷邁恩之牆逃往吉爾尼斯王國。','殺掉瓦德雷·莫萊。','','去找洛丹倫廢墟的拉林夫·安迪恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (536,'zhTW','清理海岸','我從暴風城守衛被調到這個鳥不生蛋的南海鎮來做守衛，這鎮子簡直是一無是處……整日整夜都是一股魚腥味。$B$B更別提治安官雷德帕斯了……他還想要我去對付那幫魚人，哈!$B$B我很難打起精神去跟西部海岸上的那群奇形怪狀的魚人作戰。如果你願意替我去幹掉它們，我會很感激你的。','南海鎮的法爾林·奧里涅爾中尉要你去殺掉10個碎鰭獵潮魚人和10個碎鰭神諭者。','','去希爾斯布萊德丘陵找南海鎮的法爾林·奧裡涅爾中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (537,'zhTW','黑暗議會','你拿來的信是一個自稱為納伽茲的人寫的，他是阿古斯覺醒的一員。我不知道這個阿古斯覺醒是個什麼樣的組織，不過如果他們和辛迪加是一夥的話，就是我們的威脅。$B$B我要你去查查這封信上提到的納伽茲和阿古斯暗影法師。找到他們，把他們幹掉。$B$B去高地看看，那裡是辛迪加的勢力範圍，就在斯坦恩布萊德的北面。$B$B如果運氣夠好的話，你就能在那兒找到這些阿古斯覺醒的特使。','殺死4個阿古斯暗影法師。','','去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (555,'zhTW','海龜湯','關於南海鎮，你最需要瞭解的是我們這兒有暴風城以北地區最好的美食!$B$B比如說我的秘密食譜:海龜湯。我聽說曾有人遠從夜色鎮趕來這裡，只為品嘗一碗海龜湯!不過我最近一直都沒做過這種美食。我曾經從達拉然一直走到洛丹米爾湖去捕獵鉗嘴龜，不過現在實在不是外出冒險的時候。如果你從北邊那條河里弄點鉗嘴龜身上的海龜肉來給我，我就能很快做出點海龜湯來讓你大飽口福。','給南海鎮的廚師傑森帶去10塊海龜肉。','','去希爾斯布萊德丘陵找南海鎮的廚師傑森。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (559,'zhTW','法爾林的證據','你相信嗎， $N ?雷德帕斯對咱們殺了那麼多魚人還是不滿意─哦，別謙虛了，你在這方面還挺有本事。現在他又要我證明我真的殺過魚人，他要我把那些冰涼的、粘糊糊的魚人的頭給砍下來讓他過目，這樣我才能得到他的肯定。','南海鎮的法爾林·奧里涅爾中尉要你從西部海岸的魚人身上收集10顆魚人的頭顱。','','去希爾斯布萊德丘陵找南海鎮的法爾林·奧裡涅爾中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (562,'zhTW','升官之道','我以前在暴風城的導師發來消息告訴我聯盟的高級將領已經開始關注納迦帶來的威脅了。根據他打聽來的消息，任何人在這方面有所表現的話，都很有可能得到提拔，或者至少是調動工作崗位。$B$B不過有一個小問題……我對付不了納迦， $N 。哦，當然，我能阻止酒吧裡的醉漢互相爭吵，也能拖走好鬥的乞丐，不過納迦對我來說就太難對付了。你一定得幫我這個忙， $N 。','南海鎮的法爾林·奧里涅爾中尉要你去殺掉10個刺脊灘行者和10個刺脊海妖。','','去希爾斯布萊德丘陵找南海鎮的法爾林·奧裡涅爾中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (564,'zhTW','損失慘重','沒有什麼事比失去這些駿馬更讓我煩心了。相信我，就是那些討厭的不死生物、可惡的辛迪加惡匪和其他害人的東西在這一帶到處遊逛，殺了我們不少的馬匹。$B$B不過我可以對著我爺爺的墓碑發誓，對這些馬匹威脅最大的還是奧特蘭克上的山地獅。它們總是從山上跑下來給我搗亂!$B$B你覺得自己是個英雄?那就去做點什麼來證明吧!','南海鎮的達倫·瑪爾維要你殺掉8隻山地獅和10隻巨型山地獅。','','去希爾斯布萊德丘陵找南海鎮的達倫·瑪爾維。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (565,'zhTW','巴圖羅的雪人毛皮披風','我，偉大的巴圖羅，將為你做一件聞名世界、全聯盟皆知的雪人毛皮披風!$B$B不信你就到處跑跑看，能不能再找件更棒的。每個人都會說:「巴圖羅，沒有比這更好的披風了!」當然，當然沒有。$B$B巴圖羅需要一個毛布卷，一件由技藝高超的製皮師縫製的山地披風，一股細線，當然還要有雪人的毛皮!把這些東西帶給我，我就讓你看看我的本事!','給南海鎮的巴圖羅·吉塞提找一個毛布卷、一件山地披風、一股細線和10塊雪人的毛皮。','','去希爾斯布萊德丘陵的南海鎮找巴圖羅·吉塞提。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (574,'zhTW','特種部隊','如今我們已經在很大程度上削弱了他的正規部隊，但這就意味著你得直接去面對他手下的精銳部隊。如果那些傢伙沒有被派出去襲擊我們落單的士兵的話，他們就應該駐紮在庫爾森營地後山上一處名為「儲藏室」的洞穴裡。$B$B我私下裡認識許多庫爾森的手下，他們都是身經百戰的老兵，對庫爾森忠心耿耿，而且最要命的是，他們對敵人毫不手軟。這對你來說恐怕不是個簡單的任務， $N 。多加小心。$B$B你戰勝了他們以後，就去向我的長官多倫中尉覆命吧。','殺掉10名庫爾森特種兵和6名庫爾森精神醫師。','','去荊棘谷找反抗軍營地的多倫上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 575 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (575,'zhTW','供與求','「前無古人，後無來者，南海一帶最好的也是世界最好的皮匠。」他們就是這麼叫我的。我!崔斯里克!最好的皮……呃，好吧。$B$B我的皮貨以品質優質而遠近聞名，都是鑒賞家們的首選之物!$B$B我最近收到了來自技工協會雷德沃克斯主管的訂單，他需要十二雙刨花皮靴。啊，就是那種由我製作的、非常搶手的靴子。$B$B不過要想做那種靴子的話，我需要一些鱷魚皮才行。在荊棘谷北邊的河邊有很多鱷魚，你看能不能……','收集2張淡水鱷的皮，把它們交給藏寶海灣的崔斯里克。','','去荊棘谷找藏寶海灣的崔斯里克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (576,'zhTW','海盜的眼睛','站住!誰在那邊?$B$B啊，如果沒有那隻特製的魔法眼，我就是個廢人了。當初在一次戰鬥中，我失去了我的眼睛!但幸運的是，我們的船停靠在米奈希爾港時，一位旅行巫師送給了我一隻特製的玻璃眼，這樣我才又能看見東西了。$B$B不過昨天晚上我參加了襲擊血帆海盜的行動，在跳出船的時候玻璃眼睛不小心給弄丟了。一定是那幫血帆海盜拿走了我的眼睛!看來他們這群混蛋已經找到了到藏寶海灣來的路。$B$B你能不能幫幫我這個老海盜，把我的眼睛給找回來?','藏寶海灣的獨眼迪茲要求你從血帆海盜那裡找回他的眼睛。','','去荊棘谷找藏寶海灣的獨眼迪茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 577 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (577,'zhTW','收集鱷魚皮','嗯，這些靴子已經基本定型，接下來就要開始打磨表面了。但你帶來的皮似乎少了點，做不出足夠的鞋墊來。$B$B「那現在我們得幹什麼呢，崔斯里克?」你肯定會馬上問這種問題，哈哈，你跟崔斯里克說話可真不幸啊，因為我馬上就要給你派活幹啦!$B$B沒人會去觀察鞋墊的，所以我們只要找點又厚又便宜的鱷魚皮就行了。納菲瑞提湖旁邊的那種鉗嘴鱷魚就不錯。','給藏寶海灣的崔斯里克帶回5張鉗嘴鱷魚的皮。','','去荊棘谷找藏寶海灣的崔斯里克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (578,'zhTW','海潮之石','如果個島上確實有水元素和哥布林法師的鬼魂的話，也就是意味著在那裡可以采到海潮之石!$B$B我希望你能找到這座鬧鬼的島嶼，去看看上面到底是怎麼回事。哦，如果你想知道更多的有關海潮之石的資訊的話，可以帶著這張憑證去暴風城圖書館，他們會幫你找到我最初讀過的那本傳說的手抄本。$B$B真的是加茲班首先發現那種石頭的嗎……?','為藏寶海灣的大財主里維加茲找到鬧鬼的島嶼。','找到鬧鬼的島嶼','去荊棘谷找藏寶海灣的大財主裡維加茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (580,'zhTW','威士忌·狡黠所遺失的烈酒','我們那天喝醉了，結果從很遠的辛特蘭那邊掉下了船，活活地漂到望海崖這裡來，差點餵了魚。$B$B而且我斯利姆從小就不怕水!我們船長從一艘去暴風城的私掠船上搶來了一箱紫葡萄酒。$B$B我們在辛特蘭被風暴襲擊的時候，我東倒西歪地撞碎了那個木箱，結果那裡面的酒在大風大浪裡全都掉進海裡了。我要是不把它們給找回來的話，船長見了我非拿我餵貓不可!幫幫我吧!','藏寶海灣的威士忌·狡黠想要你幫他找回弄丟的紫葡萄酒。','','去荊棘谷找藏寶海灣的威士忌斯利姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (583,'zhTW','歡迎來到叢林','歡迎來到荊棘谷!$B$B也許你不知道，但那邊的那位矮人就是聯盟一位偉大的戰爭英雄，出名的野獸獵人赫米特‧奈辛瓦里的兒子。如同他父親一樣，他並不歡迎陌生人來他的營地，不過你看起來像是見過大世面的 $C 。$B$B作為一位久經沙場的老將，奈辛瓦里大人總是很關心你們這樣的小輩。$B$B去和他談一談吧。他和父親十分酷似，所以或許他能教你些狩獵的技巧。','與小赫米特‧奈辛瓦里談話。','','去荊棘谷找奈辛瓦里遠征隊營地的赫米特·奈辛瓦里二世。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (587,'zhTW','鼻煙','啊，海上的生活。我不想說這種生活有多美好，但這就是我的生活。$B$B當我每次入港的時候，我都會找個地方好好喝上一杯，再找點高品質的鼻煙抽抽。壞習慣吧，但海賊們怎麼能沒有壞習慣呢，對吧?$B$B所以你可以想像一下，當我發現鎮上的草藥師賣完了他的全部鼻煙並且已經離開了這座小鎮的時候，我會有多沮喪有多傷心了!據說給他運貨的那條船讓那些該死的血帆劫掠者給搶劫了。$B$B我相信像你這樣勇敢的 $C ，一定能說服他們交還船上的貨物，對吧?','藏寶海灣的迪格要求你帶給他15份鼻煙。','','去荊棘谷找藏寶海灣的迪格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (597,'zhTW','血帆海盜','這是一張藏寶海灣的地圖，上面用紅筆標叉的地方就是你現在站的位置。$B$B圖上潦草的寫著幾行字:$B$B「你們的任務就是悄悄地在此地紮營，等待南方指揮部發出信號後再開始攻擊。如果任何人試圖阻礙你們，格殺勿論。」','將你的發現報告給藏寶海灣的大副克拉茲。','','去荊棘谷找藏寶海灣的大副克拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (599,'zhTW','血帆海盜','太令我吃驚了!那麼血帆海盜正計畫著進攻藏寶海灣嗎?這群發了神經病的惡棍當真是不要命了麼，藏寶海灣永遠都是我們黑水強盜的地盤!$B$B這事比我想得還要嚴重。馬上將你所知道的一切報告給艦隊指揮官卡拉·海角!這群該死的海狗可能已經開始在鎮子外面集結了……','把血帆海盜的計畫報告給艦隊指揮官卡拉·海角。','','去荊棘谷找藏寶海灣的艦隊指揮官卡拉·海角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (600,'zhTW','風險投資公司的採礦行為','最近，風險投資公司在荊棘谷一帶展開了一系列的行動，這讓我們這些誠實努力的哥布林們，你看，比如我，根本沒辦法在這裡討生活了!拜託，你一定要幫幫我!$B$B風險投資公司打算在北邊的水晶礦坑那裡採礦，可是由於那邊的石化蜥蜴到處肆虐，他們根本沒辦法進入礦坑，只能在周圍的山上開採歌唱水晶。$B$B去把他們的水晶都搶來，讓他們知道他們不該在這片叢林裡如此囂張。$B$B還有……嗯嗯……把那些水晶給我帶回來當證據!','給藏寶海灣的克蘭克·菲茲巴布帶回10塊藍色歌唱水晶。','','去荊棘谷找藏寶海灣的克蘭克·菲茲巴布。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (601,'zhTW','水元素','這些水元素無疑是傳說中發現了海潮之石的哥布林巫師加茲班召喚的。也許你知道，海潮之石會詛咒任何挪動它的人，就是說，會讓那個倒楣的傢伙從這個世界上徹底消失。$B$B應該有什麼辦法可以破除這個該死的詛咒，我們可以請一位達拉然的法師來幫我們分析一下水元素胳膊上戴著的護腕裡的魔法。你能不能回到那島上幫我收集一些進行魔力分析所需的樣本?','為藏寶海灣的大財主里維加茲收集6個水元素護腕。','','去荊棘谷找藏寶海灣的大財主裡維加茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (602,'zhTW','魔法分析','我聽說達拉然的法師們已經成功地重建了他們的魔法城市，並且把它遷到了北裂境，原先所在處只留下了一個巨大的坑洞。但有些法師則留在這裡，繼續研究著這些護腕。根據我對那些法師的瞭解，他們是絕對不會拒絕任何與魔法有關的謎題的。$B$B將這包水元素的護腕拿給他們，讓他們看看能不能找到解除石頭上的詛咒的方法。建議你去那邊找大法師安斯雷姆·織符者。他曾經幫過我的忙，我想他的淵博知識可以對你有所幫助。','將水元素護腕交給達拉然陷坑的大法師安斯雷姆·織符者。','','去奧特蘭克山脈找達拉然巨坑的大法師安斯雷姆·魯因。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (603,'zhTW','安斯雷姆的鑰匙','嗯，擁有那塊石頭的法師一定通過在某處集中力量來加強他的魔法效力……比如在某個祭壇上。按理說你應該可以用更強大的力量去瓦解它。$B$B就目前的情況而言，我知道有件物品可以派上用場:食人妖一族失落的另一件神器，一把遠古匕首。但是，還有一個……只有一個……小問題。$B$B你知道，我過去在荊棘谷進行研究的時候得到了那把匕首，但我把匕首給了我那任性的女兒，她叫凱特琳。她現在已經去了藏寶海灣，也許是真的想當個海賊吧。','與藏寶海灣的凱特琳談話。','','去荊棘谷找藏寶海灣的凱特琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (604,'zhTW','血帆海盜','克拉茲高度讚揚了你為黑水強盜做出的重要貢獻。我信任你，因此我要賦予你一個對於艦隊來說至關重要的任務。$B$B我們要求你滲透進血帆海盜建立在蠻荒海岸的南方指揮部。偷襲他們的營地，將他們的海圖與計畫書都給我帶回來，我們必須要搞清楚這群渣滓到底想幹點什麼。','藏寶海岸的艦隊指揮官卡拉·海角要求你殺死10名血帆劍客並將血帆海圖和血帆計畫書帶回去。','','去荊棘谷找藏寶海灣的艦隊指揮官卡拉·海角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (605,'zhTW','藍色歌唱水晶裂片','歌唱水晶是荊棘谷的一種特產，它對某些人來說有著非常重要的價值。我本想運一些歌唱水晶到別的地方去賣，可那該死的風險投資公司想要獨佔它，所以，像我這樣誠實的商人看來就無法親自去收集水晶了!$B$B我決定雇傭你。$B$B荊棘谷中的蜥蜴都有吞食這種水晶的習性，這可以使它們的皮膚變得更硬。因此，我們可以從它們身上收穫到一些高品質的水晶。$B$B隨便哪隻蜥蜴身上都會有水晶，但最容易對付的是在北邊的海岸附近活動的那些蜥蜴。','為克蘭克·菲茲巴布收集10塊歌唱水晶裂片。','','去荊棘谷找藏寶海灣的克蘭克·菲茲巴布。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (606,'zhTW','嚇唬病鬼','你知道這裡最讓我受不了的是什麼嗎?這兒的人都有死也不還賭債的毛病!現在已經有一大群傢伙欠著我的錢了。你能幫我催一下債嗎?$B$B第一個要催的就是住在碼頭那邊的『病鬼』菲力浦。他上個禮拜欠得實在是太多了，我一定要把這筆錢給要回來!但是要想拿到它，我們就得好好嚇唬嚇唬他。$B$B到鎮子外邊去獵殺一些老邁的迷霧谷猩猩，然後從它們身上搞點內臟雜碎什麼的，把這些玩意丟給那病鬼。最好別讓他想到那是動物內臟，讓他想點更糟的。','給藏寶海灣的『病鬼』菲力浦帶回5塊迷霧谷猩猩的內臟。','','去荊棘谷找藏寶海灣的“病鬼”菲利普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (607,'zhTW','向麥克基雷回報','給，把這個布袋給海狼。告訴他，我是想還他錢的!我發誓!!$B$B我只是喝多了點，迷路了而已，還有……總之是一團糟了。他會理解我的─你可別亂說啊!','將病鬼的還款交給『海狼』麥克基雷。','','去荊棘谷的藏寶海灣找“海狼”馬克基雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (608,'zhTW','血帆海盜','菲爾拉倫一點膽量都沒有!他連划著小船穿越水晶湖都做不到，更別說獨自率領整支艦隊來和我們對抗了。$B$B血帆海盜一定會為他們的粗心大意而付出代價的。現在我們已經掌握了他們的攻擊計畫，完全可以在他們什麼還都不知道的時候搶先下手。$B$B我們並不需要派出全部的艦隊，只要一支勇敢的冒險隊伍就能輕易完成這任務。 $N ，帶著你最優秀的同伴前往菲爾拉倫的登陸點，殺掉血帆的指揮官。這樣他們的艦隊不用多久就可以去餵魚了……','藏寶海灣的艦隊指揮官卡拉·海角要求你殺死血帆海盜的斯蒂沃特船長，尼哈魯船長和艦隊指揮官菲爾拉倫。','','去荊棘谷找藏寶海灣的艦隊指揮官卡拉·海角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (609,'zhTW','討債行動','我這兒的欠條已經少了許多啦，但還是有許多沒信譽的傢伙欠著我的錢。$B$B接下來，我們得對付瑪雷·『木腳』·維爾金斯、『烏鴉』喬喬，還有『十指』蘇克。$B$B這幫傢伙的債欠了好久，我看他們是不想還了!後來，我聽說他們被什麼人給騙到叢林裡去了。我當然不關心他們到底會怎麼樣─我要的是我的錢!$B$B他們應該就在東北方的阿博拉茲廢墟和朱布瓦爾廢墟裡。找到他們，把我的錢拿回來。','給藏寶海灣的『海狼』麥克基雷帶回瑪雷的木腳、喬喬的金色望遠鏡和蘇克的巨型戒指。','','去荊棘谷找藏寶海灣的“海狼”馬克基雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (610,'zhTW','『漂亮男孩』鄧肯','我老爸派你來的?我還以為那怪老頭早就已經放棄我了呢。$B$B我之所以離家出走確實不是他的錯，他只是不應該為我安排好一條乏味的人生道路，並希望我欣然接受它。我怎麼能忍受整天讀著那些發黴的書本，整天和那幫灰頭髮加駝背的乏味老頭法師們在一起!$B$B如果你需要我的匕首，你可能得從一個叫『漂亮男孩』鄧肯的血帆海盜那裡奪回來。我想你只要教訓教訓他，他就會屈服的。','從『漂亮男孩』鄧肯那裡奪回凱特琳的匕首。','','去荊棘谷找藏寶海灣的利刃凱特琳。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (611,'zhTW','海潮的詛咒','這麼說你正在尋找某個祭壇嘍?好吧，雖然我不像我老爸那樣是個研究食人妖遺跡的專家，但我對你正在尋找的島嶼也略知一二，在島的附近有一座沉沒在水底的食人妖城市，我想你應該到那裡去碰碰運氣。$B$B既然是你幫我找回了我的匕首，借去用用當然沒有任何問題……但我希望你用完以後能還給我!','用凱特琳之刃摧毀海潮祭壇，然後殺死加茲班，將海潮之石帶給大財主里維加茲。','','去荊棘谷找藏寶海灣的大財主裡維加茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (613,'zhTW','打開瑪雷的木腳','該死!那見鬼的瑪雷居然在他的假腳上安了一個鎖，我還死活都打不開!他的寶貝，還有他欠我的錢，都藏在那條假腿裡!$B$B我們得想辦法找到鑰匙才行。瑪雷這傢伙過去因為喜歡和住在東北邊巨魔山上的莫什奧格巨魔賭博而出名，而且他告訴過我─我是說當他還活著的時候─他每次贏了一票大的之後都會去一趟那裡，所以，或許那邊的巨魔會有他的鑰匙。$B$B要真是如此的話，你八成得大開殺戒才能搞到鑰匙……','把瑪雷的鑰匙帶給藏寶海灣的『海狼』麥克基雷。','','去荊棘谷找藏寶海灣的“海狼”馬克基雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (614,'zhTW','船長的箱子','我過去在一條專跑從這裡到卡林多的棘齒城的航線上幹過。我是個很優秀也很有名望的船長。$B$B直到……$B$B那些該死的海巨人毀了我的生活!他們打沉了我的船，殺光了我的水手，把我丟在一條救生艇上，讓我漂回了藏寶海灣。還有，其中一個名叫高拉什的巨人還把我的箱子給偷走了，他說要拿這東西當鼻煙盒，簡直是神經病!$B$B我聽說有人看見高拉什最近在東邊的海岸一帶閒逛。找到他，把我的箱子給搶回來!快去，你會得到一位船長的敬意的。','將斯莫特的箱子交給藏寶海灣的海克拜瑞·斯莫特。','','去荊棘谷找藏寶海灣的海克拜瑞·斯莫特船長。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (616,'zhTW','幽靈島','大財主里維加茲讓我留意最近在藏寶海灣和荊棘谷附近流傳的古怪傳聞。雖然我平時是絕不會關心什麼鬼故事的，但這兩天在酒館裡聽一些水手們說在海岸附近有一座鬧鬼的小島。據他們說，那上面全是水元素和一隻整日說著瘋話的哥布林的鬼魂。$B$B如果你正好要去見里維加茲閣下的話，能替我將這件事轉告給他嗎?','與藏寶海灣的大財主里維加茲談話。','','去荊棘谷找藏寶海灣的大財主裡維加茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (617,'zhTW','一捆海蛇草','聽說你正在找活做， $N ?要是你夠膽的話，我這兒倒是有件不錯的活正要找人呢。$B$B你聽說過最近有許多人都在找一處泉水麼?是的，有一群納迦也在找。我有個叫格羅伊的朋友吧，他最近出了一大筆錢，想買一些納迦稱之為海蛇草的東西。我也不清楚那到底是什麼，只知道是一種很值錢的海草。他也沒說要那玩意幹什麼，不過他確實出了一個好價錢，大概需要一捆吧。$B$B你幫我搞來10根這種什麼草，那我們就可以跟他做筆交易啦。不久前有人看見這裡北邊的海灘上出現了不少納迦。','給藏寶海灣的私掠者布勞茲帶回10捆海蛇草。','','去荊棘谷找藏寶海灣的海盜布勞茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (621,'zhTW','贊吉爾的秘密','『流亡者』贊吉爾和他的追隨者們住在藏寶海灣東北方的朱布瓦爾廢墟和阿博拉茲廢墟裡，這個傢伙已經被他的部族放逐了。為什麼?這個……$B$B據說是因為贊吉爾掌握了可以屈服其他人的心志的方法，而他所屬部族的領袖因此非常害怕他。他讓他的追隨者們喝下了一種從叢林的植物中萃取出來的液體，用它來壓抑他們的自我意識並加強他們的力量。$B$B這種藥劑對那些試圖控制別人的傢伙來說有非常大的價值。$B$B給我弄些這種藥劑的樣本來，我要研究一下他們有什麼用處。','收集12份贊吉爾的藥劑，把它們交給藏寶海灣的克蘭克·菲茲巴布。','','去荊棘谷找蠻荒海岸的克蘭克·菲茲巴布。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (624,'zhTW','科泰羅的謎題','有一座裝飾華麗，人來人往的橋$B逆風徑東，赤脊山南面之地$B在那之下，它正等待著你$B這可以叫提示，也可以叫線索$B在那裡，無盡的明天正等待著你$B在悲傷沼澤之中靜靜地等待著你','解開這道謎題!','','去悲傷沼澤尋找線索。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (627,'zhTW','克拉茲克的要求','在阿拉希高地北部的枯鬚峽谷中有一處山洞，那裡有一種十分稀有的礦石:血石。那個山洞裡的血石雖然不是品質最佳的，但即使是低等級的血石也是很有價值的……當然這只是對那些懂得如何使用它們的人來說。$B$B我需要一些這種血石。$B$B我會在這裡修補你的鍋子，不過，當我修鍋的時候……你去給我弄些血石來吧。對，多帶點回來，我當然會給你報酬的。$B$B嗯嗯，要是你連這點事都搞不定，就去找個能搞定的人幫你!','給藏寶海岸的克拉茲克帶去4塊次級血石礦。','','去荊棘谷找藏寶海灣的克拉茲克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (628,'zhTW','刨花皮靴','裡層的東西都已經做完了，現在只剩下外面的表層部分了。表層部分我只用品質最好的老海鱷魚的皮。這種皮比帆布還要好，還要結實--如果你願意的話--，還可以為我的完美設計增加設計感和特色。$B$B但是要找到一張完美的皮很難，只有老海鱷魚的皮是唯一能配得上我的設計的材料。老海鱷只會在其他鱷魚被攻擊的時候才會出來保護族群，所以你恐怕得先殺些普通鱷魚來引牠們出來。','帶1張老海鱷的皮給藏寶海灣的崔斯里克。','','去荊棘谷找藏寶海灣的崔斯里克。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (633,'zhTW','薩多爾大橋','天呀!不!可憐的伊本瑟，這實在是一個悲劇。$B$B我們絕對不能讓他就這樣白白犧牲了。你發現的這張羊皮紙上寫道，是卡姆·深怒在背後組織了這次進攻，並且，他還在薩多爾峽谷的阿拉希高地那一側囤積了不少爆裂物。$B$B如果他們用這些爆裂物摧毀了橋樑的話，那麼我們的通向北邊的主要補給線就會被徹底切斷!必須摧毀這些爆裂物， $N !完成了這個任務後立刻回來向我覆命。$B$B你是我們最後的希望了。','摧毀堆積的爆裂物。','','去濕地找丹莫德的拉格·加瑪森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (642,'zhTW','受困的公主','我叫密斯賴爾，我是大地的公主。巨人們俘獲了我，把我拘禁在阿拉希高地的地下深處。這些水晶碎塊是我和外界交流的唯一途徑。$B$B幫幫我。這些巨人的盟友─枯鬚狗頭人─就在東邊的枯鬚峽谷裡活動，那裡有一塊類似的水晶裂片。要啟動那塊水晶，你必須從狗頭人那裡收集到密斯賴爾之塵，然後把它們放在水晶上。$B$B求求你了， $N ，幫幫我吧!','收集密斯賴爾之塵。','','去阿拉希高地找枯須峽谷的虹光水晶碎塊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (651,'zhTW','禁錮之石','在阿拉希高地上散佈著4塊禁錮之石，這些石頭將我牢牢地釘在地下。$B$B要想解除它們，你就必須解除最堅固的那塊:內禁錮之石。首先，你必須搜集到其他三塊石頭的鑰匙。$B$B這些石頭都有守護者在看守，但是如果你足夠聰明或者足夠幸運的話，就能找到消滅這些守衛的辦法。','從西禁錮之石、東禁錮之石和外禁錮之石中搜集烈焰鑰匙、海浪鑰匙和雷霆鑰匙。','','去阿拉希高地找內禁錮法陣的內禁錮之石。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (652,'zhTW','打開鑰匙之石','禁錮之石的開啟基本解開了這些束縛著我的東西，可還有一把牢不可破的鎖讓我無法動彈。你看到這圈石頭中的那塊鑰匙之石了嗎?開鎖的鑰匙在弗茲魯克手中，他是囚禁我的巨人之一，也是這石鎖的看護人。$B$B你必須從弗茲魯克那裡獲得一把名叫「秩序魔棒」的鑰匙來打開鑰匙之石。$B$B你已經為我做了這麼多， $N ，只是再幫個微不足道的小忙……我會對你更加感激不盡的!','找到並殺死弗茲魯克，然後把秩序魔棒帶到阿拉希高地的鑰匙之石旁。','','去阿拉希高地找內禁錮法陣的鑰匙之石。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (658,'zhTW','新的瘟疫?','是費恩讓你來找我們的吧?我一點都不吃驚，那傢伙總是擔心這個擔心那個的。$B$B我們監視這個農場已經有段時間了，基恩洛說她不久前看到有一個信差從那間小房子裡走出來，往南邊去了。$B$B她平時話有些多，不過在這種危險的地方，我總是相信她的直覺。$B$B嗯……你的追蹤能力怎麼樣?我們認為那個信差可能是帶著信去塔倫米爾了。如果你能弄到那些檔案，就有可能幫助我們搞清楚在希爾斯布萊德所發生的那些怪事。','找到被遺忘者信差，把她的密封的信件交給格沙克農場裡的奎艾。','','去找阿拉希高地的奎艾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (660,'zhTW','新的瘟疫?','好了， $N 。我已經準備好了。$B$B可以出發了嗎?','保護基恩洛，直到她回到奎艾身邊。','保護基恩洛','去找阿拉希高地的奎艾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (681,'zhTW','諾斯弗德農場','我們正在為激流堡而戰，然而我們卻逐漸落入下風。我們、巨魔以及辛迪加分別控制著這座城市的一部分，現在我們這三方勢力陷入了整日互相征戰卻毫無突破的僵局。$B$B然而，當敵人們力量開始逐漸增強的時候，我們卻在慢慢地變弱。$B$B我們需要南海鎮的援助，但是辛迪加控制了我們和南海鎮之間的領地，因此那邊的補給很難運到這裡來。$B$B到辛迪加在諾斯弗德農場的基地去幹掉他們，也許這樣做能讓我們補給線上的壓力大大減輕，然後才能有更多的物資平安運抵這裡。','殺掉6個辛迪加雇傭兵和10個辛迪加路霸，然後回到避難谷地去向尼艾絲隊長覆命。','','去阿拉希高地找避難谷地的尼艾絲隊長。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (682,'zhTW','激流堡徽章','我們的民兵分隊正在和控制著激流堡的辛迪加成員激戰。為了刺激他們那群烏合之眾與我們作戰，辛迪加的頭目們使出了重金懸賞的手段，只要有人能殺死我們的民兵，並從他們身上繳獲激流堡徽章，辛迪加都會給予獎勵。$B$B我們必須奪回那些徽章─決不能讓劊子手們用我們的戰士的性命來換取金錢!$B$B到激流堡城內的辛迪加控制區去殺掉那些歹徒，取回我們的徽章。','把7個激流堡徽章交給位於避難谷地的尼艾絲隊長。','','去阿拉希高地找避難谷地的尼艾絲隊長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (684,'zhTW','通緝:瑪雷茲·考爾','重金懸賞瑪雷茲·考爾的項上人頭。這個獸人是辛迪加組織的高級顧問和技工，人們最後一次看見她是在激流堡內的辛迪加控制區。$B$B賞金請到尼艾絲隊長處領取。$B$B請注意:瑪雷茲是一個強大而狡猾的術士，她和惡魔有著非常密切的聯繫。追殺她時務必非常小心。','把瑪雷茲的頭顱交給避難谷地的尼艾絲隊長。','','去阿拉希高地找避難谷地的尼艾絲隊長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (685,'zhTW','通緝:奧圖和法庫雷斯特','激流堡民兵團重金懸賞法庫雷斯特領主和他的保鏢奧圖的頭顱。法庫雷斯特是辛迪加在阿拉希地區的主要領導者，他的死將使該組織在這一地區的活動陷入癱瘓。$B$B他的保鏢奧圖不是我們的戰略目標，但他生性兇殘，已經殺死了許多激流堡的士兵。$B$B賞金請到尼艾絲隊長處領取。','把法庫雷斯特和奧圖的頭顱交給避難谷地的尼艾絲隊長。','','去阿拉希高地找避難谷地的尼艾絲隊長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (691,'zhTW','證明實力','大法師馬林派斯奎爾圖和我到這裡來為他收集一些試劑，對於如何收集這些物品，我感到很困惑。不過現在你來了，我想我的問題也解決了。$B$B我需要這些東西:枯木食人妖的獠牙，枯木食人妖的醫藥包和一把暗影獵手的小刀。$B$B你能幫我找到這些嗎?枯木食人妖一般都在阿拉希高地的東南一帶出沒。','幫避難谷地中的學徒克里汀收集10個枯木食人妖的獠牙，4個枯木食人妖的醫藥包和1把暗影獵手的小刀。','','去阿拉希高地找避難谷地的學徒克里汀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (693,'zhTW','特雷萊恩的符咒魔杖','你好啊， $N ，很抱歉我以前對你那麼凶……我可以斷定特雷萊恩的第一件寶物的所在:它在石拳大廳的考格雷什手裡。順便說一句，他已經可以使用冰爆術來教訓不聽話的手下，看來離他完全掌握魔杖力量的日子也已經不遠了。$B$B石拳大廳就在這裡的南邊，薩多爾大橋的東邊。從那個巨魔手裡把那根魔杖拿回來吧。$B$B在你回來之前，我要想想我們要怎樣解決激流堡的問題。','幫避難谷地的斯奎爾圖找到特雷萊恩的符咒魔杖，並把它帶回來。','','去阿拉希高地找避難谷地的斯奎爾圖。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (694,'zhTW','特雷萊恩的防禦','休息好了嗎?$B$B我們的下一步計畫和激流堡的阿拉索之塔周圍的巨魔有關。我們必須首先開啟這座塔的防禦系統，當然，前提是你能活著到達存放那些物品的地方。為此，首先我們需要一些石拳薩滿經常攜帶著的寶石。他們把寶石從塔裡帶了出來，但他們沒有什麼機會佔有這些寶石了。$B$B從他們那裡弄一塊寶石，把它送去給克里汀─他能夠給寶石附魔，這樣一來，寶石就可以當鑰匙用了。','找到一塊蒼藍瑪瑙石，把它交給避難谷地處的學徒克里汀。','','去阿拉希高地找避難谷地的學徒克里汀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (696,'zhTW','進攻高塔','以下是你要找的東西:特雷萊恩的骨匣、特雷萊恩的寶珠和特雷萊恩的黑瑪瑙。$B$B所有這三樣東西應該都在塔中的箱子裡，你打開這些箱子應該不會有什麼問題，只是要當心那些巨魔就成。$B$B阿拉索之塔的防禦不會作用於那些巨魔，因此你必須時刻準備戰鬥。如果那些巨魔發現你在偷他們的東西，你就少不了一場惡戰。$B$B多加小心，祝你好運。','找到特雷萊恩的骨匣、特雷萊恩的寶珠和特雷萊恩的黑瑪瑙，把它們交給避難谷地的斯奎爾圖。','','去阿拉希高地找避難谷地的斯奎爾圖。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (731,'zhTW','健忘的勘察員','好吧，那麼，霍莉...哦，不對，你不是霍莉。霍莉去哪兒啦?$B$B不說這個了，那不是我們要討論的話題。我們必須找到那把石刷...我是說神秘的化石!我們必須找到化石。達納蘇斯的探險者協會希望能看到我的工作進展情況。$B$B如果你準備好了，就和我說一聲，我們去尋找那把刷子...我是說化石!我們要找到一些能讓協會滿意的東西。$B$B你準備好了嗎?','在勘察員雷姆塔維爾搜尋神秘化石的時候保護他，然後回到奧伯丁的考古學家霍莉那裡。','護送勘察員雷姆塔維爾','去黑海岸找奧伯丁的考古學家霍莉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (743,'zhTW','風怒鷹身人','謝謝你抽時間來和我談話， $N 。我是盧爾，既是一個 $C ，也是一個導師。$B$B如果你想在莫高雷之外經歷更多冒險的話，現在正是讓你接受更多考驗的時候了。$B$B如果你想測試自己的能力，就去東南方找風怒鷹身人作戰吧。他們駐紮在山邊遠離大路的地方。$B$B鷹身人是我們的天敵，對你來說，和他們戰鬥會是個不錯的考驗。','給血蹄村的盧爾·鷹爪帶回8隻風怒鷹身人的爪子。','','去莫高雷找血蹄村的盧爾·鷹爪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (744,'zhTW','準備典禮',' $N ，我的兄弟很快就要去面見血蹄酋長了，我要為他做一個頭飾，這對我來說是一種榮耀。$B$B在我處理這些皮革的時候，你能不能幫我一個忙?我沒有時間去收集足夠的羽毛，不知道你能否幫助我去收集一些呢?$B$B你應該可以在雷霆崖北面和西北面的鷹身人身上找到尺寸合適的羽毛。我需要6片蒼藍色的和6片古銅色的羽毛來完成我的頭飾。','收集6根蒼藍色的羽毛和6根古銅色的羽毛。','','去找雷霆崖
的伊恩·鷹爪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (745,'zhTW','土地之爭','這片土地上有很多紛爭， $N 。我希望你不會像我一樣經歷那麼多的戰爭，不過我還是希望你去做一件事，讓你可以瞭解到，一個看似不值一提的小小威脅如果不加制止的話，會對我們的領土帶來多大的危害。$B$B白鬃豺狼人已經在西邊的一個洞穴中和血蹄村的南邊紮了營。我們曾試圖和他們交流，卻被他們無禮地拒絕了，而且他們還大肆屠殺莫高雷的野生動物。$B$B現在語言已經不能解決問題了，我們必須有所行動。','殺死10個白鬃製革工、8個白鬃剝皮工和5個白鬃偷獵者，然後回到血蹄村向貝恩·血蹄覆命。','','去莫高雷找血蹄村的貝恩·血蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (746,'zhTW','矮人的挖掘場','有些矮人正準備在西北邊建立一個挖掘點。他們認為地底下埋藏著某些秘密，事實也的確如此，但挖空和破壞土地是不可能理解大地的教誨。$B$B收集矮人的挖掘工具，毀掉那些東西，然後把矮人損壞的工具帶來給我。$B$B你可以在熔爐邊破壞那些工具。你可以在雷霆崖找到熔爐，但任何一個熔爐 -- 甚至是矮人營地的熔爐 -- 都可以用來破壞工具。','收集5個勘察員的十字鎬。','','去莫高雷找血蹄村的貝恩·血蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 747 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (747,'zhTW','開始狩獵','歡迎來到納拉其營地，$N 。你來到這裡的消息很快就傳遍了部族。或許很快有一天你會被迎去雷霆崖上的大城市裡，但首先，你必須先向我們證明你的能力。$B$B我們這些生活在紅雲臺地上的 $R 無疑對自己優秀的狩獵技術最為自豪，當然， $R 只為生存需要和競技而狩獵。我們庫存的肉已經不多了，另外我們還需要羽毛來做衣服。現在去獵殺附近的平原陸行鳥來給村莊提供補給吧，同時你也可以借此證明自己的能力。','納拉其營地的格盧爾·鷹風要求你帶給他7根平原陸行鳥的羽毛和7塊平原陸行鳥肉。','','去莫高雷找納拉其營地的格魯爾·鷹風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (748,'zhTW','毒水','那些哥布林和他們的爪牙污染了我們神聖的水井!我們必須制止他們!$B$B要想淨化所有的水井，我得先製造出相應的淨化圖騰，然後你把圖騰拿到水井那兒去完成淨化的儀式。$B$B首先，我們給冬蹄之井製作一個淨化圖騰，這需要大地的幫助。去獵捕一些草原狼和成年平原陸行鳥，把它們的爪子帶回來給我，它們就在西南方活動。','收集6隻草原狼的爪子和4隻平原陸行鳥的爪子，把它們交給血蹄村的莫爾·雷角。','','去莫高雷找血蹄村的穆爾·雷角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 750 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (750,'zhTW','繼續狩獵','善於狩獵的 $R 從不僅僅將他的獵物看作戰利品，這些生活在平原上的野獸對我們的生存有著極為重要的意義。如果你能帶回一些珍貴的山獅皮的話，就會令部族裡的長老們對你刮目相看。你可以在南邊的山區找到它們。$B$B我們的孩子需要衣服，部族裡的帳篷也需要維修了。','納拉其營地的格盧爾·鷹風要求你帶給他10張山獅皮。','','去莫高雷找納拉其營地的格魯爾·鷹風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (753,'zhTW','一件瑣事','我這一生也算是經歷了不少磨難，走了不少路，現在我這一把老骨頭也沒什麼力氣啦。我仍然在為部族盡力，但有些時候，我還真感覺有些力不從心。$B$B不過，你這 $C 似乎是正想找點什麼事情做做呀。正好，讓我來看看你的體力如何吧。把水井旁的這個水罐交給我兒子，他就在納拉其營地裡。$B$B記住，即使是最瑣碎的小事，只要你做得夠好，也能獲得長老們的首肯。','在井邊拿一隻水罐。','','去莫高雷找納拉其營地的鷹風酋長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (754,'zhTW','淨化冬蹄之井','我已經做好了可以淨化冬蹄之井的圖騰。現在你就把它拿到那兒去完成淨化儀式。冬蹄之井就在東南邊，有許多哥布林把守著那裡!$B$B這不是個簡單的任務，不過如果我們想要重新使用那裡的水，就必須得這麼做。$B$B祝你好運， $N 。','用冬蹄之井淨化圖騰為冬蹄之井完成淨化，然後回來見莫爾·雷角。','淨化冰蹄之井','去莫高雷找血蹄村的穆爾·雷角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (756,'zhTW','雷角圖騰','要製作雷角之井淨化圖騰，你必須先去收集莫高雷平原上的肉食動物的爪子。去捕獵草原捕食者和平原獅，然後把它們的爪子帶回來見我。$B$B它們就在這裡的東邊和西邊活動。','收集6個草原捕食者的爪子和6個平原獅的爪子，把它們帶給莫爾·雷角。','','去莫高雷找血蹄村的穆爾·雷角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (757,'zhTW','力量祭儀','大地之母祭儀對於每一個想要在雷霆崖得到尊重的年輕 $R 來說都是非常重要的。$B$B但在那之前，你必須先通過力量祭儀的試煉。在這個試煉中，你必須通過殺死部族的敵人來證明你的勇猛。$B$B生活在東邊的刺刃峽谷中的刺背野豬人侵佔了我們部族不少的土地，他們偷襲我們的狩獵小隊，還在晚上到村子裡來偷東西。$B$B殺死他們，展示出你的英勇無畏吧。拿著它們的腰帶去見納拉其營地的酋長，他將證明你通過了試煉。','殺掉刺刃峽谷的刺背野豬人並帶回12條刺背腰帶，把它們交給納拉其營地的鷹風酋長。','','去莫高雷找納拉其營地的鷹風酋長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (758,'zhTW','淨化雷角之井','圖騰已經準備好了， $N 。這一次還是由你來完成淨化儀式。$B$B到村莊北面的雷角之井去，用雷角之井淨化圖騰完成淨化儀式，然後再回來找我。$B$B願大地之靈指引你。','在雷角之井使用雷角之井淨化圖騰，然後回來見莫爾。','淨化雷角之井','去莫高雷找血蹄村的穆爾·雷角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (759,'zhTW','蠻鬃圖騰','還剩下一口井需要淨化，它是以蠻鬃氏族的名字命名的。要想淨化這口井，你必須從大地上尋找一種兇猛的肉食動物的牙齒，那就是草原狼前鋒的牙齒。去北邊尋找草原狼前鋒，拿到我要的東西之後再回來。$B$B這些草原狼前鋒經常在雷霆崖的山腳下遊蕩。','收集8顆草原狼前鋒的牙齒，把它們交給血蹄村的莫爾·雷角。','','去莫高雷找血蹄村的穆爾·雷角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (760,'zhTW','淨化蠻鬃之井','你淨化冬蹄之井和雷角之井的事蹟已在魂靈之間被廣為傳誦，年輕的 $N 。我也做好了蠻鬃之井淨化圖騰，接下來就是你最後一個任務了。$B$B蠻鬃之井在雷霆崖的北面，到那裡完成淨化儀式吧，拯救這片被哥布林污染的土地，讓這片土地上再次流動甘甜純淨的井水!','在蠻鬃之井使用蠻鬃之井淨化圖騰，然後回來見莫爾·雷角。','淨化蠻鬃之井','去莫高雷找血蹄村的穆爾·雷角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (761,'zhTW','獵捕猛鷲','猛鷲是一種狡猾無比、很難獵捕的鳥。收集猛鷲的羽毛可以證明一個獵手的智慧和決心。$B$B如果你想接受這個任務，就去平原上獵捕猛鷲吧。$B$B把它們的羽毛帶給我，為你的氏族贏得榮譽。$B$B猛鷲在莫高雷的任何地方都能找到，不過要發現它們，你得有銳利的眼睛;要捕捉它們，你得有靈活的手腳。','收集8根猛鷲的羽毛，把它們帶給血蹄村的哈肯·風之圖騰。','','去莫高雷找血蹄村的哈肯·風之圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (764,'zhTW','風險投資公司','這就解釋了為什麼風險投資公司在不斷往莫高雷地區增派職員和設備。這些哥布林……他們的公司擴張得太快了。就像他們自己所說的那樣，只要給哥布林一點甜頭，你就能聽到他們打算盤的聲音。$B$B這些小東西實在是太貪婪了。不過我們 $R 決不會讓他們在我們的領土上為所欲為。到他們的礦坑去，給他們點顏色看看，那個礦坑就在被破壞的貨車東北方。','血蹄村的摩林·雲巡者要你去殺死14個風險投資公司工人和6個風險投資公司主官。','','去找莫高雷的摩林·雲行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (765,'zhTW','菲茲普羅克主管','根據你從箱子裡拿來的文件可以看出，風險投資公司已經制定了很多把我們從這兒趕走的計畫，然後他們就能隨心所欲地掠奪我們的土地了。$B$B他們為了利潤居然可以墮落到這種程度，這簡直讓我感到厭惡和驚駭。我們要除掉這個陰謀的策劃者，他就是菲茲普羅克主管。你可以在被破壞的貨車以東的風險投資公司礦坑裡找到他，把他的筆記板帶給我，讓我們看看有沒有什麼有價值的東西。','殺掉菲茲普羅克主管，把他的筆記板帶給血蹄村的摩林·雲巡者。','','去找莫高雷的摩林·雲行者。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (766,'zhTW','馬茲拉納其','我祖父曾講述過他和一隻叫馬茲拉納其的陸行鳥戰鬥的故事，說起過它那邪惡的紅眼睛，剃刀般鋒利的爪子，只要被它咬一口，你就會身中劇毒。$B$B在我穿越平原的時候，正巧遭遇了它，肩膀被它咬了一口。它比我祖父所說的還可怕!我需要一些東西來幫我解毒:一顆狼心，獅子的腿骨，平原陸行鳥的鱗片和猛鷲的胃。$B$B快點，我快要不行了。','收集草原狼的心臟、平原獅的腿骨、平原陸行鳥的鱗片和猛鷲的胃各一份，把它們交給血蹄村的茂爾·祈雨。','','去莫高雷找血蹄村的茂爾·祈雨。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (768,'zhTW','收集皮革','你好，年輕的 $R 。我從你的眼中看到了你重回原野捕獵的渴望。希望你能為你的氏族帶來榮耀!$B$B我擅於利用各種獸皮來為雷霆崖的居民製作護甲和衣物。$B$B如果你能幫我搞到一些獸皮的話，那我就可以用它們來為你製作一些你需要的東西。','收集12塊輕皮，把它們交給雷霆崖的維爾倫·陸行者。','','去找雷霆崖的維爾倫·陸行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (769,'zhTW','科多獸皮包','莫高雷的科多獸強壯而兇猛，它們的這些特質備受我們尊敬。如果你善於皮革加工，而且希望獲得製作科多獸皮包的知識，那就給我弄點材料來吧。$B$B弄些材料來，我就會把我的手藝傳授給你。','給雷霆崖的維爾倫·陸行者帶去4塊輕皮和4條粗線。','','去找雷霆崖的維爾倫·陸行者。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (771,'zhTW','幻象祭儀','要想通過幻象祭儀，你必須先找到製作先知之水的試劑。$B$B我需要一些水井石，你可以在莫高雷一帶的水井附近找到它們。另外，你還得在這周圍的大樹下面找到一些琥珀顆粒。$B$B這兩種東西都具有強大的元素力量，把它們結合起來，用部族之火點燃之後，你可以看到一個幻象。追隨它，它就會引領你進入這個神聖使命的下一個階段。','收集2塊水井石和2個琥珀顆粒，把它們帶給血蹄村的札爾曼·雙月。','','去莫高雷找血蹄村的扎爾曼·雙月。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (776,'zhTW','大地之母祭儀','你已經通過了大地之母祭儀，在雷霆崖贏得了你自己的一席之地。$B$B不過要維持你努力爭取到的地位，你還必須不斷證明自己的價值。$B$B我們生來就是獵手， $N 。在莫高雷城下有一隻非常強大的科多獸，我們稱它為阿蘭其亞。把它的角帶來，向我證明你追蹤和捕獵的能力。','雷霆崖的凱恩·血蹄要你將阿蘭其亞的角帶給他。','','去莫高雷找雷霆崖的凱恩·血蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (780,'zhTW','鬥豬','生活在東邊的刺刃峽谷中的鬥豬已經侵佔了我們部族的狩獵場。正在與我們交戰的刺背野豬人把這些野豬訓練成了兇暴而富有攻擊性的生物。$B$B去把這些可惡的傢伙殺掉，再帶些豬頭和肋排回來，我們可以燉肉給孩子們吃。','納拉其營地的格盧爾·鷹風要求你去幹掉鬥豬，並帶給他8塊鬥豬頭和8塊鬥豬肋排。','','去莫高雷找納拉其營地的格魯爾·鷹風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (784,'zhTW','背信棄義的人類','庫爾提拉斯的人類曾在普勞德摩爾上將的率領下大舉進攻杜洛塔，徹底破壞了在共同抵抗阿克蒙德和他的惡魔大軍時由大酋長和珍娜·普勞德摩爾定下的互不侵犯協議。$B$B我們擊退了人類的進攻，並攻下了提拉加德城堡。但最近，由本尼迪克上尉率領的後備軍又重新佔領了提拉加德城堡，對我們的家園構成了新的威脅，這些人類從不遵守外交協議。$B$B到南方的提拉加德城堡去消滅那些人類侵略者，證明你的勇氣和榮譽。','殺死10個庫爾提拉斯水手和8個庫爾提拉斯水兵，再把本尼迪克上尉幹掉，然後回剃刀嶺向加索克復命。','','去找杜洛塔的加索克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (786,'zhTW','科卡爾半人馬的進攻','小聲點， $C 。科卡爾半人馬就在西邊科卡爾峭壁的山脊上。$B$B昨天晚上，我潛入了他們的村莊，發現這些骯髒的野獸準備同時向杜洛塔的食人妖和 $R 發動三波攻勢。$B$B我們決不能讓他們的入侵計畫得逞!你可以召集一些兵力，潛入科卡爾峭壁並粉碎他們的進攻計畫。$B$B他們已經把進攻計畫分別交給了三個首領，準備由他們率領三股部隊同時行動。','在森金村外面的拉爾·獵齒要求你粉碎科卡爾峭壁內的三份進攻計畫。','','去杜洛塔找森金村的拉爾·獵齒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (788,'zhTW','小試身手','第一項任務將在力量方面對你進行考驗。我本來可以把你派去貧瘠之地獵殺科多獸，不過呢，照實說，你活著比死了對我們來說更有用。$B$B我相信你更合適和那些雜斑野豬鬥一鬥，往北邊走就可以找到它們。','殺掉8隻雜斑野豬，然後向大獸穴裡的高內克報告。','','去杜洛塔找試煉谷的高內克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (789,'zhTW','工蠍的尾巴','無論是強大的戰士還是笨拙的新手，都有可能會倒在蠍尾上的毒針之下。在這裡的西北方有大量蠍子在活動，給我帶8條蠍尾回來，以此來證明你的戰鬥能力吧。$B$B事實上，它們尾巴上的毒針正是製作解毒劑的重要材料，解毒劑便是從毒針中提取的。我們需要長期備有大量的解毒劑，以防止像你這樣的新手被蠍毒所害……$B$B但我肯定你是不會需要這種玩意的，對吧?','把8根工蠍的尾巴帶給大獸穴中的高內克。','','去杜洛塔找試煉谷的高內克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (790,'zhTW','薩科斯',' $C !我差點就神不知鬼不覺地死在這鬼地方了!我在谷裡捕獵蠍子的時候，突然看到一隻看起來特別兇惡的蠍子。當時我就決定以它為獵物，打算在它那碩大的鉗子鉗住我的腿以前，先重重地給它來上那麼一下子。$B$B但我忘記了它還有根毒刺，毒刺猛紮了下來，一下子就刺進我的胸口。拜託，你一定得替我報仇!只有這樣才能留存我的名譽!我是在南邊的高地上碰上它的。','殺死薩科斯並將它的爪子帶回去交給哈納祖。','','去找杜洛塔的哈納祖。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (791,'zhTW','新的背包','我太老了，已經沒法上戰場拼殺了。所以我開始用別的途徑為部落出力，實現我的價值。$B$B我在這裡監視周圍的情況，我們的力量越來越強大，我吹起號角的機會也越來越少。$B$B為了打發時間，我經常給那些保衛家園的年輕戰士們做些有用的東西。$B$B我可以給你做一個用來放置財物的包袱，但是你得先給我找些帆布腳料來，人類和半人馬經常使用這種布料。','剃刀嶺瞭望塔中的弗恩·凝眉想要8塊帆布腳料。','','去杜洛塔找剃刀嶺的弗恩·凝眉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (792,'zhTW','邪靈劣魔','我相信你會在試煉谷學到很多東西，年輕的 $C 。$B$B我本是被派到這處谷地裡來指引和教育你們的，但我卻在這裡發現了一些不潔之物……$B$B一群自稱為燃刃氏族的 $R 潛入了試煉谷，他們躲進了東北方的一處洞穴裡，而他們的邪靈劣魔則肆虐著周邊的一大片地區。$B$B作為你對抗燃刃氏族的第一個任務，我命令你消滅這些劣魔。盡可能地多殺一些，如果殺完了它們之後你還活著的話，就回來向我覆命。','殺死8隻邪靈劣魔。','','去杜洛塔找試煉谷的祖雷薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (794,'zhTW','燃刃勳章','我通過預言術發現在燃刃集會所的深處藏有一件蘊涵著強大力量的物品，它被一些猛獸和黑暗的魔法守衛著。$B$B那件物品叫作燃刃勳章，你的下一個任務就是找到它，把它從集會所裡偷出來。$B$B不過你可得小心，因為勳章的所有者可能是一個燃刃部落中的強者，他也許要比你以前對付過的那些傢伙要強上許多倍。$B$B現在就出發吧， $N ，那個洞穴就在這裡的西北方。','幫大獸穴外的祖雷薩·遠凝帶回燃刃勳章。','','去杜洛塔找試煉谷的祖雷薩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (806,'zhTW','黑暗風暴',' $N ，我有個不妙的消息。對燃刃氏族的調查表明，杜洛塔境內還有不少這個氏族的勢力。這是我們絕對不能允許的!在他們站穩腳跟、滋生邪惡之前，我們必須把他們消滅掉。$B$B有個名叫費索·暗雷的哥布林術士就居住在西北部的雷霆山裡，他和他的那群爪牙就在那裡製造混亂。$B$B去幹掉他，再把他的爪子帶回來給我!','把費索的爪子帶給剃刀嶺的奧戈尼爾·魂痕。','','去找杜洛塔的奧戈尼爾·魂痕。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (808,'zhTW','明希納的顱骨','我在夢中聽到了我兄弟明希納的呼喚。$B$B回音群島上的術士札拉贊恩抓走了他，折磨著他，最後殘忍地害死了他。$B$B但即使是死亡也沒能讓我的兄弟得到安寧，因為札拉贊恩用邪惡的魔法把明希納的靈魂困在了他的顱骨中。我在夢中看見…我兄弟的顱骨和其他人的顱骨一起被堆在回音群島中最大的那座島上的法陣中。只要他的頭骨還在那兒，他的靈魂就無法得到自由。$B$B請你幫助他吧， $N 。找到那個邪惡的法陣，把明希納的顱骨帶回來給我，讓他的靈魂獲得自由吧!','到回音群島上去，將島上法陣中的明希納的顱骨帶回來，交給森金村的加德林大師。','','去杜洛塔找森金村的加德林大師。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (815,'zhTW','恐龍蛋大餐','啊呀!我差點忘了還得做早飯!$B$B $N ，快去給我找點鞭尾龍的蛋來，至少得要三個蛋才夠明天做飯用。$B$B血爪鞭尾龍非常兇猛，而且會拼命地保護自己的蛋。有時它們會把蛋深深地埋在地下讓你找不到，不過在森金村東南方的回音群島上，這些鞭尾龍的蛋滿地都是。','收集3個鞭尾龍的蛋，並把它們帶給剃刀嶺的廚師托爾卡。','','去找杜洛塔的廚師托爾卡。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (816,'zhTW','丟失的孩子',' $N ，請幫幫我吧!我的兒子克魯恩幾天前到西邊的怒水河畔捕獵鱷魚，卻一直沒有回來，我現在覺得不妙了。$B$B儘管他十分強壯，但他的固執和自尊常常讓自己陷入麻煩。我警告過他，鱷魚是強大而兇猛的動物，可他一聽就火了，掉頭就走。$B$B如果你找不到他，至少也請給我帶來一些關於他的消息，不管是好的還是壞的……就算把怒水河畔每隻鱷魚的肚子剖開也要找到點什麼。','把關於克魯恩的消息告訴剃刀嶺西北部農場中的米莎·托克雷。','','去杜洛塔找托克雷農場的米莎·托克倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (817,'zhTW','生活所需的虎皮','我們的獸皮大多取自生活在杜洛塔地區的老虎身上， $N 。我們捕獵這些野獸的原因很多，比如毯子、護甲，還有帳篷什麼的;同樣，還有許多原因讓我們允許它們繼續繁衍生息。$B$B但是現在，我們有必要再殺掉一些老虎了。我們的人數在增加，而庫存的獸皮也已經開始供不應求了，因此我需要更多獸皮來為他們製作各種生活用品。$B$B給我找四張杜洛塔猛虎的毛皮來，我會給你一些獎賞的。','收集四張杜洛塔虎皮，並把它們交給森金村的維爾林·長牙。','','去杜洛塔找森金村的維爾林·長牙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (818,'zhTW','沃納爾大師','雖然我的視力不斷衰退，但我還是可以看得足夠清楚。我曾經可以很輕易地施放強力的魔法，而現在我更多時候必須依靠鍊金術的幫助才行。不過我不收學徒，因為我從來沒有看到過任何夠格的食人妖或 $R 。$B$B你是合適的人選嗎?當然，你當然是……你當然以為自己合適。$B$B我需要一點東西，你能幫我拿來嗎?$B$B我要一些龍蝦人的眼睛和幾瓶蟹膠，你可以在杜洛塔的海蟹或龍蝦人身上找到這些東西，找齊了之後再來見我。','把4個龍蝦人的眼睛和8小瓶蟹膠帶到森金村，交給沃納爾大師。','','去杜洛塔找森金村的沃納爾大師。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (821,'zhTW','老陳的空酒桶','你想嘗嘗老陳的雷霆佳釀嗎?哈哈，這東西可是很帶勁的哦。老陳把釀酒術教給了我師傅，我師傅又傳給了我。去幫我找一些釀酒的材料，然後你就會得到物有所值的回報!$B$B幫我帶5顆草原獅的獠牙、5個平原陸行鳥的腎臟和1根雷霆蜥蜴的角回來，然後我就可以釀酒了。$B$B這些東西都可以在貧瘠之地找到。','收集5顆草原獅的獠牙、5個平原陸行鳥的腎臟和1根雷霆蜥蜴的角，把它們交給棘齒城的釀酒師德羅恩。','','去找貧瘠之地的釀酒師德羅恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (826,'zhTW','札拉贊恩','巫醫札拉贊恩就住在東邊的回音群島上，那些島嶼曾經是我們的家園。$B$B札拉贊恩從那裡不斷派出他的爪牙來到這邊的大陸上，用妖術控制我們的同胞，將他們也變成札拉贊恩的傀儡。$B$B我們必須阻止他。$B$B打敗札拉贊恩和他的爪牙─那些曾經是我們的朋友和親人的暗矛食人妖。把札拉贊恩的頭給我帶回來，作為你已經斬殺了這個惡魔的證明。','打敗札拉贊恩。','','去杜洛塔找森金村的加德林大師。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (833,'zhTW','神聖的墓地','赤色石是我們 $R 最神聖的墓地，只有最勇敢的 $R 才能得到在那裡安息的殊榮。這是給予那些幫助保衛雷霆崖和為部族的利益而付出生命的偉大 $C 的無上榮譽。$B$B不過這段時間以來，有種邪惡的威脅正在接近我們的神聖領土。有一群刺背干涉者正在破壞我們的墓地，我的年紀太大了，無力把他們趕走。$B$B你一定要把他們驅逐出去， $N 。','在赤色石殺掉8個刺背干涉者。','','去莫高雷找赤色石的博學者諾拉·暴雨圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (834,'zhTW','沙漠之風','我叫雷茲拉克，是加茲魯維的手下。他派我來這裡跟杜洛塔的獸人作生意...一切進行得很順利，除了商隊以外。商隊的安全根本沒辦法保證!這真的給我搞了不少麻煩!$B$B上次發出的一批貨物，他們還說肯定能平安送達，結果被一票塵風鷹身人從半道上給劫了去...他們好像是從那什麼...烈風峽谷來的?$B$B我得拿到那批補給!沿著大峽谷向南走，你就會看到那條直直切入山壁東西兩面的溝壑。','取回5袋裝滿貨物的袋子。','','去找杜洛塔的雷茲拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (835,'zhTW','保衛商路','加茲魯維跟我說過:「雷茲拉克呀，有一件事情你必須銘記，那就是如果你想把事情做好，就得親力而為。」$B$B我不能失去我們所有的商隊，所以我得自己解決這件事才行。鷹身人正在肆虐我們的補給路線。如果我們把他們全都給做了，那條路就徹底安全了。$B$B當然，加茲魯維還教過我另一點，那就是「有錢能使鬼推磨」。那麼，你願意幫我的忙嗎， $N ?','殺掉12個杜洛塔鷹身人，任何種類的都行。','','去找杜洛塔的雷茲拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (837,'zhTW','野豬人的進犯','我們剛來這裡的時候，鋼鬃野豬人已經佔據了大片的土地，讓我們頭疼不已。經過不斷的努力，我們已經將絕大部分的野豬人都驅逐出去，不過在某些地區還殘留著防衛良好的野豬人。$B$B但是，這種情況已經持續太久了，我們要保護自己，我們絕不能允許鋼鬃野豬人佔據我們的領土。野豬人的營地就在西邊，只要找到荊棘就可以找到牠們。今天，我們把他們趕出杜洛塔，明天，我們就能把他們趕出整個卡林多。','替剃刀嶺的加索克殺掉4個鋼鬃野豬人，4個鋼鬃斥候，4個鋼鬃傳令兵和4個鋼鬃戰地衛士。','','去找杜洛塔的加索克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (844,'zhTW','平原陸行鳥的威脅','你對陸行鳥熟悉嗎?沒用的動物、飛不起來、愛玩、腦子只有我拳頭那麼大。遲鈍到不懂得避開移動的車子。多虧了牠們的硬腦殼，我不知折斷了多少根車軸...有時候我覺得野豬人是故意把牠們驅趕到我們車隊的路徑上，好為埋伏製造優勢的。$B$B讓我為你感到驕傲吧， $C 。砍殺一票那種骯髒的鳥，讓道路保持淨空，然後把牠們的鳥喙帶回來給我當做證據。','收集7個陸行鳥的喙。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (845,'zhTW','角斑馬','如果你想為我所深愛的部落服務，你得向我證明自己的力量，小子。你可以從狩獵角斑馬開始。角斑馬或許不是貧瘠之地上最兇猛的野獸，但忽視牠們的踢腿你可是會大感後悔。$B$B去獵殺北邊和南邊的角斑馬，並且收集牠們的蹄子。把蹄子帶來給我，或許我們就能接著派你去對付更兇猛的什麼東西。','殺死快步角斑馬並收集4只角斑馬蹄。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (848,'zhTW','菌類孢子','貧瘠之地的綠洲裡隱藏著一個謎。生命的能量從綠洲之水中湧出，給那些汲取水分的動植物帶來了勃勃生機。$B$B與此同時，這種能量也在慢慢地改變這些動植物。$B$B在綠洲附近生長著一種蘑菇，我們這些羅德隆的藥劑師發現這種蘑菇的孢子中包含有一些特殊的物質，它對我們非常有用。$B$B幫我帶一些孢子回來，我們會非常感謝你的。','從遺忘之池的蘑菇那裡收集5個菌類孢子。','','去找貧瘠之地的藥劑師赫布瑞姆。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (858,'zhTW','點火裝置','你該不會是斯布特瓦夫派來的吧?我被困在這兒了。我在不知道需要鑰匙才能啟動伐木機的情況下就貿然跳了進來。更蠢的是，當另一台伐木機的操作員問我是否一切正常的時候，我居然慌了!我沒跟他說我手裡沒鑰匙，而只是說機器有些問題。$B$B我們要趕緊離開這裡!到起重機上邊的控制室去，魯格維茲主管應該有這台伐木機的鑰匙。$B$B幫幫我!','從魯格維茲主管那裡取得點火裝置的鑰匙。','','去貧瘠之地找淤泥沼澤的維茲克蘭克的伐木機。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (861,'zhTW','獵人之途','我看得出來，你渴望探索。我也曾渴望到處漫遊...$B$B漫遊並且狩獵。狩獵是 $R 最高的榮譽。$B$B如果你真想走上獵人這條路，就向我展示你的能力和決心。把莫高雷一帶的平原徘徊者的爪子帶來給我。平原徘徊者非常兇猛、狡猾，對於想要成為獵人的年輕 $C 來說是最合適的獵物。','收集4隻平原徘徊者的爪子。','','去雷霆崖找獵人高地的梅洛·石蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (863,'zhTW','偷跑','我想我要好好學學才行……應該不會很難。就這些按鈕，一個操縱杆和兩個……對了，你準備好要出發了嗎?','保護維茲克蘭克以及他偷來的哥布林伐木機返回棘齒城的斯布特瓦夫那裡。','護送維茲克蘭克離開風險投資公司鑽井工地','去貧瘠之地找棘齒城的斯布特瓦夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (865,'zhTW','一定是角','貧瘠之地的迅猛龍比其他地區的迅猛龍更加聰明狡猾。我想它們的智慧就來自它們的角!如果是這樣的話，我可以將牠們的角磨成粉末，製成「智慧飲料」。然後就能賣掉大賺一筆!!!$B$B從這裡開始就是你的工作了:我想要最聰明那隻迅猛龍的角。「鐮爪王」在棘齒城北方的峭壁上帶領著一群聰明的迅猛龍。把角給我帶來!別想跟我派去的那些人一樣敲我竹槓!','取得鐮爪王之角。','','去找貧瘠之地的麥伯克·米希瑞克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (867,'zhTW','鷹身劫掠者','這些該死的鷹身人長期以來不停地攻擊和掠奪我們的補給商隊。現在該是我們割斷她們喉嚨，削減她們數量的時候了。$B$B我一直在她們的巢穴附近細心觀察，已經確定了誰是她們的領導者。我們應該先以削弱她們的作戰力量為目標，這樣才能徹底擊敗她們。$B$B慢慢來，先去幹掉那些在西北方出沒的巫翼鷹身人和巫翼遊蕩者，然後幫我帶8隻巫翼鷹身人的爪子回來吧。這應該是一個不錯的開始...','從巫翼鷹身人和巫翼遊蕩者身上收集8只巫翼鷹身人的爪子。','','去找貧瘠之地的達索克·快刀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (869,'zhTW','跟蹤竊賊','殘骸附近留下了巨大且彎曲的爪行足跡。這種足跡只有迅猛龍才有。$B$B你第一個直覺是迅猛龍騎兵襲擊了這個營地，但不是很確定，附近也找不到其他不屬於動物的痕跡。$B$B足跡朝東北方離開，往荊棘嶺的東邊而去。謎底一定就在那裏。','足跡通往荊棘嶺的東邊。跟著足跡走，看看你會找到什麼。','','去貧瘠之地找十字路口的加茲羅格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (870,'zhTW','遺忘之池','你感覺到那種震顫了嗎， $C ?某種東西將大地劈成了兩半。但我們德魯伊還能感覺到其他的震顫。$B$B生命正在曾經乾旱無生機的土地上顫動。十字路口周圍的綠洲是突然綻放的。我可以感覺到有股力量正不斷往地面洩露，但它的源頭是什麼?是否和讓貧瘠之地支離破碎的災難有關?$B$B我們必須找到那個源頭。前往十字路口西北邊的遺忘之池吧。在那裡的綠洲水中搜尋力量的源泉，然後回到這裡。','搜查十字路口西北邊的遺忘之池的底部。','探索遺忘之池','去找貧瘠之地的圖加·符文圖騰。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (871,'zhTW','保衛前沿哨所','所有的野豬人都是我們的敵人，而其中有些傢伙特別讓人討厭。$B$B剃鬃野豬人屢次攻擊往返於我們與杜洛塔之間的補給車隊。我的斥候一直在尋找這些襲擊事件的指揮者，但是在找到真正的幕後主使之前，我們總得想些辦法來打擊那些可惡的野豬人才行。$B$B就從這裡的南方開始搜尋，他們在河的附近襲擊我們的營地。找出他們，殺了他們。','殺掉8個剃鬃盜掠者和3個剃鬃獵手。','','去找貧瘠之地的索克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (887,'zhTW','南海海盜','加茲魯維答應給我升遷，只要我能幫助他解決棘齒城的海盜問題。麻煩的是，這些新來的海盜佔領了這裡南邊的勇士島。他們要的不光是我們的貨物，他們對我們有些私怨!某個晚上，他們甚至跑來追我們的一艘大帆船。$B$B我有個足以應付這情況的計畫，但加茲魯維想要儘快看見結果。前往勇士島，幫我砍一些腦袋下來，行嗎?','在勇士島上殺死8位南海殺手或南海私掠者。','','去找貧瘠之地的加茲魯維。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (888,'zhTW','被竊的貨物','我希望取回所有丟失的貨物，但我想那不太可能。不過，有些貨物是我必須要取回的!$B$B正如你所見的，我的天文臺馬上就要建好了，現在只差兩塊鏡片中較小的一塊。第一塊已由杜洛塔的商隊運到，第二塊運上了船，但現在還沒有到。對了，我還沒有收到藏寶海灣的崔斯里克給我發來的靴子!$B$B到海賊營地去一趟，看看能不能找到這些貨物吧。','幫棘齒城的加茲魯維取回一箱靴子以及一塊望遠鏡片。','','去找貧瘠之地的加茲魯維。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (891,'zhTW','船長的復仇','塞拉摩那些狂熱的人類又把我艦隊中一艘船給擊沉啦!$B$B他們的新海軍准將把船停靠在岸邊，任意占領或擊沉無辜的船隻。$B$B前往南方吧，沿著商旅海岸抵達他的營地。給我拿回他們水兵和水手的徽章，處死他的中尉皮瑞和巴克蘭。就像他們毀掉我的艦隊那樣，把他們給徹底消滅!','從塞拉摩水兵和水手身上收集10枚塞拉摩徽章，殺死皮瑞中尉和巴克蘭中尉。','','去找貧瘠之地的沙羅薩斯船長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (895,'zhTW','懸賞:葛瑞威船長','懸賞!$B$B少女之匕號的船長$BJ.葛瑞威$B$B罪名是在公海上搶劫、綁架、勒索、縱火、奴隸買賣等等。葛瑞威最近帶領了一夥南海掠劫者在附近海域出現，上一次被人目擊時，他們正在攻擊勇士島。領賞者必須提供可明確證明通緝者已死亡的證據!$B$B－加茲魯維','把葛瑞威船長的頭顱帶去棘齒城交給加茲魯維。','','去找貧瘠之地的加茲魯維。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (896,'zhTW','礦工的寶貝','嘿， $R ，你有對寶藏有興趣嗎?我就知道這能吸引到你。$B$B最近港口那有小道消息，就是說風險投資公司有個礦工在東北邊的石礦坑挖出了一枚足有拳頭大小的翡翠石。$B$B我知道有一些買主肯掏錢買那麼大一塊寶石，如果你幫我找到那塊寶石的話，那麼我願意和你五五分帳。你願意幫忙嗎?','從風險投資公司的某個監督者或者執行者那裡奪取貓眼翡翠。','','去貧瘠之地找棘齒城的碼頭管理員迪茲維格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (898,'zhTW','逃離監牢','終於有人來救我了!$B$B你居然能躲過那些守衛，這簡直是太不可思議了。這幫塞拉摩的狂熱分子已經毫無理智可言了。他們擊沉了我們的船隻，俘虜了我這個唯一的倖存者，還稱我為聯盟的敵人和威脅。$B$B你看我像是要威脅誰的樣子嗎?我不過是在棘齒城和藏寶海灣之間來回奔波的下等水手而已。$B$B一下子說了這麼多，你願意幫我返回棘齒城嗎?等你準備好了，我們就馬上越獄。','護送基爾薩瑞斯·火枝安全地返回棘齒城的沙羅薩斯船長那裡。','護送基爾薩瑞斯·火枝安全地返回棘齒城。','去找貧瘠之地的沙羅薩斯船長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (899,'zhTW','復仇的怒火','我的全家都被刺背野豬人殺害了， $C 。也許你能體會這種失去親人的傷痛，也許你不能…每天我都在這裡等著，從日出到日落，尋找這些罪無可赦的惡魔。$B$B從那天起，除了關在那邊的俘虜之外，我見一個野豬人就殺一個。但這依然遠遠無法平息我復仇的欲望。$B$B我想你這個 $C 能夠幫助我。$B$B去殺掉那些野豬人，能殺多少就殺多少。帶回它們的獠牙，讓我們一起為它們的死亡而慶賀吧。','收集60根刺背野豬人的獠牙，把它們交給十字路口的曼寇里克。','','去找貧瘠之地的曼科裡克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (900,'zhTW','負載平衡器','三個控制閥門都處於打開狀態。根據控制面板上的指示說明，在拆卸零件之前必須要把這三個閥門關閉。','關閉燃油控制閥、調節閥和主控制閥，然後再使用控制臺。','','去找貧瘠之地的控制台。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (901,'zhTW','負載平衡器','關閉設備後就可以開啟控制面板，從控制臺中移出主動式負載平衡器。一切準備就緒，現在你需要做的就是取得可以打開控制臺的鑰匙。','從技工斯尼格斯那裡拿到控制臺鑰匙。','','去找貧瘠之地的控制台。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (903,'zhTW','獵殺雌獅','如果你真想向我證明你的勇氣，那讓我派你去處理那些咬人真的很痛的傢伙吧。貧瘠之地的草原雌獅可是無與倫比的狡猾、機敏、迅速......而且致命。她們最近一直在城郊一帶騷擾我們的斥侯，尤其東北方最為嚴重。$B$B $N ，獵殺她們的時候要當心點，否則你可能會發現自己不是獵人，而是獵物。','從草原雌獅身上收集5個雌獅的爪子。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 916 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (916,'zhTW','樹林的腐敗','我是為了觀察居住在影絲洞的樹林蜘蛛才來到幽影谷的。我聽說了泰達希爾在最近賜下的祝福，照理說牠們應該不再具有那麼強的攻擊性才對。看來我被誤導了。$B$B最近我取得了一些牠們的毒囊，讓人憂慮的是，在它們裡面發現一種非常不健康的腐化。總而言之，如果我們放任被腐化的野生動物這樣子四處猖獗，我擔心會有不好的事情發生。$B$B我要你削減牠們的數量好爭取一點時間。','殺死12隻樹林蜘蛛。','','去泰達希爾找幽影谷的基爾沙蘭·風行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (917,'zhTW','樹林蜘蛛的卵','仔細想想，或許你能夠再幫我一點忙。我來這裡是為了在洞穴深處取得一顆樹林蜘蛛的卵，但那些蜘蛛可不樂意。如果你能取得蜘蛛卵並帶回去給迪蘭妮亞，我們都會很感激的。','取得一顆樹林蜘蛛的卵。','','去泰達希爾找幽影谷的基爾沙蘭·風行者。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (918,'zhTW','樹精的種子','泰達希爾的樹精是代表自然的元素生物，它們以某種方式反映了我們這裡的自然生態的情況。$B$B所以看到樹精變得如此憤怒真讓人感到擔憂。$B$B我相信這與土壤有關。我一直在用不同的方法種植植物，可以用樹精的種子來試驗一下。我請求你，能在奧拉密斯湖周圍的樹精那兒收集一些種子給我嗎?','取得6顆樹精的種子。','','去找泰達希爾的德納蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (919,'zhTW','樹精的新芽','小樹精在奧拉密斯湖周圍和湧泉湖以西迅速成長。我害怕它們會的數量會多到無法控制!我們應該在它們惹出亂子之前把它們從土地上清除。$B$B你在湖邊行走的時候，如果看到任何樹精的新芽長出來，就順便除掉它。讓我們的土地免受污染!','收集10個樹精的新芽。','','去找泰達希爾的德納蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (921,'zhTW','泰達希爾:艾澤拉斯之冠','該是你出發追尋自己命運的時候了， $N 。但是在你走出我們美麗的森林之前，你應該先好好瞭解我們近代的歷史。$B$B有一個你必須去完成的任務。到奧達希爾北邊的月井裡裝一瓶水。在那裡，你將會短暫地瞥見我們的魔法，並了解我們的過去。$B$B當你完成後，帶著水去找特納隆·雷拳。你可以在奧達希爾頂端的西方坡道上找到他。','裝滿水晶之瓶。','','去泰達希爾找幽影谷的特納隆·雷拳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (923,'zhTW','青苔之瘤','在樹精之中有一股邪惡氣息正在蔓延。我們試著找出源頭，但在我們找到之前……為了維護泰達希爾的安全，我們必須砍掉那些已經無法挽救的樹精。在北方湧泉湖一帶遊蕩的樹精受到的污染最為嚴重，你必須消滅它們!$B$B消滅在那裡發現的樹精，收集生長在它們身上的青苔之瘤，然後把那些瘤交給我，讓我燒掉它們。','取回5個青苔之瘤。','','去達納蘇斯找貿易區的雷利亞·綠樹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (929,'zhTW','泰達希爾:大自然的回絕','讓我告訴你所必須完成的任務的其他一些細節。達納蘇斯的德魯伊需要使用泰達希爾的月井的水，所以月井的水需要不斷地補充。使用這種特製的瓶子，你可以收集起月井之水。$B$B帶著這個瓶子去星風村外東邊的月井，裝滿水，再帶回來給我。注意聆聽月井給予你的訓誡，以免我們不斷擴張自己的缺點。','裝滿翡翠之瓶。','','去泰達希爾找多蘭納爾的科瑞薩斯·月怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (932,'zhTW','扭曲的仇恨',' $N ，我必須警告你，我們不能對這件事袖手旁觀。薩特已經夠我們頭疼的了，而眼前的這件事更是一個潛藏在身邊的危機。$B$B有個名叫邁雷納斯領主的惡棍就住在北邊附近的惡魔石洞穴裡，他在那兒聚集了一大批劣魔戰士。他的心就像夜晚一樣黑，而他的計畫一定極度黑暗邪惡。$B$B你必須在北邊附近的洞穴中找到他，帶他的頭回來見我。','取得邁雷納斯領主的頭顱。','','去泰達希爾找奧拉密斯湖的塔隆凱·捷根。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (933,'zhTW','泰達希爾:黎明將至','我想要你到此處的正南方去拜訪最後一口月井，就在亞里斯瑞恩之池的岸邊。尋找那口井時務必小心，隨時準備拔出武器。我感覺在泰達希爾南部有著日益增長的腐化。$B$B當你拿到水時，我希望你將它帶去給池邊的一張熟面孔。她想要和這種腐化戰鬥，並且是她親口要求你的協助。','裝滿紅玉之瓶。','','去泰達希爾找多蘭納爾的科瑞薩斯·月怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (937,'zhTW','神諭林地','我和一個哨兵小組被派到這裡來保護神諭之樹免受鷹身人的威脅。她們已經在沼澤周圍建造了很多巢穴，我們正在試著把它們趕回去。$B$B神諭之樹曾派信差到達納蘇斯去通報這一情況，但一群鷹身人在中途殺死了那個信差。$B$B如果你認為你能勝任這項任務的話，就到她們的巢穴裡去，殺死她們，把她們的腰帶拿回來作為證明。','收集6條血羽腰帶，把它們交給神諭林地裡的哨兵阿瑞尼亞‧裂雲。','','去泰達希爾找湧泉湖的哨兵阿瑞尼亞·碎雲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (943,'zhTW','健忘的勘察員','嗯，我在那裡會議之後把原始樣品交給了勘察員維爾。最近，我在洛克莫丹發現了雷魯之石，我認為它就是解開神秘化石的鑰匙。$B$B當我準備趕往維爾加挖掘場的時候，遭到了迅猛龍的攻擊，雷魯之石也給弄丟了。$B$B我不知道是哪只迅猛龍吞掉了這塊石頭，但如果你能找回它，我應該就可以釋放這些化石中的魔力了。當然，我們也需要最初從維爾加挖掘場取回的那枚化石。','米奈希爾港的考古學家弗拉岡特要你把雷魯之石帶給他。','','去濕地找米奈希爾港的考古學家弗拉岡特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (944,'zhTW','主宰之劍','我很奇怪納迦為什麼會出現在這裡，在黑海岸。但更奇怪的是...暮光之錘。那些信徒崇拜非常非常古老的大地之神，一個很久以前就被打敗的神。$B$B主宰之劍就是那個古神被打敗的地方。$B$B去那裡找到更多暮光之錘的信徒。$B$B帶上這個占卜之瓶。等你到了主宰之劍之後，就用它製造一個占卜之碗，通過那個碗，你可以直接和我通話。','收集資訊，然後使用占卜之瓶創造出一個占卜之碗，並利用這個碗和安努通話。','進入主宰之劍。','去找占卜之碗。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (945,'zhTW','護送瑟瑞露尼','救命呀!$B$B我正在主宰之劍附近散步的時候，這些骯髒的傢伙包圍了我。多虧我善於隱藏才沒有被他們找到!我很厲害吧!$B$B你能幫我離開這裡嗎?還有還有，你能不能給我姐姐瑟瑞希爾捎個口信，告訴她我平安無事?要不然她會擔心死的。她住在艾森娜神殿裡，那地方就在南方的梣谷森林裡。','幫助瑟瑞露尼逃跑，然後告訴在艾森娜神殿的瑟瑞希爾，她的妹妹目前很安全。','護送瑟瑞露尼離開主宰之劍。','去找瑟瑞希爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (947,'zhTW','洞中的蘑菇','我正在研製一種藥劑，需要一種生長在特定洞穴裡的稀有蘑菇才能配製。這個洞穴位於壁泉河瀑布的後面，在東邊稍稍偏北的地方。$B$B我本來準備自己去，不過古樹之林建議我不要靠近那個地方。我們尊貴的盟友覺得那個洞穴是黑海岸新出現的邪惡勢力的藏身之處。$B$B $N ，請你幫我收集那些蘑菇。與此同時，請察看一下那處洞穴以便確認古樹所擔心的事情。','收集5個粗柄蘑菇和1個毒帽蘑菇，把它們交給奧伯丁的巴瑞薩斯‧月影。','','去黑海岸找奧伯丁的巴瑞薩斯·月影。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (951,'zhTW','瑪塞斯特拉聖物','你在主宰之劍找到的那頁書來自於一本古籍...一本精靈撰寫的古籍。但它已經被暮光之錘詛咒和玷污了，看來暮光之錘的信徒是希望用古代精靈的魔法將他們古老的主人重新召回我們的世界。$B$B到東北邊的瑪塞斯特拉廢墟去看看，找到那些古代的聖物。如果我能研究一下它們的話，也許能搞清楚暮光之錘打算如何使用那些精靈的魔法。','收集6個黑暗深淵聖物，把它們交給古樹之林的安努。','','去黑海岸找暮光谷的安努。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (953,'zhTW','亞米薩蘭的毀滅','到東邊去就可以發現亞米薩蘭廢墟。現在，那些未曾安息的 $R 貴族的亡靈如同生前一般盤踞在那裡，那裡也曾經是艾薩拉的僕人練習他們強大魔法的地方。$B$B我在奉命探索那片廢墟的時候偶然發現有兩塊巨大的石碑，上面是潦草寫下的亞米薩蘭的故事，還有這座城市被毀滅的歷史。在我閱讀碑上的刻文的時候,突然有亡靈出現和我說話，嚇得我趕緊逃了回來。$B$B如果你夠膽量的話就去一趟那片廢墟，替我破譯一下石碑上的刻文。','研究刻有亞米薩蘭的故事及其被毀經過的石碑，然後回到黑海岸的哨兵坦莎‧月刃那裡。','','去黑海岸找亞米薩蘭的哨兵坦莎·月刃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (955,'zhTW','巴莎蘭','如果要我把一生的故事都講出來，恐怕你會失去耐心。簡單地說，我的一生漫長而痛苦，而現在這種鬼靈般的生活更是對我最痛苦的折磨。$B$B我被魔法囚禁在這裡。也許我說的話有些誇張，但我可以向你發誓，如果你能幫我找到從這裡逃脫的辦法，我一定會對你感激不盡的。現在我被施加了封印，如果你能幫我拿些薩特和劣魔的耳環，我也許能找到一些線索。','幫巴莎蘭的阿斯特利安收集8只劣魔耳環。','','去黑海岸找薄霧海的阿斯特利安。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (956,'zhTW','巴莎蘭','如果劣魔開始與施加在我身上的封印頻頻聯繫的話，我想我已經猜到原因了。毫無疑問，這枚封印已經落入指揮他們的薩特的手中。$B$B我強烈地感覺到了這一點， $N 。某個薩特得到了那個封印。如果你能得到它，或許就可以幫我衝破這牢籠，我將對你不勝感激。','獲取遠古月亮石封印，把它交給巴莎蘭的阿斯特利安。','','去黑海岸找薄霧海的阿斯特利安。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (957,'zhTW','巴莎蘭','某位非常強大的貴族製造了這個用來囚禁我的封印。在南方的亞米薩蘭有一處與這裡相似的廢墟，那裡至今仍燃燒著遠古的火焰，那藍色的火焰可以摧毀這個封印。$B$B不過在那片廢墟裡，你千萬要當心， $N ...','用亞米薩蘭廢墟中的遠古火焰摧毀遠古月亮石封印，然後回到巴莎蘭的阿斯特利安那裡。','','去黑海岸找薄霧海的阿斯特利安。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (958,'zhTW','精靈貴族的工具',' $C ，我有一項任務交給你。$B$B你去過亞米薩蘭廢墟嗎?如果還沒有，你可以在通向南方的大路東側找找看。亞米薩蘭廢墟曾經是眾多 $R 貴族的家園，而如今那裡卻成為他們濫用魔法的見證。$B$B據哨兵的報告，那些貴族的亡靈依然在使用古代的魔法武器進行抵抗。我們必須獲得那些聖物，只有這樣我們才有可能真正摧毀那些亡靈。','幫奧伯丁的桑迪斯‧織風取回7個精靈貴族的聖物。','','去黑海岸找奧伯丁的桑迪斯·織風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (959,'zhTW','港口的麻煩','啊呀!$B$B你也看到了，最近有點倒霉!早間從藏寶海灣過來了一支大型的運貨船隊，我是說大型的!我從沒有見過那麼多的木箱。我想加快點速度，所以卸貨卸得稍微快了點。$B$B結果呢，還沒等我弄清楚是怎麼回事兒，我看到那個可惡的傢伙─瘋狂的馬格利什─手拿一瓶99年波爾多陳釀跑了出來。我一路追他到了哀嚎洞穴，但是我可不想進到那個可怕的地方去。$B$B嗯……你夠不夠膽量去把他給我找出來?','棘齒城的起重機操作員比戈弗茲讓你從瘋狂的馬格利什那兒取回一瓶99年波爾多陳釀，瘋狂的馬格利什就藏在哀嚎洞穴裡。','','去貧瘠之地找棘齒城的起重機操作員比戈弗茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (962,'zhTW','毒蛇花','幽暗城的皇家藥劑師學會派我來這兒完成一個特殊的任務， $N 。我想你會願意幫助我的，因為黑暗女王領導下的被遺忘者將會通過我的任務得到進一步的加強。$B$B近來我在研究一種罕見的植物，它的名字叫毒蛇花，我相信這種藥草有著巨大的能量。$B$B不幸的是，它只生長在哀嚎洞穴的最深處，那是貧瘠之地最危險的洞穴之一。','為雷霆崖的藥劑師札瑪收集10朵毒蛇花。','','去找莫高雷的藥劑師扎瑪。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (963,'zhTW','永志不渝','永恆之井的戰鬥結束以後，亞米薩蘭被毀滅了，全城的 $R 都成為了這座城市的陪葬，其中就有我的至愛安娜雅。$B$B我也沒有想到，在那次災難過去了數千年之後，對安娜雅的回憶依然縈繞在我的夢中。有一次，當我恍恍惚惚地在黑海岸的森林裡遊蕩的時候，我發現自己正置身於亞米薩蘭的廢墟之中……我居然看見了我的至愛─她那飽受折磨的亡魂。$B$B她必須得到自由，但我沒有勇氣去做，因為讓她得到自由，就必須先摧毀她的亡靈。','釋放安娜雅·曦奔的靈魂，把她的墜飾交給奧伯丁的塞瑞利恩·白爪。','','去黑海岸找薄霧海的塞瑞利恩·白爪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (966,'zhTW','奧薩拉克斯之塔','一群術士在這座塔的裡裡外外住了下來。我本應該早些回去向艾麗莎報告，但我想如果我親自去報告的話也許會錯過些什麼。$B$B德爾葛蘭懷疑這夥人聚集在塔周圍是要密謀什麼壞事，但我們對此所知甚少。$B$B我手裡有一些術士的羊皮卷軸碎塊，但我還需要更多的碎塊才能解開這個謎。對了，我必須警告你，千萬不要冒險進入塔中，因為塔裡的術士非常可怕!','在奧薩拉克斯之塔附近幫巴蘇爾‧影擊收集4塊破舊的羊皮紙。','','去找黑海岸的巴蘇爾·影擊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (970,'zhTW','奧薩拉克斯之塔','巴蘇爾的這封信裡的消息真是可怕。這個暗灘教派對我們而言始終是一個很大的威脅，必須儘快清除才行。我和東北方的奧迪拉蘭中的暗灘教派打過交道，他們中的一個人持有一枚靈魂寶石，其中蘊藏著有關這個教派力量來源的秘密。$B$B把它交給我，我應該有辦法從中找出一些資訊來。','搜集一枚發光的靈魂寶石，並把它交給邁斯特拉崗哨的『淨化者』德爾葛蘭。','','去梣谷找邁斯特拉崗哨的淨化者德爾格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (971,'zhTW','深淵中的知識','收集傳說是我的義務。古老的傳說。強大的傳說。能開啟門扉的傳說，以及如果不好好處理，將能喚醒那些「沈睡者」的傳說。$B$B根據傳聞，有個古老傳說的片段，洛迦里斯手稿，就在西邊那處黑澗深淵的最底部。那地方是我們逝去已久的祖先的古老居處。在他們的城市淪為廢墟之前，他們掌握著偉大的知識。$B$B去黑澗深淵尋找那份手稿。我將不會忘記你曾為我這樣做。即使在這樣的末日之中。','將洛迦里斯手稿帶去黑澗營地給哨兵受訓員伊薩拉。','','去找丹莫洛的葛利·硬骨。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (973,'zhTW','奧薩拉克斯之塔','伊克魯德·瑪格蘇爾，沒錯，我瞭解他。他可是一個強大的獸人術士，就住在火痕神殿裡，那是一個位於梣谷西南的極端邪惡的地方。$B$B至今他並沒有給我們造成太大的麻煩，而我也沒工夫去對付他，不過現在看起來…他的死期到了。','把伊克魯德·瑪格蘇爾之書交給邁斯特拉崗哨的『淨化者』德爾葛蘭。','','去梣谷找邁斯特拉崗哨的淨化者德爾格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (976,'zhTW','奧伯丁的補給品','德爾葛蘭讓我給奧伯丁的哨兵艾麗莎·星風捎信，順便給她提供一定的補給，但是我討厭一個人上路。密林深處到處危險的敵人，我可不想讓這些物資和資訊落到他們的手裡。$B$B如果你或者其他人能擔當我的護衛，我們現在就可以出發了。有你的幫助，我堅信這些物資一定能平安運抵奧伯丁。','護送費羅·艾隆漢安全地穿越梣谷森林，再與邁斯特拉崗哨的『淨化者』德爾葛蘭談話。','護送費羅·艾隆漢','去梣谷找邁斯特拉崗哨的淨化者德爾格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (982,'zhTW','深不可測的海洋','從我們現在所在位置沿著海岸一直往北可以看到兩艘沉船-銀色清晨號和迷霧之紗號。這兩艘船在穿越茫茫大海，最終將要達到奧伯丁的時候遇到了那些可惡的魚人，它們現在只能躺在海底作為那些惡棍的戰利品了。$B$B這兩艘船的船長都沒有能倖免於難，他們的日誌以及其他有價值的東西還鎖在船裡的帶鎖箱中。我希望你能幫我找到這些東西，這對於那些生還的船員也是頗有意義的。','找到銀色清晨號的帶鎖箱和迷霧之紗號的帶鎖箱，把它們交給奧伯丁的高爾博多‧鋼手。你可以在村莊北部遇難的船隻裡找到這兩隻帶鎖箱。','','去黑海岸找奧伯丁的高爾博德·鋼手。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (983,'zhTW','傳聲盒827號','嘿!看看我這劃時代的最新發明:傳聲盒!通過它，你可以和很遠的人進行交談!$B$B也許你已經見過它們了，嗯，就是那些上面有操縱杆的盒子。不過傳聲盒有一個毛病，就是它們需要經常性的維護。$B$B而且每一個盒子的問題都不一樣，不過我在這個問題上做得就很巧妙!你看，我把每一個盒子都放在那些能給它提供最合適的修理零件的生物附近。現在傳聲盒827號出了點故障，它就在奧伯丁的南邊，需要6隻蟹腿來進行修理。我會獎賞你的...','收集6隻蟹腿，把它們放進傳聲盒827號。','','去黑海岸找奧伯丁的傳聲盒827號。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (984,'zhTW','熊怪的威脅',' $N ，我來這裡是想看看魔苔的影響有多麼厲害。我的一些同胞險些被泰達希爾的一個墮落的熊怪殺死，而我發誓不會讓類似的情況再次出現...更別提更糟糕的情況了。$B$B在黑海岸，我已經看見了一系列有關各種生靈墮落的線索，但我需要找到這種墮落是否有蔓延的跡象。我想我們仍然應該通過熊怪來進行調查，你可以幫我找到一個熊怪的營地嗎?如果你發現了任何情況，就馬上回來報告我。','在黑海岸找到一處墮落熊怪的營地，然後向奧伯丁的特倫希斯報告。','找到一處墮落的熊怪營地。','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (985,'zhTW','熊怪的威脅',' $N ，在偵察敵人方面，你已經展示了足夠的才能。但你與他們作戰的技能如何呢?$B$B並不是所有的冒險者都喜歡面對面的遭遇戰，我是某些冒險者更喜歡潛行之類的隱秘行動。$B$B如果你覺得自己能行，就到奧伯丁南邊的那個熊怪營地吧，那裡的熊怪對我們構成了極大的威脅。在那一帶活動的都是黑木部族的熊怪，去殺掉8個黑木探路者和5個黑木風語者，然後回來向我報告。','殺掉8個黑木探路者和5個黑木風語者，然後回到奧伯丁向特倫希斯彙報。','','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (986,'zhTW','丟失的主人',' $N ，你幫了我很多忙，我能不能再請求你幫助一下銳爪和他的主人沃科爾?我可以幫你精心製作一件有魔力的披風，它能夠讓你在尋找沃科爾時暢通無阻，免受黑海岸上任何猛獸的阻撓。$B$B不過要製作這件披風，我需要從月夜雄虎或者月夜雌虎身上獲取幾張張上等毛皮。你可以在急彎河以南找到那些月夜猛虎。','收集5張優質月夜猛虎毛皮，把它們交給奧伯丁的特倫希斯。','','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (994,'zhTW','殺出重圍','很好， $N ，就是這樣，讓我們一起衝出去。我們要殺出一條到銳爪身邊的路，到了那裡之後我們可以分開行動。$B$B不過我想特倫希斯一定會聽你來講述這次驚心動魄的逃亡，所以在我們活著離開這裡以後，別忘了儘快去一趟奧伯丁。','保護沃科爾離開，然後去和奧伯丁的特倫希斯談話。','幫助沃科爾逃到路上','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1001,'zhTW','傳聲盒411號','細小的聲音劈哩啪啦地從機器內部傳出來。$B$B「這裡是維茲班恩!下一個傳聲盒在奧伯丁北部海岸上的某個地方。我的記性有時候不太好，不好意思!$B$B那台傳聲盒的編號是411，需要3顆蛇頸龍的眼球來修理。你可能得跳進漆黑冰冷的大海深處去尋找黑海岸魚龍...真抱歉...$B$B就像上次一樣，只要你給傳聲盒帶去維修所需的物資，它就會給你吐出報酬的。*打嗝*...什麼?沒事，我很好!」','從位於傳聲盒411號附近的深海中收集3顆黑海岸蛇頸龍的眼球。','','去黑海岸找薄霧海的傳聲盒411號。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1002,'zhTW','傳聲盒323號','傳聲盒突然靜了下來，然後你聽見維茲班恩又開始說話。$B$B「下一個傳聲盒的編號是323。它在奧伯丁北部，不過...我的麥芽酒哪兒去了?什麼?哦，在路上，小橋邊，你不會找不到它的。」$B$B維茲班恩咕噥咕噥地說了一些不連貫的話，然後你聽見大口喝酒的聲音。$B$B「這個傳聲盒需要月夜猛虎的牙齒來維修...需要6顆。」','收集6顆月夜猛虎的牙齒，把它們放進傳聲盒323號。','','去黑海岸找壁泉河的傳聲盒323號。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1003,'zhTW','傳聲盒525號','在一陣什麼東西沸騰和油滴四濺的奇怪聲音之後，你聽見維茲班恩顫抖的聲音從機器中傳出。$B$B「順著這條路，在遙遠的南方就能找到下一個傳聲盒。應該不難發現它……就在路邊上……在柵欄附近。我想我把它藏在矮……矮樹叢裡了。呵呵呵……沒錯，傳聲盒525號得有從那些灰斑薊熊身上扒下來的灰色頭皮才能維修。對，灰色的……呵呵呵……」$B$B當機器停止下來的時候，你聽到更多類似吞咽的聲音。然後，突然之間，它又啟動了。$B$B「4塊!」','收集4塊灰色頭皮，然後把它們放在傳聲盒525號中。','','去黑海岸找暮光海岸的傳聲盒525號。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1007,'zhTW','古代雕像','我有一項任務交給你， $C 。$B$B當我坐船經過被淹沒的佐拉姆廢墟的時候，受到了納迦的攻擊。這些傢伙突然從水裡冒出來，他們的利爪差點就把我撕個粉碎!我拼命逃走，而最後的結果，就像他們說的，不用講你也知道。$B$B我是一個物種考古學家，而我正試圖找出那個失落的古老城市。$B$B你可以去西南方的佐拉姆海岸，並沿路找出所有的古老雕像嗎?正是為了這些東西，我才有勇氣到佐拉姆海岸這麼危險的地方。','收集10個古代雕像。','','去找梣谷的塔爾倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1008,'zhTW','佐拉姆海岸','在我們的西北海岸，也就是佐拉姆海岸一帶，潛伏著一股邪惡的勢力。$B$B佐拉姆海岸是已經被毀滅的佐拉姆城殘存的部分，佐拉姆主城在大爆炸中被摧毀，沉到了海底，這些很久以前發生的事情已經快要被 $R 忘卻了。$B$B現在，納迦又回來了。至於他們為什麼會回來，誰也不知道。但是這些並不重要，我們必須殺了這些魔鬼，把他們送回地獄!$B$B完成任務之後，就立刻回來向我報告。','收集20顆怒尾納迦的頭顱，把它們交給阿斯特蘭納的辛德瑞爾。','','去梣谷找阿斯特蘭納的辛德瑞爾·速火。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1009,'zhTW','盧澤爾','除非你能找到可以打開雕像上的那只鎖的鑰匙，否則雕像的秘密將永遠無法解開。$B$B那把鑰匙其實是一枚戒指，佐拉姆之戒。在這座城市被很久以前那場大爆炸所掀起的波濤淹沒之前，佐拉姆之戒曾經屬於這座城市的統治者。$B$B這枚戒指已經丟失很多年了，不過納迦最近找到了它。$B$B他們的領導者盧澤爾就住在佐拉姆北部邊緣的一個小島上。請幫我取回這枚戒指吧， $N 。','取得佐拉姆之戒。','','去找梣谷的塔爾倫。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1010,'zhTW','巴斯蘭的頭髮','在北邊那座巴斯蘭鬼屋的廢墟上，曾經生長著一種叫做巴斯蘭之髮的植物，它能夠讓人的靈魂安寧下來。$B$B在村莊裡有個患病的孩子，我想他的病痛不僅僅是肉體上的。你願意幫我到巴斯蘭鬼屋去尋找一些巴斯蘭之髮嗎?我需要用它來醫治這個孩子。$B$B巴斯蘭鬼屋就在邁斯特拉崗哨以北，梣谷和黑海岸交界的地方。','收集8份巴斯蘭之髮。','','去梣谷找邁斯特拉崗哨的奧雷迪爾·闊葉。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1011 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1011,'zhTW','被遺忘者的病菌','被遺忘者，部落中的不死生物勢力已經潛入了梣谷，現在就潛伏在我們的廢墟和洞穴之中。我們認為他們的目標是在 $R 的領地上散播疾病。這一點必須儘快得到確認!$B$B被遺忘者在南邊有一個營地，就在朵丹尼爾獸穴附近，那是他們製造和封裝毒物的地方。攻入那個營地，給我偷取一瓶病毒，我得研究一下這些毒藥，這樣才能搞清他們真正的意圖。','找到一瓶病毒，把它交給林歌神殿的凱尼斯‧靜風。','','去梣谷找林歌神殿的凱尼斯·靜風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1012,'zhTW','瘋狂的德魯伊','那些德魯伊死了，被他們那些因為部落污染了森林之心而發瘋的領導者們殺死!就連在這裡我也能感覺到那種腐化，我不敢再往前進。$B$B我和梣谷與森林之心的同調性太高，但你…你可以直闖那個獸穴，執行任何必要的任務。我已經為你在那裡設置了線索。$B$B儘管這讓我痛心疾首，我還是必須請求你這些曾經偉大的德魯伊領導者安息：坦尼爾·暗木、尤希爾·喚月，和瑪沃里斯·裂雲。','殺死發瘋的德魯伊：坦尼爾·暗木、尤希爾·喚月，和瑪沃里斯·裂雲。','','去梣谷找林歌神殿的凱尼斯·靜風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1013 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1013,'zhTW','烏爾之書',' $N ，在影牙城堡裡有一本書，烏爾之書，對我的收藏而言可說是極有價值的。烏爾在天譴軍團到來之前曾是達拉然裡一位偉大的法師，他對其他世界的研究對被遺忘者中的某些團體……很有價值。$B$B到影牙城堡裡找到這本書，把它帶給我，我會向黑暗女王彙報你的貢獻……','把烏爾之書拿給幽暗城鍊金區裡的看守者貝爾杜加。','','去找幽暗城的看守者貝爾杜加。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1014 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1014,'zhTW','除掉阿魯高','現在我已經對整個詛咒有了一個全面的瞭解，並開始著手研究如何補救了。$B$B但阿魯高依然好好地住在影牙城堡中。在幹掉阿魯高之前，我們還不能宣稱銀松森林已經是黑暗女王的地盤。$B$B但是，我得去搞明白怎樣才能根除他的魔法影響， $N 。所以我只能把除掉阿魯高的任務交給你了。$B$B到影牙城堡去，永遠地結束阿魯高的骯髒法術。把巫師的頭給我帶來!','殺死阿魯高，把他的頭帶給瑟伯切爾的達拉爾·織曦者。','','去銀松森林找瑟伯切爾的達拉爾·道恩維沃爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1016,'zhTW','收復密斯特拉湖','如果部落無法突破密斯特拉湖的水元素防禦時，我們可以很輕易地守住銀風避難所。$B$B他們其中一位薩滿，在泰德雷斯的森林中召喚出一個古老而憤怒的水靈，汙染我們的元素並使其轉而對付我們。湖泊與部落向我們步步進逼，我們毫無選擇，只能撤退到這個尖塔上。$B$B向東走。把湖泊拿回來，我們才有機會收復這個避難所。','殺死12個污濁的水元素與泰德雷斯。','','去找梣谷銀風避難所的哨兵維爾莉妮·星墜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1017,'zhTW','法師召喚者','這世上只有那個躲在貧瘠之地的不死族法師才能夠召喚出那麼多的水元素來。也只有像他那樣白癡的傢伙才會想要嚐試那麼做。這個薩瑞魯斯‧法伯尼可能正坐在鬼霧峰頂嘲笑我呢。$B$B $N ，你必須深入敵人的領地，除掉這個卑鄙的傢伙。關於這傢伙的白癡行為我已經聽說得夠多了。我們要讓他知道挑釁我們哨兵部隊會有什麼樣的下場。$B$B殺了他，帶他的人頭回來見我。不過你得當心，部落可能正監視著你。','殺掉薩瑞魯斯‧法伯尼，把他的首級交給銀風避難所的哨兵維爾莉妮‧星墜。','','去找梣谷銀風避難所的哨兵維爾莉妮·星墜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1022,'zhTW','狼嚎谷','儘管我們投入了大量的物資和人力想要將剩餘的惡魔趕出北方的費伍德森林，但是看來似乎並沒有什麼效果。我們只能把大部分的惡魔禦於梣谷之外。$B$B在北方的費伍德森林附近，有一群神秘的狼人佔據了麥爾莎迪絲神殿的廢墟。他們令人心顫的嗥叫使得那個地區得了個「狼嚎谷」的名字。保存在神殿中的麥爾莎迪絲之書也許能讓我們知道這些狼人出現在這裡的原因。','到狼嚎谷去，研究一下麥爾莎迪絲之書，然後向林歌神殿的哨兵梅麗瑞亞‧霜影覆命。','','去梣谷找林歌神殿的哨兵梅麗瑞亞·霜影。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1023,'zhTW','失落的寶石','在檢查泰洛尼斯的遺物時，你發現了一本完好無損的日誌。$B$B你收起日誌並留下泰洛尼斯的屍體。$B$B接下來你唯一要做的事，就是找到泰洛尼斯在找的那顆寶石。奧蘭迪爾曾經提過寶石就在這個地區。也許在那些觸鬚的手裡......?','找到發光的寶石。','','去梣谷找阿斯特蘭納的萊恩·狼行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1025,'zhTW','先發制人','在你出發去月井之前，如果你願意測試一下自己能力的話，我還有另外一項可以造福梣谷的任務交給你。$B$B沿著這條路一直向東走，在靠近弗倫河的地方有一些熊怪頻頻攻擊過路的旅客。他們扭曲的靈魂只有靠著恐懼才能得到撫慰，他們瘋狂的心智只有在啜飲無辜者的鮮血時才能得到滿足。$B$B幫助哨兵部隊守護我們的領地，讓那些熊怪知道血債是要血還的。$B$B我相信他們的營地應該在這條路的南邊...多加小心。','殺掉汙林族的1個汙林守衛者、2個汙林巨熊、10個汙林薩滿和12個汙林戰士，然後回去找阿斯特蘭納的萊恩‧狼行者。','','去梣谷找阿斯特蘭納的萊恩·狼行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1026,'zhTW','搜尋狼嚎谷','我希望你帶來比較好的消息。$B$B萊恩說的沒錯，我了解達圖爾的創造物與這個區域的樹人－至少我曾經了解過。現在他們已經腐化，他們的天性已經被扭曲。$B$B你需要找到一把鑰匙才能打開裡頭裝有下一段魔棒碎片的箱子。$B$B從這裡往東北方走，在費伍德森林邊緣一帶，有個地方叫做狼嚎谷，這把木製鑰匙在狼嚎谷的其中一個樹人身上。拿到鑰匙後，穿過山谷的地下通道，找到一片小小的空地。箱子應該藏在那附近。','找到木製鑰匙，並利用它取得達圖爾的魔棒的鐵杆部份。','','去找梣谷的莎爾蒂恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1027,'zhTW','尋找魔棒最後的部件','魔棒的最後一塊被交給了多丹尼爾德魯伊以保管。 我不知道他們把它藏在哪裡。 很抱歉，我不能為您提供更多幫助。$B$B我只能告訴您沿通往貧瘠之地的路標走。德魯伊人在那條路的東邊避難了，但對你沒有多大幫助：他們最近被殺了...這是我不願多想的事情。$B$B找到最後一塊時，帶上 交給我，我會幫助您重建魔棒。','取得達圖爾的魔棒的最後一段，鐵質柄頭。','','去找梣谷的莎爾蒂恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1031,'zhTW','塞納留斯的樹枝','安妮莉亞把手放在你的肩頭上，慢慢地把你拉近她的身邊。她艱難地喘著氣，抬手指向北方的拱門。在她的氣息漸漸變得微弱，眼睛慢慢地閉上之前，安妮莉亞留下了最後一句話:「被他奪走了...加薩里斯...」她臨終時還在想著要讓塞納留斯的樹枝回到林精的手中。','取得塞納留斯的樹枝。','','去梣谷找林歌神殿的伊莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1032,'zhTW','獵殺薩特!','我不敢相信安妮莉亞居然離我而去了……我們以前天天都在森林裡一起遊玩。我感覺很……難過。$B$B也許有一個辦法可以讓我感覺好一點。請你去殺了那些從我身邊奪走安妮莉亞的薩特!請你把它們的角拿給我作為證明，我會永遠感謝你的。','取得16支薩特的角。','','去梣谷找林歌神殿的伊莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1033,'zhTW','伊露恩之淚','我曾把挽救蕾拉的生命的希望寄託於奧蘭迪爾的醫術上，可讓我擔心的是，那只能延緩疾病在我孩子體內的蔓延而不能讓她徹底痊癒。我們一定要找到更有效的藥物!感謝奧蘭迪爾，他告訴我如果第一種治療方法不能起作用的話，還有下一步的治療方法。$B$B有一種名叫伊露恩之淚的特殊的石頭，只有在阿斯特蘭納東部的伊瑞斯湖中心的小島上才能找到它。奧蘭迪爾說這塊石頭能治療一切疾病...求求你， $N ，幫我找來伊露恩之淚，祈求它能結束我孩子的痛苦!','找到伊露恩之淚。','','去梣谷找阿斯特蘭納的皮爾圖拉斯·懷特姆恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1034 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1034,'zhTW','星塵廢墟','月神之淚減輕了我女兒的一些病痛，感謝伊露恩，她做惡夢的次數也大大減少了。可是……她仍發著高燒。$B$B奧雷迪爾告訴我，在南方的星塵廢墟中可以找到一種結晶的星塵，或許它能緩解蕾拉的高燒。請你幫我收集一些星塵吧， $N 。$B$B願伊露恩保佑你速去速回。','收集5份星塵，把它們交給梣谷的皮爾圖拉斯·懷特姆恩。','','去梣谷找阿斯特蘭納的皮爾圖拉斯·懷特姆恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1035,'zhTW','墜星湖','蕾拉的高燒退了，但她還是很虛弱。我想她很難靠自己的力量康復。我想要借助月亮石的魔力才能讓她痊癒。$B$B過去我們常在東南部的墜星湖搜集月亮石……但是食苔沼澤獸來了之後就不行了。$B$B這群野獸的領袖是一個沼澤獸神諭者，它收集所有從天上掉下來的月亮石並把它們藏起來。現在，你得從沼澤獸神諭者那裡拿到一枚月亮石。$B$B要達到此一目的，恐怕你必須先殺了那個沼澤獸神諭者。','從沼澤獸神諭者那裡取回一枚隕落的月亮石，並把它帶給阿斯特蘭納的皮爾圖拉斯·懷特姆恩。','','去梣谷找阿斯特蘭納的皮爾圖拉斯·懷特姆恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1038 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1038,'zhTW','維琳德的日記','你是由麥爾薩迪斯之書中得知這一切的?我認為你應該去檢查一下她的所有物品，雖然那樣做可能不太妥當。用這把鑰匙可以打開她放在哨兵小屋裡的箱子。她把平時的工作都記錄了下來，因此你從她的日記中應該可以瞭解到很多事情。$B$B我應該告訴你，哨兵們認為她是因為某些特殊的原因而離開的，她隨時都有可能再回來。女祭司過去做過很多讓我們對她倍加信賴的事情。','在維琳德的箱子裡搜尋她的日記，把日記連同鑰匙一起交給達納蘇斯的塞恩提爾‧刃紋。','','去達納蘇斯找戰士區的塞恩提爾·刃紋。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1041,'zhTW','商隊通路','若我說的不對請不要見怪，我應該記得沒錯，畢竟不是每天都會發生這樣的事兒的。$B$B我記得你要找的那個維琳德。那是不久前發生的事，要知道，不是每天都會有一位元漂亮的 $R 女祭司會願意搭著我這輛破爛的大蓬車旅行的，不過，我的車用來代步的確很不錯，不是嗎?$B$B我們在向北去的路上分手了，她往夜色鎮去了。那裡的書記員應該有所有的出入記錄，或許從那裡你能知道些對你有用的東西。$B$B在叢林裡你最好多加小心，即使是在安全的時節，那兒仍然是個危險的地方。','與夜色鎮的書記員達爾塔談話。','','去暮色森林的夜色鎮找書記員達爾塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1043,'zhTW','月神的鐮刀','你的故事聽起來不像是假的...我不能完全理解你的動機，不過如果你想要除掉暮色森林的狼人，我就不需要瞭解這些。$B$B在南方有一座礦山，很多狼人在那裡出沒...天知道他們是從哪裡冒出來的，不過據我們所知，他們最早就是在那裡出現的。$B$B去忙你的吧，不過如果你有什麼重要消息，請一定要告訴我。我們需要所有能幫我們對抗邪惡的資訊。','去找關於月神鐮刀的消息，然後回到夜色鎮見喬納森‧卡爾文。','','去暮色森林找夜色鎮的喬納森·卡爾文。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1045 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1045,'zhTW','蘭恩的淨化','我很確定，那個早已死透的巫師達圖爾，原本打算要用他的魔棒征服並摧毀我們，就像 $R 與獸人一樣。但我想現在我們可以拿這個魔棒用在其他用途上。$B$B蘭恩·血牙是梣谷中所有熊怪的首領。他的血牙族人是部族當中最強大的，並隱居在東方一個僻靜的營地。$B$B殺光他們，並把他的腦袋帶回來。我們來試試能不能把這個腦袋好好地利用一下。','取得蘭恩·血牙的顱骨與達圖爾的魔棒。','','去梣谷找密斯特拉湖的克羅爾格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1050 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1050,'zhTW','泰坦神話','未來是已經命中註定了的!我們的命運就像雨點落入大海一樣無可改變。$B$B不過研究過去也許可以讓我們預見未來，並提前做好一些準備。$B$B在災難降臨在羅德隆之前，提里斯法林地中有一處藏有許多書籍的地方─老修道院的圖書館，據說有一本《泰坦神話》就收藏在哪裡。$B$B把它給我拿回來，也許我們可以一起揭開過去的秘密!','從修道院拿回《泰坦神話》，把它交給鐵爐堡的圖書館員麥伊·蒼塵。','','去鐵爐堡找探險者大廳的圖書館員麥伊·蒼塵。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1054,'zhTW','解除威脅','從阿斯特蘭納出發，一直向北走，你能看到許多薊皮熊怪。我的斥候向我報告說，熊怪的數量在最近幾個月裡成倍地增加。如果它們的數量變得足夠多的話，就可能會直接向阿斯特蘭納發起攻擊。$B$B你能殺掉多少熊怪就殺多少，但你要把他們酋長的顱骨給我帶回來作為證明...$B$B我會留在阿斯特蘭納等你的消息，願伊露恩與你同在。','把達爾‧血爪的顱骨交給阿斯特蘭納的萊恩‧狼行者。','','去梣谷找阿斯特蘭納的萊恩·狼行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1057,'zhTW','奪回焦炭谷','你應該能猜出來，身為森林之靈的保衛者的我為什麼會如此憤怒。$B$B你翻越了無數山嶺來到這裡，一路上你應該已經看到在這片土地上都發生了些什麼。貪婪正在將這神聖的山脈引向毀滅的深淵。$B$B南方的焦炭谷正在遭受那群貪得無厭的機械化工業大軍的荼毒。更糟的是，那裡的鷹身人竟然拒絕讓我們進入那裡撫慰大地受到的創傷。$B$B把這群骯髒的鷹身人給我趕出去， $N !','石爪峰的守護者奧巴格姆要求你殺死7個血怒鷹身人、7個血怒伏擊者、7個血怒殺戮者和7個血怒遊蕩者。','','去石爪山脈找石爪峰的守護者奧巴格姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1062,'zhTW','哥布林侵略者','哥布林經營的風險投資公司搬到石爪山脈裡面砍伐樹木與焚燒大片的森林。這片土地的守護之靈們的眼中已經充滿痛苦與憤怒。我們必須阻止風險投資公司!$B$B到西北邊的巨木谷後方，進入狂風峭壁。你可以在那裡找到正在工作的哥布林和他們的僕人 - 讓他們知道部落絕對不會允許他們任意破壞石爪山的環境。用他們最容易理解的語言來讓他們了解……$B$B暴力。','殺死15個風險投資公司的伐木工，然後回去找石爪山與貧瘠之地交界處的希雷斯·碎石。','','去石爪山脈和貧瘠之地的交界處找希雷斯·碎石。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1069 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1069,'zhTW','深苔蜘蛛的卵','煎蜘蛛卵是藏寶海灣的時尚菜肴。問題是……藏寶海灣的蜘蛛卵已經斷貨了。$B$B我發誓這絕對是個賺錢的好機會!$B$B在狂風峭壁─就是石爪山的西北地方─那裡有一種深苔蜘蛛，如果你能幫我弄來一些深苔蜘蛛的卵的話，我一定會付給你一大筆錢!$B$B這些蜘蛛最喜歡在樹蔭下爬行……但可惡的風險投資公司砍掉了它們賴以生存的大樹!$B$B不過，你還是到狂風峭壁去找找深苔蜘蛛吧，它們的卵在有樹的地方還是很多的。','收集15顆深苔蜘蛛的卵，把它們交給棘齒城的麥伯克‧米希瑞克斯。','','去貧瘠之地找棘齒城的麥伯克·米希瑞克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1071 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1071,'zhTW','地精學者','你看， $N ，我也是偉大的魔法、化學和工程學研究會的成員，我的目標……嗯嗯，我的使命，便是好好教導這幫 $R 們，讓他們知道魔法、化學和工程學的融合便可拯救他們的森林!$B$B但這是一場艱苦的戰鬥，哥布林們的繁殖速度簡直就像兔子一樣。我甚至沒有時間去搞新的發明!$B$B我需要些時間來進行計畫和組織。但這需要你的幫助，去幫我把東邊狂風峭壁那裡的綠皮玩意們幹掉一些。','殺掉10名風險投資公司伐木工和10名風險投資公司砍樹工，然後向石爪山的加克希姆·塵鏈覆命。','','去石爪山脈找蛛網小徑的加克希姆·塵鏈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1073 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1073,'zhTW','失職+藥劑=快樂','哈哈哈……你來搞硝酸甘油炸藥是為了阻止哥布林們破壞森林?!$B$B我現在不關心你和加克希姆到底熟不熟了……我可以把這玩意給你，誰管最後是你還是他們被炸成碎片!$B$B但是還有一個小問題，我現在身邊沒有成品。$B$B只要你把我需要的材料帶給我，我就可以馬上給你做一些。$B$B但在這之前，至少你得證明你在鍊金術方面不是個白癡。','給鐵爐堡的洛瑪克·鏈帶拿去4瓶初級法力藥水和2瓶初級堅韌藥劑。','','去找鐵爐堡的洛瑪克·鏈帶。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1076,'zhTW','西部荒野中的惡魔','啊，有了。一個傳信法術……我相信你需要的就是這種效果。$B$B我會為你做一張抄寫有這道法術的卷軸，不過要完成它，我得先弄些塵魔的殘骸來。$B$B在我找到其他的材料之前，你能到西部荒野去給我抓一隻這種邪惡的生物回來嗎?它們的確很危險，但我肯定，如果你想為加克希姆的實驗做點什麼貢獻的話，沒什麼是你不能搞定的。$B$B我會在這裡等你回來。','將塵魔的殘骸帶回給暴風城的科林·瑪林。','','去找暴風城的科林·瑪倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1078,'zhTW','完鱗歸瑪倫','旅人們一直在問我有關石爪山的事情，看來那裡已經成為一個公認的最佳冒險場所了─當然前提是你沒有在尋找雙足翼龍、元素生物，也沒有跟風險投資公司扯上關係。$B$B在石爪山脈深處的焦炭谷中還居住著一群披著厚重鱗片的蜥蜴。把那些鱗片磨成灰就是我施放一些法術所必需的原料。$B$B如果這些蜥蜴還活著的話，你能不能幫我搞一些它們的鱗片來?$B$B注意點時間，不用太著急，而且我會付給你不錯的酬勞。','給暴風城的科林·瑪倫帶回8片晶化鱗片。','','去找暴風城的科林·瑪倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1079,'zhTW','隱秘行動:A','就是這樣啦， $N 。仔細看著，裝置已然準備就緒了。$B$B拿著這幾張紙─上面已經把引爆和爆炸的具體情況全寫明白了呀，當然，包括你該把這些爆裂物放在哪兒。$B$B記住，任務的成功與否並不取決於你炸毀了多少東西，A計畫的成功取決於你是否從峭壁湖南部的伐木場裡帶回了風險投資公司的計畫書。','將風險投資公司工程計畫書從狂風峭壁的伐木場中偷出來。','','去石爪山脈找蛛網小徑的加克希姆·塵鏈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1080,'zhTW','隱秘行動:B','B計畫跟A計畫差不多， $N 。$B$B我們分散他們的注意力，然後將重要的信函都給偷出來。$B$B關鍵是要弄到他們的信件……記住這一點。$B$B我給你的紙上已然寫明白了你該把爆裂物放在哪裡。去吧，活著把那些信帶回來……','將風險投資公司函件從狂風峭壁最東面的狂風礦坑中偷出來。','','去石爪山脈找蛛網小徑的加克希姆·塵鏈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1083,'zhTW','怒靈','我不敢肯定風險投資公司對這座山谷做了些什麼，不過顯然他們剛來的時候根本沒有能力和這裡的生物抗衡。$B$B於是他們只好在這裡放了一把大火，然後用他們那強大的機器在山谷裡四處屠殺。$B$B而且，這些無知的傢伙還釋放出了一些亂七八糟的元素生物，把山谷搞得一團糟。$B$B這些生物在谷中隨意遊蕩，連伊露恩都不再眷顧這片土地了。$B$B幹掉那些元素生物，把它們身上的悶燒餘燼帶給我，以此來作為你曾奮力拼殺的證明。','從焦炭谷中的任意火元素身上收集8個悶燒餘燼，把它們交給石爪山的凱拉·影矛。','','去石爪山脈找蛛網小徑的凱拉·影矛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1084,'zhTW','受傷的古樹','顯然，那些一直以來都保衛者著山谷的樹人們也已開始了驅逐風險投資公司的行動。不幸的是，甚至是這些最偉大的保衛者們也開始逐漸墮落。$B$B加克希姆認為他們的墮落與哥布林們撤退時所使用的某種武器有關。$B$B我告訴他，我打算從某個受傷的樹人那裡收集一份樣本，這樣他就可以通過對這份樣本的研究來確定這個推斷是否屬實。$B$B給我帶回一些彈片來，好讓那個地精來研究它……','給石爪山的凱拉·影矛帶回一塊被腐蝕的彈片。','','去石爪山脈找蛛網小徑的凱拉·影矛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1090,'zhTW','格雷蘇的要求','你知道的，我曾經是這裡的二老闆，但在格雷蘇接管了這裡之後，一切就全變了。我的老闆菲茲克斯被他炒魷魚，而我被丟到這個礦坑裡來當苦力。菲茲克斯就讓我待在這裡，暗中收集資訊，如果我們能知道格雷蘇在打什麼算盤，菲茲克斯的新老闆就會付給我們不錯的酬勞。$B$B無論如何，現在我知道的是，格雷蘇下令要大量地開採這種青綠色的礦石。要不這樣，我幫你作一份樣本出來，你幫我帶給菲茲克斯，但是我在採集礦石的時候，你得幫我留意外面的巡邏兵。','在匹茲尼克完成開採之後拿到神秘礦石。','在匹茲尼克採礦時保證他的安全。','去找石爪山脈的匹茲尼克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1093,'zhTW','超級收割機6000','風險投資公司到底在搞什麼鬼啊，嗯?他們到底在想些什麼呀?哥布林的公司裡竟然雇傭了一個地精!$B$B好在斯布特瓦夫是個識貨的傢伙，知道我是個天才，他在我被公司炒了以後馬上就雇傭了我!$B$B據說公司正在製造一種新型的大型伐木機，斯布要把我這東西的設計書偷來給他。不過格雷蘇─那個滿手是血的地精─他一看見我就想把我給幹掉……或許你能替我去把設計書給偷來?你應該可以在他們的操作員身上找到它。','為石爪山的菲茲克斯偷來超級收割機6000型的設計圖。','','去石抓山脈找狂風峭壁的菲茲克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1096,'zhTW','格雷蘇','我只見過格雷蘇一次，但我得告訴你，那傢伙一眼看起來就知道他不好對付。他的一部分身體似乎已經殘廢了，於是他給自己裝上了一些金屬部件和裝備，這樣他的部分肢體就機械化了。$B$B格雷蘇就在東北方峭壁湖的湖岸邊上監視著整個地區的工作進展。我想我是沒辦法去那裡了……但你看起來也許有能力對付他。$B$B如果你能為我幹掉他的話，我會付給你不錯的酬勞的。','將格雷蘇的機械臂帶給石爪山脈的菲茲克斯。','','去石抓山脈找狂風峭壁的菲茲克斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1105 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1105,'zhTW','硬化龜殼','我的兄弟正在為他的火箭車研究一種新燃料。他很聰明，真的是太聰明了……我想他設計的新燃料一定非常強悍，強到甚至可以蝕穿車子的底盤!$B$B為了防止這種情況的出現，我得應該強化一下油箱。$B$B這片平原上的烏龜有很硬的殼，我想用它們來製造火箭車的新油箱，這樣就可以裝載我兄弟的新燃料了。$B$B你看起來很可靠，願意去給我弄一些這樣的殼嗎?','收集9塊硬化龜殼，把它們交給閃光平原的維茲爾·銅栓。','','去千針石林找沙漠賽道的維茲爾·銅栓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1109 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1109,'zhTW','蝙蝠的糞便','就如你所見到的一樣， $N ，我們正要在皇家藥劑師學會進行一個非常…嗯…有趣的實驗。$B$B作為這裡的領導者，我的職責就是監管所有最具潛質的化學實驗。所以說我總是夢想太多，時間太少!$B$B你看起來是個擅長跑腿的 $C ，也許你可以幫我的忙。$B$B我需要一種稀有的原料，這種原料只有在產於剃刀沼澤的一種罕見的蝙蝠身上才能找到。去剃刀沼澤幫我帶回一些沼澤蝙蝠的糞便來，然後我們就可以開工了……','幫幽暗城的藥劑大師法拉尼爾帶回一堆沼澤蝙蝠的糞便。','','去找幽暗城鍊金房的大藥劑師法拉尼爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1134,'zhTW','石爪山的雙足翼龍','儘管我們還沒有跟部落全面開戰，但是這來之不易的和平卻已經處於崩潰的邊緣了，最近他們愈加頻繁地展開針對我方的秘密行動。$B$B我們安插在塞拉摩的密探向我們報告說，在石爪峰南面的暗色湖一帶有許多巨翼雙足翼龍在活動，而獸人正在該地收集它們的毒液，然後獸人的刺客就會使用這些毒液，無聲無息地對聯盟發動致命的突襲!$B$B如果他所說的都是真的，那麼我們就必須阻止他們， $N 。我們必須切斷他們的毒液來源!','收集12個巨翼雙足翼龍的毒囊，並把它們交給阿斯特蘭納的辛德瑞爾‧速火。','','去梣谷找阿斯特蘭納的辛德瑞爾·速火。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1138,'zhTW','海中的水果','我愛螃蟹，螃蟹就好像是海中的水果!你可以把它烤了吃、煮了吃、燉了吃、炸了吃、炒了吃、煎了吃;你可以把螃蟹做成螃蟹沙拉、螃蟹湯、螃蟹燉肉、黑胡椒螃蟹、檸檬汁燉螃蟹、清蒸螃蟹和鐵爐堡特級螃蟹─這就是螃蟹存在的意義!$B$B我現在要留在這裡釣魚，所以沒有辦法自己去找到上好的螃蟹肉。你可以從暗礁蟹和硬殼潮行蟹身上得到品質上乘的螃蟹肉，然後把它們烤了吃、煮了吃...','收集6塊優質蟹肉，把它們交給奧伯丁的古博‧布拉普。','','去黑海岸找奧伯丁的古博·布拉普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1140,'zhTW','奧薩拉克斯之塔','獸人們寫起字來比小孩子的塗鴉好不到哪裡去。當我決定去學習他們的語言時，我的許多部下都曾經取笑過我，但我想這樣做還是有助於進一步瞭解我們的敵人。$B$B從伊克魯德的亂七八糟的文字中，我們可以知道埃瑟里克斯仍掌握著兩顆靈魂寶石，它們分別被放在梣谷東北部的夜道谷和薩提納爾，這兩個地方都是被薩特控制的地區。$B$B小心點， $N ，面對那些被薩特之血浸透了地面的神殿，即使是像你這樣經驗豐富的 $C 也會心神不寧的。','在夜道谷和薩提納爾找到被禁錮的精靈貴族的靈魂，釋放他們，然後回到邁斯特拉崗哨的『淨化者』德爾葛蘭那裡。','','去梣谷找邁斯特拉崗哨的淨化者德爾格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1141,'zhTW','釣魚世家','布拉普家族一向以酷愛釣魚而聞名。我的名字叫古博‧布拉普，我在釣魚。$B$B在這個地區我最希望釣到的魚是黑海岸石斑魚。以前我會坐船出海專門釣這些石斑魚，但是由於那些該死的魚人的出現，我已經很久沒有出海釣魚了。我打賭那些魚人早把這裡的石斑魚給吃光了。$B$B那麼說來，你願意幫我抓一些黑海岸石斑魚回來?如果你願意的話，我可以給你一把貨真價實的布拉普家族魚竿!這根魚竿可是釣魚時的乘手工具啊!','為奧伯丁的古博‧布拉普抓6條黑海岸石斑魚。','','去黑海岸找奧伯丁的古博·布拉普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1143,'zhTW','奧薩拉克斯之塔','我知道了。如果你所說的是真的，那麼我們必須馬上發起進攻。我認為埃瑟里克斯就住在塔上。不過你要當心，在他的周圍有很多強大的術士，比你以前所見到過的任何術士都還要可怕。','殺掉埃瑟里克斯‧納拉辛，把他的項上人頭交給奧薩拉克斯之塔附近的巴蘇爾‧影擊。','','去找黑海岸的巴蘇爾·影擊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1199,'zhTW','暮光之錘的末日','受到混沌古神的古老儀式驅動，暮光之錘的成員致力於他們黑暗的守護神召回這個世界，在整個世界上散佈死亡和恐怖。$B$B我們相信暮光之錘已經和納迦達成聯盟，並且正群聚在西邊的黑澗深淵裡面。$B$B不論在那古老神殿的深淵中醞釀著怎樣邪惡的計畫，我們都必須讓它消失。$B$B向暮光之錘開戰，並且帶回你成功的證據。你的努力將獲得優渥的回報。','收集10個暮光墜飾，把它們交給黑澗營地的哨兵阿露溫。','','去達納蘇斯找工匠區的銀月守衛瑪納杜斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1200,'zhTW','黑澗深淵中的惡魔','我體內的力量已經流失。我需要你的幫助!$B$B很久以前這個地方是崇拜伊露恩的偉大神殿。但一名古神的腐化從地底滲透而上，污染了神聖的月井，導致這地方不幸地化成了廢墟。$B$B阿庫麥爾，古神的僕從，從水中崛起。$B$B暮光之錘教徒和納迦們結成同盟，好來侵佔這些土地。這些教徒，接受著克爾里斯的領導，將無辜的生命獻祭給阿庫麥爾來獲取力量。$B$B殺死克爾里斯，並將他的頭顱帶去給黑澗營地的阿謝蘭， $N 。拜託你。','將暮光領主克爾里斯的頭顱帶去黑澗營地給阿謝蘭‧北木。','','去找達納蘇斯的哨兵塞爾高姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1221,'zhTW','藍葉薯','藍葉薯是美味絕頂的佳餚!但是這種東西很罕見，非常非常罕見。它們只生長在貧瘠之地，在剃刀沼澤的地下深處。$B$B不過知道這一點也沒什麼用，因為如果你不知道它們的確切位置，那麼就算近在咫尺你也不一定找得到它們。這就是我訓練這些地鼠去尋找藍葉薯的原因─它們有很靈敏的嗅覺，在五十步以外就能嗅到藍葉薯塊莖的氣味。$B$B這差事並不輕鬆，但是如果你幫我弄來一些藍葉薯的話，我會付給你一筆可觀的報酬。','找到一個開孔的木箱。','','去找貧瘠之地的麥伯克·米希瑞克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1267,'zhTW','失蹤的使節','在塵泥沼澤找珍娜·普勞德摩爾談談。','與塵泥沼澤的吉安娜·普羅德摩爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1275,'zhTW','研究墮落','愚蠢的血精靈們已經徹底陷入了對魔法的狂熱之中了，難道他們沒有見到卡林多大陸上的薩特與納迦們身上發生了些什麼嗎?$B$B我總覺得血精靈們也將會踏上這樣一條不歸之路，但是艾澤拉斯已經無法再承受多一種被魔法扭曲了心智的怪物了。$B$B我希望能夠研究一下薩特和納迦的腦幹組織，這樣也許就能瞭解那些精靈們的命運將會走向何方。在梣谷海岸邊的黑澗深淵中有許多薩特和納迦，你去那裡找一找吧。$B$B這將會是一段漫長的旅程，一路小心， $N 。','黑澗營地的芮爾溫‧影星需要8塊墮落者的腦幹。','','去黑海岸找奧伯丁的戈沙拉·夜語。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1360,'zhTW','尋回寶物','我本來有個不錯的工作，就是在荒蕪之地的奧達曼挖掘場當挖掘工……直到那些該死的穴居怪出現之後。我驚險地逃了出來，而且還什麼也沒來得及拿。在一片慌亂之中，我弄丟了我最重要的財產。我那箱子很難撬開是沒錯，不過你知道嗎，那裡滿地都是穴居怪!$B$B你去幫我拿回箱子來，我就好好謝你!那個寫著我名字的箱子就在北部大廳的盡頭，你得一路殺進去才行。','到奧達曼的北部大廳去找到克羅姆·粗臂的箱子，從裡面拿出他的寶貴財產，然後回到鐵爐堡把東西交給他。','','去找丹莫洛的克羅姆·粗臂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1446,'zhTW','『預言者』迦瑪蘭','我的枯木同伴們通常對家裡附近的陌生人都不太友善。$B$B我?我已經沒有家了。我被我悲傷沼澤的阿塔萊族的同胞流放到這裡。$B$B我們的精神領袖迦瑪蘭曾有過一個「預言」，他聲稱召喚哈卡能帶給阿塔萊族永恆的生命。$B$B但是我覺得有些不對勁的地方，如果這個預言僅僅是為了操縱我們，那我們該怎麼辦?$B$B我要為他們流放我的舉動復仇，給我把迦瑪蘭的頭帶回來，也許這樣我的同胞就可以重獲自由。','辛特蘭的阿塔萊流放者想要迦瑪蘭的頭。','','去辛特蘭找沙德拉羅的阿塔萊流放者。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1491,'zhTW','智慧飲料','好吧，所以迅猛龍角似乎不太有用。不過沒關係，萬事起頭難嘛!而且我想我找到了另一種原料，可以讓我製造出更好的智慧飲料!$B$B有一種物質名叫哀嚎香精，我想這種東西就是造成貧瘠之地出現各種奇特動植物的原因。幫我找到這種物質，我要把它加入我的飲料裡試試看!$B$B我聽說這種物質可以在西邊的哀嚎洞穴裡的那些生物身上被找到，去獵捕那些生物，幫我收集哀嚎香精吧。','收集6份哀嚎香精。','','去找貧瘠之地的麥伯克·米希瑞克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1498,'zhTW','防禦之道','作為一個 $C ，我們最重要的任務之一就是……保護。我們是部落的護盾，我們要保護比我們弱小的同胞的安全。如果你要加入我們，那你就必須先向我證明你的毅力。$B$B到杜洛塔的雷霆山去，那裡有不少閃電蜥蜴和雷霆蜥蜴。去獵捕那些蜥蜴，向我證明你比牠們更加強大!在牠們的攻擊面前要毫不畏縮，帶一疊牠們燒焦的鱗片回來給我作為證明。$B$B完成這個任務之後，我就教導你。','帶5塊燒焦的鱗片回來給貧瘠之地前沿哨所的猶塞克。','','去找貧瘠之地的猶塞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1503,'zhTW','鍛造好的鋼錠',' $N ，我會給你一柄武器，但首先我需要你的幫助。幾天前的一個晚上，西北邊的那些鋼鬃部落的傢伙摸進了我的營地，他們不敢和我正面交戰，但是他們知道我眼睛不好使，所以就想辦法用響聲把我引出來，然後派幾個同夥溜進去偷了我的東西!$B$B他們偷走了一隻鐵箱子，裡面是一些鑄造好的鋼錠。如果你能夠找到它們的話，我就會給你一件你用得到的武器。$B$B你應該可以在鋼鬃野豬人的營地裡找到那只鐵箱子，把那些鋼錠給我拿回來。','把鍛造好的鋼錠帶給貧瘠之地的索恩格瑞姆·火眼。','','去貧瘠之地找荊棘嶺的索恩格瑞姆·火眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1582,'zhTW','月光外衣','達納蘇斯的居民，尤其是像我這樣的手工藝者，都是相當繁忙的。年輕的冒險家們很想在曠野裡試試他們的身手，當然這就需要相應的裝備來做保障。$B$B如果你能幫我搞到足夠多的皮革製品的話，我也許會教你一些高級的製皮技術。','把1雙雕花皮甲手套、5雙雕花皮甲長靴和5件雕花皮甲披風交給達納蘇斯的洛瑟里亞斯。','','去找達納蘇斯的洛瑟里亞斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1858,'zhTW','破碎之手氏族','你得去想辦法把塔贊的背袋給弄開，這樣咱們才能把裡面的東西拿出來。這鎖的結構還真挺複雜的，所以你想要弄開它的話就只能靠鑰匙了。$B$B如果你沒有在塔贊的屍體上找到鑰匙，那他就一定把鑰匙放到某個安全的地方去了……啊，對了!他有一個助手叫加摩爾，是個徹頭徹尾的大酒鬼，你八成能在酒館裡找到這傢伙。我建議你「安靜地」把鑰匙從他手裡搞來。','偷來塔贊的鑰匙，用它打開他的背袋，然後將裡面的物品交給奧格瑪暗影裂口的瑟祖克。','','去找奧格瑪的瑟祖克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1963,'zhTW','破碎之手氏族','大酋長行事的方法實在是有些太謹慎了。他總是很小心地不讓部落顯得過於鋒芒畢露。一旦我們足夠強大了，我們的力量將能征服一切。部落必須重現往日的榮耀和尊嚴，而現在看來能做到這一點的就只有我們破碎之手氏族了。$B$B我們必須在暗中積蓄力量，再突然向敵人發起致命的打擊，神不知鬼不覺地將敵人除掉。如果你想加入我們，就必須先為我完成一個任務，以此來證明你自己的價值。$B$B有個名叫塔贊的食人妖在棘齒城附近和海賊們做交易，而他那裡有我感興趣的消息。殺了他，把他的背袋拿來給我。','殺死塔贊，把他的背袋帶給奧格瑪暗影裂口的瑟祖克。','','去找奧格瑪的瑟祖克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1998,'zhTW','芬維克·薩托斯','瓦里瑪薩斯大人剛剛給我下達了一道命令，要求我派人去把一個對被遺忘者構成巨大威脅的傢伙立刻剷除掉。他的名字是芬維克·薩托斯，瓦里瑪薩斯大人認為他是一群在銀松森林中肆虐的不死生物的領袖。$B$B一接到這個任務，我馬上就想到了你， $N 。我堅信，以你的能力一定可以將這個任務輕鬆完成。$B$B我們派遣到銀松森林的亡靈哨兵們傳回的最新報告中指出，薩托斯就躲藏在洛丹米爾湖岸邊的一處廢棄碼頭上。','殺掉芬維克·薩托斯，把他的頭顱交給幽暗城盜賊區的米奈特·卡加德。','','去提瑞斯法林地找幽暗城的米奈特·卡加德。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1999,'zhTW','交易工具','安伯米爾的祈倫托巫師那裡保存著大量關於達拉然現狀的檔案，這些情報是我們從一個囚犯的口中拷問出來的。瓦里瑪薩斯大人已經下令，要求我們必須把這些檔案弄到手。$B$B於是這個任務就落到了你的肩上， $N 。你需要一些裝備，更重要的是得學會開鎖的技術。去跟我們的工具商艾斯特蕾·根德瑞談談，在你出發前向她要一套開鎖工具吧。','找到達拉然形勢報告，把它交給幽暗城盜賊區的米奈特·卡加德。','','去提瑞斯法林地找幽暗城的米奈特·卡加德。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2038 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2038,'zhTW','賓格斯的補給品','好像在洛克湖墜機還不夠倒楣似的，湖心小島上的穴居怪還襲擊了我，搶走了我的工具和氣壓爆裂物。沒有旋翼機沒有爆裂物，我什麼都做不了!$B$B去幫我找回工具和氣壓爆裂物， $N 。為了諾姆瑞根!','找回賓格斯的裝備:','','去洛克莫丹找洛克湖的賓格斯·雷管。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2040,'zhTW','地底突襲','諾姆瑞根已經被那群卑鄙懦弱的穴居怪們完全佔據了!情況很緊急，或許你能幫上我們的忙， $N 。$B$B在死亡礦坑深處有一台功能強大的哥布林伐木機，找到這台伐木機並帶回它的能源供應機件。有了這台伐木機的能源供應機件，我們就能給高速鑽孔挖掘機供應足夠的能量，用它來鑽透這裡與諾姆瑞根之間的岩石。鑽開一條路，給他們來一次地精式的突襲!','從死亡礦坑中帶回小型高能發動機，將其帶給暴風城矮人區中的沉默的舒尼。','','去暴風城的矮人區找沉默的舒尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2078,'zhTW','基爾卡克的報復','旱鴨子，你得幫忙找到我的大副。$B$B帶上這把鑰匙，把它插入我的大副身上的鑰匙孔裡，然後把他給我帶回來。$B$B那些魚人們馬上就要吃不了兜著走了，因為我的大副就要回來啦!','找到基爾卡克的大副─機械打手4100型，把他帶到基爾卡克那裡。','','去黑海岸找薄霧海的基爾卡克·旋杆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2098,'zhTW','基爾卡克的鑰匙復原','想要當一個出色的海賊可不簡單呀，你這個旱鴨子是不會理解的。我們的生活並不僅僅只是掠奪和痛飲!唉，我的船在海岸附近被那些可惡的魚龍給弄沉了。$B$B我希望我的大副能夠重新回來工作!$B$B當我被沖到海岸的時候，大副的鑰匙在岩石上折斷了，接著又被黑海岸那一帶的怪物給偷走了，我只記得隱約看見一些狂暴暗礁蟹、兇猛的森林陸行鳥和幾個魚人正在搜尋船的殘骸...','找到基爾卡可鑰匙的3段碎片，把它們交給基爾卡克‧旋杆。','','去黑海岸找薄霧海的基爾卡克·旋杆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2118,'zhTW','瘟疫蔓延','一種疾病正在黑海岸蔓延，它能夠控制一切與它接觸的靈魂和肉體。$B$B這種瘟疫對薊熊的影響最大，使得這種曾經高貴的動物現在幾乎變成了毀滅和殺戮的機器─它們變得狂暴，完全失去了理智。我有一種方法應該可以治療這種病。$B$B把這個陷阱放到森林的空地上。任何狂暴薊熊經過時，都會在短時間內變得馴服。一旦薊熊安靜下來了，就上前安撫它，減輕它的痛苦(使用/soothe命令)，然後它就會跟你走。把它帶到這裡來， $N 。','你帶回染病的薊熊了嗎，小心慢慢?','','去黑海岸找奧伯丁的薩納瑞恩·綠樹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2138,'zhTW','清除疫疾','正如我所擔心的，這種療法沒有得到效果。$B$B對我來說，任何野生動物的死都是一件令我難過的事情，但是我們必須殺掉這些感染了瘟疫的狂暴薊熊。$B$B $N ，回到森林裡去，殺掉20隻狂暴薊熊。這雖然無法驅散瘟疫，但可以在短期內降低狂暴薊熊對這片森林和森林裡的居民們帶來的破壞。','到森林裡去殺掉20隻狂暴薊熊。','','去黑海岸找奧伯丁的薩納瑞恩·綠樹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2139,'zhTW','薩納瑞恩的希望',' $N ，我們用慘痛的代價換取了黑海岸和奧伯丁的平安。$B$B你殺了很多早已病入膏肓的動物，減輕了森林的痛苦，也解脫了這些動物的靈魂。儘管這種狀況只能持續一小會兒，但是奧伯丁的人民感謝你。$B$B我要交給你最後一項任務，請注意，這將是又一次的殺戮任務。我希望這是最後一次讓你去做這樣的事情， $N 。$B$B有一隻雌薊熊住在東北方的一個靠近巴莎蘭的洞穴裡，殺了她。','找到雌薊熊，然後殺掉它。','','去黑海岸找奧伯丁的薩納瑞恩·綠樹。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2178,'zhTW','燉陸行鳥','你聞到撲鼻的香氣了嗎?那可是用我的秘方精心烹製的、新鮮出爐的陸行鳥燉肉，口感超絕，美味無比!$B$B你對我的食譜很感興趣吧?$B$B在我告訴你食譜之前，你得證明你能對付那些動物。$B$B我可並不是要求你簡單地跑出去馴服一隻陸行鳥，然後騎回來見我。你得去捕殺一些陸行鳥，把它們那些多汁的肉脯帶回來給我。只有這樣我才會把陸行鳥燉肉的秘方教給你。','給急彎河的奧蘭達利亞‧夜歌帶回5塊陸行鳥肉。','','去黑海岸找奧伯丁的奧蘭達利亞·夜歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2242,'zhTW','命運的召喚','我們相信有一個薩特可以幫助我們搞清泰達希爾的森林中究竟發生了什麼。但不幸的是，他可不會老老實實地跟我們合作。$B$B他的藏身之處就在神諭林地週邊的一棵樹上，但是與他接觸的人─無論是使用武力還是試圖交涉─都被他殺死了。也許只有偷偷摸摸地行動才是唯一可行的方案， $N 。$B$B去看看塞希爾的包裹裡有些什麼，然後回來向我報告。','找到遠古的塞希爾，帶回任何你可能發現的線索。','','去達納蘇斯找貿易區的塞尤娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2282,'zhTW','奧瑟爾伐木場','多年以來，我們都在這裡對 $C 進行訓練!畢竟不是每一個 $C 都能像老盧修斯那樣機靈和優雅的。$B$B沿著這條路向前走，一直到奧瑟爾伐木場去。我在那裡放了一隻裝著重要物品的箱子。去把箱子裡的東西給我拿來，我就給你頒發偷竊技能認證書!','打開盧修斯的帶鎖箱，拿到偷竊技能證明物，然後把它歸還給湖畔鎮的盧修斯。','','去赤脊山找湖畔鎮的盧修斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2358,'zhTW','奈茲拉之角','很多年之前，奈茲拉之角被從拉文霍德的領地上偷走了。經過漫長的跋涉和搜尋，我終於得知它一直以來都在那些野獸的手中。$B$B幹掉你見到的所有黑石獸人，直到你奪回奈茲拉之角為止，拿到它之後就回來找我。$B$B請為我找回奈茲拉之角吧，你的名字將永遠被拉文霍德家族銘記， $N 。','將奈茲拉之角交給湖畔鎮的阿蘭提爾。','','去赤脊山找湖畔鎮的混亂之手阿蘭提爾','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2359,'zhTW','克拉文之塔','我為如何進入這座塔的問題頭痛好久了， $N 。最近從暮色森林來了一船貨物，同時還來了不少守衛。$B$B他們是誰?我也有著和你一樣的疑問。我所知道的是─他們不是人類。$B$B不管怎麼樣，這批貨物中有一隻特殊的箱子─我想這就是那些亡靈在守護的東西。帶著狼牙棒的那個傢伙手裡有那座塔的鑰匙。$B$B拿到鑰匙，進入塔里，看看箱子中到底有什麼，然後去向馬迪亞斯報告。','偷取迪菲亞塔樓鑰匙，進入迪菲亞塔樓，看看暮色森林的箱子裡到底有什麼東西，然後向暴風城的馬迪亞斯·肖爾彙報。','','去暴風城找軍情七處的馬迪亞斯·肖爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2381,'zhTW','搶劫海盜','我並不是要嚇唬你， $N ，但是前五個派去偷南海寶藏的小偷都是被別人一塊塊運回來的……$B$B沿著這裡南邊的海岸走，你會找到海浪剃刀號，那是南海海賊的船。貨艙中的東西就是你的目標─南海寶藏。在船艙的二層是海賊的聚集處，那裡也是他們訓練 $C 的地方。$B$B設法登上那條船，然後把南海寶藏給我偷到手。你可以在那群海賊紮堆的地方試試自己的身手，但是你要非常小心，否則你就會成為第六個!','把南海寶藏帶回給棘齒城的卑鄙的維尼克斯。不要忘了從維尼克斯的機械設備中拿取一份大餅乾和盜賊工具，你的任務需要使用這兩件東西。','','去貧瘠之地的棘齒城找卑鄙的維尼克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2438,'zhTW','翡翠攝夢符','班奈希爾獸穴的德魯伊守護者蓋洛拉斯‧塔文斯倫曾經給了我一個翡翠攝夢符。這種強大的護符可以吸取翡翠夢境的能量，給拿著它的人帶來好運。$B$B不過，我把它放在星風村的衣櫃裡了，沒辦法把它取回來...星風村原本是個寧靜的小村子，但現在那裡受到了熊怪的侵襲。$B$B你能不能幫我拿回攝夢符， $C ?','取得翡翠攝夢符。','','去泰達希爾找多蘭納爾的塔隆凱·捷根。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2459,'zhTW','『食夢者』菲羅斯塔','翡翠...不見了!我的攝夢符被毀了!$B$B星風村北部有一群瘤背秘法師。我接到報告說他們的領袖『食夢者』菲羅斯塔的脖子上戴著一條在夜間會發出綠光的項鍊。我覺得就是他偷走了我的翡翠...他絕不會想到那顆翡翠對他毫無用處。$B$B去找到丟失的寶石， $N 。另外，你在那兒活動的時候，別忘了順便清除一些墮落的瘤背秘法師。','殺掉7個瘤背秘法師，並找到遺失的珠寶。','','去泰達希爾找奧拉密斯湖的塔隆凱·捷根。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2499,'zhTW','奧肯斯古爾','我搞明白了!我不得不衝來這裡找你!其實答案很簡單...腐化是經由樹精傳染的，但源頭卻只有一個。$B$B奧肯斯古爾已經被一顆我所見過的最大的腫瘤毒害了...那個腫瘤簡直可以稱之為龐然大物。$B$B奧肯斯古爾過去住在我湖泊附近的一個洞穴裡，但後來跑到了東北方的一個隱蔽處。 $N ，殺掉奧肯斯古爾，拿到它身上的腫瘤，讓這個墮落之源永遠從我的家園消失。','從奧肯斯古爾那裡取得巨大的瘤。','','去找泰達希爾的德納蘭。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2500,'zhTW','荒蕪之地的試劑',' $C ，我需要你的幫助。我是個小有名氣的鍊金師，我需要你去荒蕪之地幫我找一些原材料。$B$B我需要這些東西補充我的庫存:五個禿鷲的胃囊、十顆峭壁山狗的牙齒和五塊岩石元素裂片。當然你可以從這些動物身上拿到這些東西，不過如果你不擅長打仗的話，可以找些擅長的朋友。$B$B找到這些東西給我，作為交換你可以得到一些錢幣。$B$B好吧，你覺得怎麼樣?','從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。','','去洛克莫丹找灰爪山的加克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2518,'zhTW','月神的淚水','薩絲拉女士曾經受到月神的寵愛，這只優雅而純潔的蜘蛛在月光下的迷霧中編織著銀線，用以收集銀色的露水，並將這種有強大治療功效的露水存放在附近的神殿裡。$B$B不過最近薩絲拉突然變得瘋狂起來，她的後代也受到了威脅。$B$B找到薩絲拉， $N ，結束她的痛苦。她住在這裡東北邊的河流附近。取得她的銀色絲囊，然後帶回來交給我。','取得薩絲拉的銀色絲囊。','','去達納蘇斯找神殿花園的女祭司艾茉拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2520,'zhTW','薩絲拉的祭品','現在你必須完成交給你的任務。拿上銀色絲囊，然後將它作為薩絲拉的祭品獻給伊露恩，讓這只蜘蛛得以安息。$B$B找到大殿中央的噴泉，在那兒放下祭品。神聖的泉水可以淨化並清洗讓薩絲拉發瘋的墮落力量。$B$B完成任務之後再回來見我。','女祭司艾茉拉讓你將薩絲拉女士的銀色絲囊放在大殿的噴泉處，然後回去見她。','在噴泉處奉上祭品','去找達納蘇斯的女祭司艾茉拉。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2541,'zhTW','沉睡的德魯伊','這裡的瘤背薩滿找到了一種可以在德魯伊休眠時將他的靈魂和肉體分離的方法。熊怪就這樣驅使著我的肉身，利用我去襲擊那些對班奈希爾獸穴進行偵察的人。現在我沉睡在翡翠夢境裡，無法阻止他們。$B$B你一定要幫幫我。瘤背薩滿用一種特殊的符咒來完成這種儀式，我希望能研究一下這種符咒。 $N ，全靠你了。','將一個薩滿巫毒符咒交給班奈希爾獸穴的奧本·怒爪。','','去找泰達希爾的奧本·怒爪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2561,'zhTW','利爪德魯伊','在研究過這個符咒之後， $N ，我知道該做什麼了。請拿著它，然後照我說的去做。$B$B你必須接近附近房室的門。在門裡，你會發現我那失去靈魂的軀體...雖然我對接下來要說的話感到很遺憾，但是除此之外我找不到其他可以讓我擺脫瘤背熊怪控制的辦法了。$B$B你必須殺了我的肉身，然後對我的屍體使用巫毒符咒。完成這個任務之後就請回到我這裡來。','奧本·怒爪要求你去殺掉他那失去靈魂的身體，然後對其屍體使用巫毒符咒。','釋放奧本·怒爪的靈魂','去找班薩羅獸穴的奧本·怒爪。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2608,'zhTW','贊吉爾之觸','哦，天哪，你看起來就像死人一樣。糾正一下─我見過死人，你看起來比死人還要糟，簡直像是死了又死!$B$B哈哈!諾拉姆，你聽見了吧?把它記下來!$B$B*咳嗽*嗯，好吧。為了幫助你，我得先給你抽點血。別擔心，只有前幾次抽血會有點疼……大概前五十次吧……準備好了之後就躺下(使用/lay指令)， $N 。','用/lay指令躺下，接受道克·米希匹克斯的治療。如果他找不到病因，就找不到治療的方法。','診斷完成','去找暴風城的道克·米希匹克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2609,'zhTW','贊吉爾之觸','我們達成了共識， $N ，你得的是「伊提斯綜合症」。$B$B幸運的是，我這裡有醫治伊提斯綜合症的藥方。$B$B我需要些東西:一束普通野花、一隻鉛瓶，一根青銅管，最後還要一卷淡綠色絲線。奧·艾瑪在「最好的線團」那家店裡給我留了一卷這樣的線，就在運河區沿岸。$B$B趕緊出發吧， $N ，記住在你的病痊癒之前不要接觸任何人。哦，還有，蒙特高莫醫生說你該洗個澡了─他說的，不是我說的。','給道克·米希匹克斯帶去一束普通野花、一隻鉛瓶，一根青銅管，最後還要一卷淡綠色絲線。伊提斯綜合症可不會不治而愈，年輕的小姐。','','去暴風城找英雄谷的道克·米希匹克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2770,'zhTW','加茲瑞拉','在塔納利斯沙漠的食人妖古城祖爾法拉克深處，有一個神聖的池塘。食人妖可以從那個池塘裡召喚一頭巨大的野獸─加茲瑞拉!它兇猛異常，甚至連它的鱗片都會因為巨大的能量而發出聲響。我要用它的能量來給我的賽車增加動力!$B$B把加茲瑞拉的鱗片給我弄來!$B$B不過，召喚加茲瑞拉的方法是食人妖的秘密。如果你想要面對加茲瑞拉的話，首先就要從食人妖那裡弄到召喚它的方法。','把加茲瑞拉的鱗片交給閃光平原的維茲爾·銅栓。','','去千針石林找沙漠賽道的維茲爾·銅栓。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2904,'zhTW','一團混亂','<克努比呻吟著。>發……發生什麼事了?$B$B我只記得自己被一隊黑鐵矮人抓住了，他們揍了我一頓，把我跟這些醜陋的穴居怪扔在一塊兒。$B$B快救我出去， $N !$B$B我有個計畫:把我帶到出口，如果我們能活著走出去的話，你就到藏寶海灣去，告訴斯庫提我去了棘齒城，然後警告廷克維斯，黑鐵矮人準備製造超強的鑽探設備。$B$B讓我們開始吧!','將克努比護送到發條小徑的出口，然後向藏寶海灣的斯庫提彙報。','營救克努比','去荊棘谷找藏寶海灣的斯庫提。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2922,'zhTW','拯救尖端機器人!','當我們摯愛的諾姆瑞根城淪陷時，我可憐的發明─尖端機器人─受到了某種致命的打擊。它原本包含了很多精巧的設計，並且儲存了大量的資訊，憑藉這些，它無數次地幫助了我和我的同事，但現在它的正電子腦被極化，變成了負電子腦……尖端機器人的行為已經變得完全異常了。它像個瘋子似的在諾姆瑞根裡咆哮!$B$B也許我們仍然可以挽救它，如果你能找回尖端機器人的記憶體核心並把它交給我，那麼我就能找到故障的原因，然後把我可憐的尖端機器人修好。$B$B','將尖端機器人的記憶體核心交給鐵爐堡的技工大師歐沃斯巴克。','','去鐵爐堡找侏儒區的工匠大師歐沃斯巴克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2924,'zhTW','基礎模組','有一種通用型的機械部件─基礎模組─對於諾姆瑞根的技工和鐵匠來說都非常重要，不過在我們大舉逃出諾姆瑞根的時候，誰也沒想起要把這些東西帶上!我手頭上的工作需要大量這種部件。$B$B請去諾姆瑞根給我拿一些基礎模組回來，它們就裝在城市深處的機械儲存櫃裡。$B$B謝謝你， $N ，請儘快出發吧!','收集12個基礎模組，把它們交給鐵爐堡的科勞莫特·鋼尺。','','去鐵爐堡找侏儒區的科羅莫特·鋼尺。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2926,'zhTW','諾恩','事故後，諾恩想的說的都離不開兩個主題:如何將穴居怪趕出諾姆瑞根，以及如何為席捲諾姆瑞根的瘟疫找到治療的方法。$B$B幸運的是，拉茲和我已經快要研究出一種治療方法了─要不然就是一種很強勁的朗姆酒的配方。我們要試過才知道!當然，為了檢驗我們的理論是否成立，我們需要一些東西，準確地說，是諾姆瑞根城裡那些穴居怪身上的輻射塵。用這個小瓶子裝一些泛著綠光的輻射塵，然後把它帶回來!','用空著的鉛之瓶對著輻射入侵者或者輻射掠取者，從它們身上收集放射塵。瓶子裝滿之後，把它交給卡拉諾斯的奧齊·電環。','','去丹
莫羅找卡拉諾斯的奧齊·電環。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2928,'zhTW','陀螺式挖掘機','太糟糕了， $N 。我們沒有足夠的零件讓我們的陀螺式挖掘機部隊進入丹莫洛。$B$B我們需要的是零件， $N ，更多的零件。說到尋找零件，難道還有比諾姆瑞根更好的地方嗎?我聽說那裡的機器人像牧區的牛似的到處遊蕩。$B$B我要你做的就是到諾姆瑞根去，把這些機器人拆開，拿出它們的內部裝置。給我弄兩打來就夠了。','收集24副機械內膽，把它們交給暴風城的舒尼。','','去暴風城的矮人區找沉默的舒尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2929,'zhTW','大叛徒','我以前曾經非常信任瑟瑪普拉格，我從未想過他會背叛我和所有地精同胞。他為什麼要背叛我們?為了權力?為了金錢?這些東西只要假以時日他都可以擁有。現在我們背井離鄉，那個瘋子掌握了政權，成了個什麼都沒有的國王……$B$B我們要奪回諾姆瑞根， $N 。在奪回自己的城市之前，我們絕不停止努力。如果你想加入我們，就先去完成一個簡單的任務:殺了那個叛徒，機電師瑟瑪普拉格。','到諾姆瑞根去殺掉機電師瑟瑪普拉格。完成任務之後向大工匠梅卡托克報告。','','去鐵爐堡找侏儒區的大工匠梅卡托克。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2930,'zhTW','搶救資料','在逃離諾姆瑞根的時候，我們留下了太多的資料!非常重要的資料!$B$B我需要一張稜彩穿孔卡片，你可以從諾姆瑞根城裡的矩陣式打孔電腦3005-D型裡找到這種卡片。不過糟糕的是，要得到它的話，你就必須先接近低級安全終端，也就是A型，B型和C型電腦，然後用不同的穿孔卡片開啟它們，從白色的卡片開始……而且我們把所有的穿孔卡片都留在城裡了。$B$B這真是一場災難!你能幫忙嗎?','將稜彩穿孔卡片交給鐵爐堡的大技師卡斯派普。','','去鐵爐堡找侏儒區的大機械師卡斯派普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2951,'zhTW','超級清潔器5200型!','這個裝置屹立於那些竭力保護房間的地精中，裝置上有一塊小金屬牌，上面寫著「超級清潔器5200型」，還有一段文字:$B$B:「污垢和殘渣讓你的東西看起來污穢不堪?超級清潔器5200型會使它重現光芒!將你想要清理的物品放入清潔器中，然後向槽裡投入三枚銀幣。稍候片刻，你的珍寶就會重新變得潔淨而耀眼!」','將髒兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。','','去找銀松森林的超級清潔器5200型。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2962,'zhTW','更多的輻射塵!','你的樣本不僅數量不夠，而且純度也不夠。$B$B我們需要更多的輻射塵。很顯然，穴居怪身上的輻射劑量根本無法滿足我們的需要。你必須重返諾姆瑞根，直接從輻射源頭取回一些輻射塵。我指的是那些受到輻射的泥漿怪、潛伏者和水元素。小心一點，收集這種輻射塵並不容易。也許你得試好幾次才能找到一個合適的樣本。','到諾姆瑞根去收集高強度輻射塵。要多加小心，這種輻射塵非常不穩定，很快就會分解。','','去丹莫洛找卡拉諾斯的奧齊·電環。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3361,'zhTW','逃難者的困境','我本來正在前往諾姆瑞根的途中，打算和我的地精同胞會合，結果一切錯得一塌糊塗!$B$B我離開安威瑪，包包裝好，跋涉過及腰的雪。然後我們遇上這場莫名其妙的地震，把我震得暈頭轉向。結果我跑到了這裡，更糟的是，食人妖偷光了我的東西!$B$B $N ，過去那一天半顯然證明了我能力不足。你介意幫個忙，進入西南方的食人妖營地，把我的東西帶回來給我嗎?','把菲利克斯的盒子、菲利克斯的箱子和菲利克斯的螺釘桶。','','去丹莫洛找寒脊山小徑的菲利克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3376,'zhTW','打斷尖牙!',' $N ，我聽說過你的名字，新來的。或許你可以幫我們一個其他人都做不到的忙。$B$B我們 $R 在這塊土地上建立了自己的家園，但是我們也付出了代價。刺刃峽谷中有一座刺背野豬人的村莊，在他們的首領─尖牙刺鬃酋長的帶領下，一直在與我們交戰，這讓我們的生活變得非常艱難。我要你去取回尖牙刺鬃酋長的首級!$B$B你可以在東邊的峽谷中找到他們那簡陋的村莊，刺鬃酋長就在村子裡面。','把尖牙刺鬃酋長的頭顱交給紅雲台地的勇者風羽。','','去莫高雷找納拉其營地的衛兵維薩羅·風羽。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3521,'zhTW','埃沃隆的解藥','我真的很擔心我的朋友埃沃隆。他失蹤將近一天，我害怕他可能中毒了...或者更糟。$B$B我希望你幫忙收集製造解毒劑的材料以防萬一。從附近樹木的底部收集紫藍色蘑菇，在水池周圍收集月牙百合花，還有北邊某隻蜘蛛身上的樹林蜘蛛的膿液。$B$B就算他中毒了，混合這些材料仍相當簡單。他前往北邊的影絲洞了，幸運的話你會在那附近找到他。','收集7朵紫藍色蘑菇、4朵月牙百合花和1份樹林蜘蛛的膿液。','','去泰達希爾找幽影谷的迪蘭妮亞·月光。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 3524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3524,'zhTW','擱淺的巨獸','眾所周知，巨大的海洋生物會在黑海岸的岸邊上岸，待在那裡直到死亡。近來，這些巨獸擱淺的數量不斷增加。月神殿派我到這裡來調查，但是海邊的魚人使調查變得非常困難。$B$B被邪惡的灰霧魚人所掌控的奧伯丁南部海岸上躺著一頭擱淺的巨型生物，你能幫忙去從這頭巨獸身上弄點骨頭回來供我研究嗎?','在奧伯丁南邊的海岸上尋找擱淺生物的駭骨，然後帶著骨頭回來找奧伯丁的溫尼斯‧布萊葛。','','去黑海岸找奧伯丁的溫尼斯·布萊葛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3636,'zhTW','與聖光同在','天譴軍團對聯盟是一個長期的威脅，我想你應該明白這一點。最近，我們偶然發現了一些罕見的東西， $N 。$B$B在貧瘠之地有一片令人恐怖的灌木林稱作剃刀高地。雖然那兒曾經是野豬人的家，但是很明顯，它已經變成天譴軍團的地盤，並衍生出了更加可怕的生物……這些生物都被巫妖『寒冰使者』亞門納爾統治著。$B$B願聖光與你同在， $N ;終結那裡的邪惡吧。','大主教本尼迪塔斯要你去殺死剃刀高地的『寒冰使者』亞門納爾。','','轉至暴風城，去找教堂廣場的大主教本尼迪塔斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 3661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3661,'zhTW','月神之獸?','梟獸是難以預測的生物， $N 。它們有著極端溫順的一面，如果它們重視的東西受到威脅，這些生物就會變得非常兇猛。$B$B傳說這些野獸是由伊露恩創造的，我對這種說法的真偽很感興趣。$B$B近來，我聽說辛特蘭的梟獸數量越來越多─這些兇殘、原始、野蠻的傢伙在辛特蘭的野外四處橫行。你能幫我收集一些梟獸的羽毛嗎?','為魯瑟蘭村的艾瑞拉斯·琥珀收集15支梟獸羽毛。','','去泰達希爾找魯瑟蘭村的艾瑞拉斯·琥珀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3901,'zhTW','斷骨骷髏','你向被遺忘者展示了你在正常情況下的潛力， $N 。現在讓我們看看你在壓力下的表現吧。$B$B與你先前幹掉的殭屍相比，斷骨骷髏更為強韌也更為兇殘。殺掉它們，再次向被遺忘者證明你的能力吧。別耽擱時間，完成任務後立刻來找我交談。','殺死8個斷骨骷髏。','','去提瑞斯法林地找喪鐘鎮的暗影牧師薩維斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3902,'zhTW','撿破爛','嘿，說你呢!要是你想實現自己的價值，那就聽好了!$B$B我們要求那些剛剛爬出墳墓的新兵前往喪鐘鎮，搜尋任何可以為我們所用的裝備，這些裝備極有可能裝在成堆的箱子裡。我們希望能立即招募到更多的新兵，因此，除非我們想讓他們赤手空拳地上陣，否則我們就得搜尋一切可用之物!$B$B開始工作吧，你這堆可悲的骨頭!對那些不努力工作的傢伙，我可是不會給予回報的。','在喪鐘鎮及臨近地區搜尋6件破爛裝備，把它們交給亡靈衛兵薩爾坦。','','去提瑞斯法林地找喪鐘鎮的亡靈衛兵薩爾坦。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4161,'zhTW','卡多雷的食譜','很久以前， $R 被稱作卡多雷，卡多雷的意思是「眾星之子」。瞭解這些歷史對幫助你成為一名真正的 $C 非常重要， $N ，所以好好聆聽我告訴你的故事吧。$B$B卡多雷總是以自己和環境之間的和諧關係而感到自豪，這意味著我只向自然索取生活必需的東西，並且要給自然以友善的回報。這種平衡使我們受益良多， $N 。$B$B去幫我收集7條小蜘蛛腿 -- 不要多，然後回來找我。','收集7條小蜘蛛腿。','','去泰達希爾找多蘭納爾的扎瑞恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4402,'zhTW','戈加爾的清涼果','試煉谷這裡真是熱得要死。$B$B<戈加爾擦了擦他的額頭。>$B$B如果我有仙人掌果的話，就可以做點清涼果來吃了!沒什麼能比清涼果更甘甜消暑的。$B$B我跟你說啊， $N ，只要你給我弄6個仙人掌果來，我就幫你做一些清涼果。如果你感興趣的話，就到這附近去找找仙人掌，採集它們的果子。','收集6個仙人掌果。你記得他說過，附近的仙人掌上可以找到這種果子。','','去杜洛塔找試煉谷的戈加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4601,'zhTW','超級清潔器5200型!','這個裝置屹立於那些竭力保護房間的地精中，裝置上有一塊小金屬牌，上面寫著「超級清潔器5200型」，還有一段文字:$B$B:「污垢和殘渣讓你的東西看起來污穢不堪?超級清潔器5200型會使它重現光芒!將你想要清理的物品放入清潔器中，然後向槽裡投入三枚銀幣。稍候片刻，你的珍寶就會重新變得潔淨而耀眼!」','將髒兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。','','去找希爾斯布萊德丘陵的超級清潔器5200型。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4602,'zhTW','超級清潔器5200型!','這個裝置屹立於那些竭力保護房間的地精中，裝置上有一塊小金屬牌，上面寫著「超級清潔器5200型」，還有一段文字:$B$B:「污垢和殘渣讓你的東西看起來污穢不堪?超級清潔器5200型會使它重現光芒!將你想要清理的物品放入清潔器中，然後向槽裡投入三枚銀幣。稍候片刻，你的珍寶就會重新變得潔淨而耀眼!」','將髒兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。','','去找銀松森林的超級清潔器5200型。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4681,'zhTW','擱淺的巨獸','黑海岸地區到處都是這種擱淺在海灘上的生物。它們大多出現在海岸線上，有一些甚至出現在海水中。我想讓你調查另一隻最近被發現的生物，據說它的屍體躺在奧伯丁西邊的海水中，在一艘沉船附近。把你發現的任何有助於研究的資訊都回饋給我。$B$B此外，在旅途中，你可能會發現其他擱淺的生物，你一定要把這些新發現也告訴我們!','在奧伯丁西面海水中的海龜骨骸那裡取回海龜的殘骸，然後與奧伯丁的溫尼斯‧布萊葛談話。','','去黑海岸找奧伯丁的溫尼斯·布萊葛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4740,'zhTW','懸賞:莫克迪普!','注意!$B$B殺死名為「莫克迪普」的魚人就可獲得一筆賞金。這只邪惡的野獸至少殺死了一名哨兵，還涉嫌使至少兩條貨船在黑海岸沉沒!$B$B莫克迪普最後一次出現是在是奧伯丁以南的一個有草棚的魚人營地中，據信它保護著那裡的草棚。殺死該魚人後請到奧伯丁的哨兵戈琳達‧納希恩處領取賞金。$B$B奧伯丁鄉村委員會','找到並殺死名為莫克迪普的魚人。它守護著位於奧伯丁南部海岸的魚人營地。','','去黑海岸找奧伯丁的哨兵戈琳達·納希恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4762,'zhTW','壁泉河','壁泉河的河水正在逐漸變得污濁，這污濁的河水流入薄霧海，我擔心奧伯丁也會很快受到影響。我懷疑居住在上游區域的黑木熊怪是造成污染的原因，但是我覺得它們並不是一切問題的真正源頭。$B$B帶上這支試管，到北面的河口去，在第一個內陸瀑布的水潭中取出一份河水的樣本來─在你抬頭就可以看到一座橋的那個地方取水就可以了。拿到樣本後就回奧伯丁來找我。','到奧伯丁的北面去，沿著壁泉河到達第一個瀑布處，從瀑布下的水潭中取出一份水樣。','','去黑海岸找奧伯丁的桑迪斯·織風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4763,'zhTW','黑木熊怪的墮落','我們已經知道熊怪的墮落與薩特有很大的關係，他們使用魔法護符控制熊怪。如果我們要嘗試拯救熊怪的話，就必須擊敗引誘熊怪的薩特，取回他的護符!$B$B到我們的月井裡去，在碗裡盛滿水，然後從北面的熊怪營帳中取回一些食物。把水和食物混合並放在河水邊的營火旁，只要熊怪吃下食物，它就會得到淨化，稍等片刻，那個引誘熊怪的薩特就會出現...這時你就要出手殺掉它!','在空的淨化碗裡盛滿奧伯丁月井的井水。','','去黑海岸找奧伯丁的桑迪斯·織風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4811,'zhTW','紅色水晶','我們東邊的區域出現了越來越多的有攻擊性的梟獸。過去它們都是很溫和的─甚至可以說是神秘的動物。儘管仍然有人對它們非常尊敬，但出於對奧伯丁安全的考慮，我不得不保持更現實一些的觀點。$B$B據說這段時間以來，月光梟獸被黑海岸東部山脈上的一塊巨大的紅色水晶吸引，聚集在它的周圍。沒有人知道那塊水晶是什麼，也沒有人知道它是否真的存在。我想讓你去找到它的位置，並把你所發現的任何東西都報告給我。','到奧伯丁的東邊去，沿著黑海岸東部邊界的山脈尋找一顆巨大的紅色水晶，然後向奧伯丁的哨兵戈琳達‧納希恩彙報你的發現。','在黑海岸東部邊界的山上找到巨大的紅色水晶','去黑海岸找奧伯丁的哨兵戈琳達·納希恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4812,'zhTW','清洗水晶','用這支小瓶裝一些奧伯丁月井的水。它潛在的魔法能量可以幫我們弄清這塊水晶的成分，你必須把水倒在那塊水晶上，剩下的就不用你操心了。$B$B雖然我不覺得你會有什麼不測，但我仍然希望你多加小心。我們東邊就是費伍德森林，如果這塊水晶真的與那個地方有關聯，它就可能非常危險。','在奧伯丁月井中把空水瓶裝滿，然後調查黑海岸東部山脈的紅水晶。','','去找黑海岸的神秘的紅色水晶。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4921,'zhTW','在戰鬥中失蹤','我們在一個小小的 $R 營地裡作戰，然後就被沖散了─她獨自與三個刺背野豬人交戰。形勢越來越不妙，我引開了一些敵人，結果她又很快被新趕到的敵人包圍了。在狂怒之下，我衝向敵人，但是他們人多勢眾，很輕鬆地就把我打倒了。$B$B我醒來的時候，一位 $R 德魯伊正在照料我的傷口，他是在黃金之路上找到我的。$B$B $C ，請你幫我尋找我妻子的音訊。','找到曼寇里克的妻子，然後回到十字路口找他。','','去找貧瘠之地的曼科裡克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5233,'zhTW','目標:苦痛鬼屋','已經有兩口瘟疫之鍋被成功打開了，雖然並不確定你能否繼續前進，但我們仍然想要打開剩下的兩口瘟疫之鍋。這可以讓我們的解藥發揮更大的效果!$B$B這次你的目標是苦痛鬼屋的瘟疫之鍋。那個地方在安多哈爾正東邊，相對來說比較靠近被毀壞的城牆。和以前一樣，消滅那裡的護鍋領主，拿到它的鑰匙。用這只瓶子從鍋裡取得樣品。$B$B祝一切順利，$n!','到西瘟疫之地的苦痛鬼屋去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶苦痛鬼屋的空瓶來採集瘟疫之鍋中的毒藥樣本。','','去西瘟疫之地解鎖達隆米爾湖的天災之鍋。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5235,'zhTW','目標:蓋羅恩農場','最後的一口瘟疫之鍋在一個被稱作蓋羅恩農場的地方，由天譴軍團中較為強大的爪牙守衛著─那裡的鬼魂和怨靈尤其危險。你可不能掉以輕心，$n。$B$B蓋羅恩農場在這裡的東北方向，靠近東瘟疫之地的邊界。和以前一樣，消滅那裡的護鍋領主以獲取他的鑰匙。拿著這個空樣品瓶，把它裝滿給我拿回來。願聖光護佑你平安完成這次危險的任務，$c。','到西瘟疫之地的蓋羅恩農場去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶蓋羅恩農場的空瓶來採集瘟疫之鍋中的毒藥樣本。','','去西瘟疫之地的蓋羅恩農場解鎖天災之鍋。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5321,'zhTW','昏昏欲睡','我正要趕路去邁斯特拉崗哨見利拉迪斯‧月河，但是我決定在這裡停下打個盹...自從我被從翡翠夢境中喚醒之後，就總是那麼睏...$B$B<打哈欠>$B$B你願意給我帶路嗎?我知道邁斯特拉崗哨在這裡的南邊，就沿著梣谷的路走好了。路上可能會有危險，我希望你的朋友也能一起來幫助我。$B$B最後一點，也許我會在半路上睡著，你只要吹響我的號角就可以喚醒我了。號角就在這個箱子裡。','護送克羅尼亞‧恒影到梣谷邁斯特拉崗哨的利拉迪斯‧月河那裡去。','護送克羅尼亞·恆影到邁斯特拉崗哨去','去找梣谷的利拉迪斯·月河。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5441,'zhTW','懶惰的苦工','該死的苦工!我叫他們在山谷裡伐木，但他們總是見縫插針地打盹!我需要找個人幫我去叫醒他們。$B$B你看起來挺適合這差事的。給你，拿著這根棍子，看到偷懶睡覺的苦工就打醒他。只要狠狠地敲他們一下就能讓他們乖乖回去工作了!別忘了把棍子還給我。$B$B這些該死的懶漢……','在懶惰的苦工睡覺時，用工頭的木棒敲他們。敲醒5個苦工，然後把工頭的木棒還給試煉谷的工頭塔茲利爾。','','去找杜洛塔的工頭塔茲利爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5481,'zhTW','葛爾多的任務','主人需要草。我們的手太大，沒有辦法撿。你可以幫我們，我們不傷害你。我們需要陰暗草。這裡有許多這樣的草，路邊也有。$B$B拿到草之後，把它交給布瑞爾墓地的主人，霍蘭德。','收集3根陰暗草，把它們交給布瑞爾墓地的初級藥劑師霍蘭德。','','去找布瑞爾的初級藥劑師霍蘭德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5482,'zhTW','末日草','你看到我所處的困境了吧， $N ?那個蠢貨弄來的野草根本不是我要的!如果你能幫我弄到需要的東西，我會回報你的。幫我帶來足夠的末日草我就會給你適當的獎勵。$B$B據我所知，那些野草一般生長在大墓地附近的植物群裡，就在布瑞爾墓地北面。快去吧，小心那兒的豺狼人。','收集10株末日草，把它們交給初級藥劑師霍蘭德。','','去提瑞斯法林地找布瑞爾的初級藥劑師霍蘭德。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 5541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5541,'zhTW','海格納的彈藥','海格納·重槍在安威瑪出售槍支。步槍隊和迫擊砲小隊都會花大量的時間在他的店鋪裡挑挑揀揀，所以他總是需要充足的新貨物。$B$B但是……我送給他的最後一箱彈藥在半路上不見了。送貨的傢伙說他當時在灰色洞穴附近紮營，然後來了幾個雪怪把他給趕跑了……那個傻瓜就把海格納的彈藥留在那裡了!$B$B $N ，你能不能拿到那些彈藥然後送到海格納那裡去呢?我敢說他的庫存已經不多了。','把海格納的彈藥交給丹莫洛的海格納·重槍。','','Return to Hegnar Rumbleshot in Dun Morogh.','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5726,'zhTW','隱藏的敵人','如果說有什麼是我絕對不能容忍的，那就是我們當中的背叛者。但是我過早地插手這件事，真有些愚蠢─這不僅不能有效地清除那些墮落者，反而使得叛徒越來越多。$B$B但是，你，年輕的冒險者，你可以進入那些我的密探所不能到達的地方……你能發現真相……你能找出那些叛徒的幕後主使。$B$B如果你足夠勇敢的話，就去奧格瑪東邊的骷髏石，找到燃刃氏族軍官的徽記，然後回到我這兒來。','將軍官的徽記交給奧格瑪的索爾。','','去找奧格瑪的薩爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5727,'zhTW','隱藏的敵人','讓我們看看你找到的徽記是否有價值。$B$B城中有一個術士，他認為自己已經得到了我的信任，但是他並不知道我很瞭解他真正效忠的主人是誰。他實際上是燃刃氏族的領袖。先別急著跟他開戰，因為他還有用處，我們可以利用他來對付我們的敵人。$B$B去奧格瑪的暗影裂口找他，把這枚徽記交給他，跟他談談，看他是否相信你是他的同夥，然後回到我這兒來。','將軍官的徽記交給尼爾魯·燃刃並與他談話，看看他是否相信你是燃刃氏族中的一員，然後回到奧格瑪的索爾那裡。','看看尼爾魯·火刃是否相信你是火刃氏族的成員','去找奧格瑪的薩爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5728,'zhTW','隱藏的敵人','嗯，灼刃氏族的首領……這可是件至關重要的事。如果他們是尼爾魯的幹將，那他們就是我們的首要目標。這個薩特……巴札蘭，以及另一個尼爾魯提及的傢伙─他是幹什麼的來著，是個術士?─必須被除掉。$B$B回到怒焰裂谷去， $N 。找到灼刃氏族的兩名首領，殺死他們。但是別讓尼爾魯知道是你幹的。你必須繼續偽裝成他的忠實追隨者，不要暴露身份。','殺死巴札蘭和『塑能師』耶戈什，然後回到奧格瑪的索爾那裡。','','去找奧格瑪的薩爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5761,'zhTW','『飢餓者』塔拉加曼','我們偉大的大長交給我的首要任務就是搜尋那些利用惡魔的力量破壞城市的敵人。燃刃氏族是個威脅，但是這裡還存在著其他的威脅，比如在怒焰裂谷安家的灼刃氏族，他們暗地裡計畫著襲擊部落的無辜民眾。$B$B要想阻止他們，就必須殺死他們的領袖─那個被稱作『飢餓者』塔拉加曼的惡魔守衛。$B$B殺死他，索爾看到他的心臟之後一定會安心很多，這點我可以確信。','進入怒焰裂谷，殺死『飢餓者』塔拉加曼，然後把他的心臟交給奧格瑪的尼爾魯·火刃。','','去找奧格瑪的尼爾魯·火刃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6394,'zhTW','塔茲利爾的鎬',' $N ，你是個值得信賴的 $R 。我能把另一個任務也託付給你嗎?$B$B不久前，我在北邊的一個洞穴中挖掘礦石的時候不小心弄丟了我最喜歡的鎬。後來當我回去找它的時候，卻發現洞穴中住滿了邪惡的野獸!到那個被稱作燃刃集會所的洞穴中去幫我取回我的鎬，行嗎?$B$B我把它放在一個有瀑布的大廳裡了。我的鎬附有魔法，你在黑暗中也能看見它，所以你不必擔心找不到它……只要小心那些守護它的野獸就是了!','將塔茲利爾的鎬還給工頭塔茲利爾。','','去找杜洛塔的工頭塔茲利爾。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 6395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6395,'zhTW','瑪拉的遺願','瘟疫發生之前，我的朋友瑪拉·菲普斯和她的丈夫山繆生活在一起。但是瘟疫掃過這片土地之後，山繆加入了天譴軍團的隊伍。$B$B瑪拉逃過了瘟疫，卻慘死在她那愚蠢的丈夫手裡。唉，這個傻女人深愛著自己的丈夫，她的遺願竟然是同山繆葬在一起。$B$B山繆·菲普斯就住在喪鐘鎮東北邊，在路旁的一座廢棄的營帳裡。去打敗他，實現瑪拉的遺願─將他葬在瑪拉的墳墓裡，就在墓地的第一排。','將山繆·菲普斯的遺骸帶到瑪拉的墳墓去，然後回到新兵艾爾雷斯那裡。','','去提瑞斯法林地找喪鐘鎮的新兵艾爾雷斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 6548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6548,'zhTW','為我的村莊復仇','恐怖圖騰氏族劫掠了我的村莊，一個活口都沒留下。我奮力殺敵，但還是差一點就被殺掉了。$B$B $N ，現在我唯一的願望就是讓他們付出血的代價。你可以在這裡的西面找到他們。','殺掉8個恐怖圖騰惡徒和6個恐怖圖騰傭兵，然後向石爪山脈東南邊界處的瑪卡巴·扁蹄覆命。','','去石爪山脈和貧瘠之地的交界處找瑪卡巴·扁蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6624,'zhTW','救死扶傷','你好，醫生。我們將在今天下午對你的醫術進行檢驗。如果你通過了測試，那麼你將榮幸地成為聯盟外科醫療隊的一員。$B$B現在注意了!致命傷要優先處理，然後是重傷，傷勢一般的病患放在最後處理。你必須拯救至少15個病人才能通過這個測試。如果有6個病人在這個過程中死亡，那麼你就失敗了。$B$B我們會給你提供治療所需的繃帶。$B$B祝你好運，醫生。','使用急救繃帶來治療病人。你必須在6個病人死亡之前拯救15個病人。','拯救15個病人！','去塵泥沼澤找塞拉摩島的古斯塔夫·範沃森醫生。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6629,'zhTW','殺死格魯迪格·暗雲',' $N ，你很好地完成了殺掉恐怖圖騰成員的任務。如果你有膽量的話，就去挑戰格魯迪格·暗雲和他的手下吧，他們是最難對付的敵人，而格魯迪格就是攻擊我們村莊的主謀。$B$B你可以在這裡西邊稍遠的地方找到恐怖圖騰崗哨，他就在那裡。殺了他，我會永遠感謝你的。','殺掉格魯迪格·暗雲和6個恐怖圖騰蠻卒，然後向石爪山東南面的瑪卡巴·扁蹄覆命。','','去石爪山脈和貧瘠之地的交界處找瑪卡巴·扁蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6661,'zhTW','捕捉礦道老鼠','慢著，你這飯桶。你...你在找活幹嗎?我們這兒鼠災氾濫，甲板上人手不夠。$B$B你說什麼?你只需要吹奏這根捕鼠者之笛就行了，牠們會跟著你走向生命的盡頭!$B$B給我抓五隻小壞蛋來，把牠們交給我，我要活的。$B$B啊...','使用捕鼠者之笛捕獲5隻礦道老鼠，把老鼠們引到蒙提那兒去。','','去鐵爐堡找坑道地鐵的蒙提。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6681,'zhTW','拉文霍德莊園',' $N :$B$B拉文霍德已經對你感興趣了，小賊。我們一直在觀察你。你的狀況有些尷尬，但沒有什麼是我們不能改變的。$B$B如果你想要在拉文霍德大人手下謀求一份工作，以及成為刺客聯盟的一員，只需把拉文霍德徽印(已附在信中)拿到拉文霍德莊園來。$B$B你的第一項任務就是要找到莊園，它就隱藏在希爾斯布萊德的群山之中，你要充分發揮你的聰明才智。$B$B向你致敬，$B$B- 法拉德。','把拉文霍德徽印交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。','','去希爾斯布萊德丘陵找拉文霍德莊園的法拉德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7383,'zhTW','泰達希爾:卡多雷的重擔','你現在必須要立刻前往位於神諭之樹枝幹底部的那口月井，就在此處的西北方深處。那是我們的第一個，也是最強大的一口月井，據說井水具有伊露恩能量的純粹精華。$B$B取回一瓶井水帶來給我。當你的任務完成後，我會在達納蘇斯前方的路口與你碰面。','裝滿紫水晶之瓶。','','去泰達希爾找多蘭納爾的科瑞薩斯·月怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7790,'zhTW','黑紙白字','你可沒預計到這個...','攻下戰歌鋸木場，然後回來找我。','','找強納森·樂卡夫特談話。','佔領戰歌磨坊','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8154,'zhTW','阿拉希盆地的資源!','我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，饑腸轆轆地開向戰場!$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材─所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方， $N 。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回一箱資源來。','獲得阿拉希盆地戰鬥的勝利，獲取一只阿拉希資源木箱，然後向避難谷地的瑪克里爾中士覆命。','','去阿拉希高地找避難谷地的瑪克里爾中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8155,'zhTW','阿拉希盆地的資源!','我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，饑腸轆轆地開向戰場!$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材─所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方， $N 。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回一箱資源來。','獲得阿拉希盆地戰鬥的勝利，獲取一隻阿拉希資源木箱，然後向避難谷地的瑪克里爾中士覆命。','','去阿拉希高地找避難谷地的瑪克里爾中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8156,'zhTW','阿拉希盆地的資源!','我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，饑腸轆轆地開向戰場!$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材─所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方， $N 。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回一箱資源來。','獲得阿拉希盆地戰鬥的勝利，獲取一隻阿拉希資源木箱，然後向避難谷地的瑪克里爾中士覆命。','','去阿拉希高地找避難谷地的瑪克里爾中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8166,'zhTW','阿拉希盆地之戰!',' $N ，在阿拉希盆地的戰鬥是為了資源和領土而進行的戰鬥。這個地區作戰的關鍵是保證我們軍隊稀有物資和補給的順暢運作。我命令你去攻擊距離我們在阿拉希盆地中的基地最遠的戰略設施。$B$B當農場、礦坑、伐木場或鐵匠舖被敵人佔據時，攻擊這些設施，找到敵人的旌旗，然後把它拔掉!$B$B當你完成了奪回這四個點的任務之後，就回到我這裡來。','進攻礦坑、伐木場、鐵匠舖和農場，然後向避難谷地的奧斯萊特元帥覆命。','','去阿拉希高地找避難谷地的奧斯萊特元帥。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8167 AND `locale` = 'zhTW';
