INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8799,'zhTW','節日英雄','聽好...我不應該告訴你這件事情的內容，但既然你是今日的英雄...$B$B每年的這個時候到處都有新鮮的冬青，但是都沒法保存太久。我們有一台保存的機器，能為冬青永遠保鮮!我們用它來點綴節日...在夏天的時候還可以賺取利潤!$B$B我會讓你使用保存機，但你一定要是個大師級的廚師才行。你需要一些石中鹽和兩個，三個，喔五個好了，五個金幣。我會幫你弄到一批好貨的。','攜帶1份石中鹽及5個金幣到冬青保存機去，你可以獲得5份保存的冬青。','','去找冬青樹儲藏器。','','','','',0);
