INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9293,'zhTW','必要手段……','附近的湖已受到其中一塊船用能量水晶的污染。許多安曼谷的植物和動物也都因此產生突變。$B$B我有個方法可以治療湖泊，但我需要突變的鞭笞者樣本來做分析。他們就在西邊的安曼牧場裡。$B$B你能幫我嗎， $C ?','收集10個鞭笞者樣本再回到安曼谷的失事地點找植物學家泰瑞茲。','','去找埃門谷墜毀點的植物學家塔蕾克絲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9294,'zhTW','拯救湖泊','感謝老天爺，我想它產生作用了!我會給你一個藥劑讓你散播在南邊的銀線湖裡。它會中和掉散落在這附近的放射性船用能量水晶所產生的影響。$B$B游到那裡並散播我的中和劑。別擔心，你不會因為待太久而被輻射影響的。','對放射性能量水晶散播中和劑。然後，再回到安曼谷的失事地點找植物學家泰瑞茲。','','去找埃門谷墜毀點的植物學家塔蕾克絲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9303,'zhTW','注射疫苗','薩那需要我們的幫忙來搶救艾克索達的部份區域。泰瑞茲準備了一份疫苗可以用在奈斯特灌木林梟獸身上，大部分需要搶救的地區都有他們的蹤跡。$B$B只要靠近未注射的梟獸再使用水晶就可以了。不幸的是，你必須殺了其他的生物。你可以在東南邊的奈斯特灌木林和奈斯特山丘找到他們。','在6個奈斯特灌木林梟獸身上使用注射用水晶。再回到安曼谷的失事地點找復仇者艾德。','','去埃門谷找墜毀點的守備官奧達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9305,'zhTW','備用零件','我們已設法找到在失事中損壞的全像攝影發射器。如果我們能修好它，那麼我們就有機會找到安曼谷外的其他生還者。$B$B我們知道鄰近區域有些船上的儀器可以拿來做為備用零件，不過當地的梟獸早已搶先我們一步偷走它們。$B$B $N ，我們要你前往南邊的奈斯特灌木林和山丘，找到那些備用零件!','收集4個發射器的備用零件。然後再回到安曼谷的失事地點找技師·薩那。','','去埃門谷找墜毀點的技師沙娜安。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 9311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9311,'zhTW','血精靈間諜','我有一個計畫。我們一定要殺了他們的領導者。他們沒有了主人，或許會撤退重建勢力。我們只要爭取時間直到修復完成。$B$B然後復仇者艾德一定會知道這件事。殺了勘測員，再回去告訴他我們發現了什麼。','殺死勘測員坎翠斯，然後把這裡發生的事告訴安曼谷失事地點的復仇者艾德。','','去埃門谷找墜毀點的守備官奧達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9369,'zhTW','補充治療水晶','我們是德萊尼。我們的船失事了，而且由於我們有許多傷者，我們現在最擔心的就是治療水晶的庫存。我們一定要盡快補足水晶!$B$B不幸的是，我們此時唯一的選擇就是從當地的山谷飛蛾身上直接抽取血液。牠們的血液是很合適的替代品。$B$B你可以在溪谷附近的區域找到牠們，不過牠們大多集中在西北方。','從附近的安曼谷飛蛾身上取得6瓶飛蛾血清，再交給安曼谷失事地點的波尼特斯。','','去埃門谷找墜毀點的普羅尼圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9435,'zhTW','遺失的水晶','如果希爾斯布萊德有什麼很棒的事實，那就是那裡註定要活在戰爭的陰影之下。就連像一車的石頭這樣無害的東西都是目標。$B$B通常損失建築材料不是什麼了不起的挫敗，但最近從碧玉礦坑運來的貨物裡包含了一箱我急著要研究的稀有水晶。被遺忘者劫掠者攔截了那輛貨車，並把它開到東北方他們想重建的哨塔那裡。我們一定要立刻奪回那些水晶， $C !','從被遺忘者那裡取回一箱稀有水晶並交給南海鎮的胡嵐。','','去希爾斯布萊德丘陵找南海鎮的忽爾蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9516,'zhTW','摧毀軍團','我絕不容忍他們活在這世界上!燃燒軍團摧毀了我們的種族，迫使我們到新世界建立新家園。然後他們一次又一次的出現，我們只能一再撤退。$B$B夠了!$B$B在南邊與西邊的冥火嶺、屠魔峽谷和屠魔山裡，有一群燃燒軍團的餘孽。他們是燃燒軍團在久遠之前入侵這世界時遺留下來的。$B$B趁還來得及的時候過去殺光他們!','在冥火嶺、屠魔峽谷和屠魔山裡殺死15個惡魔。','','去梣谷找林歌神殿的守備官維達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9517,'zhTW','可恥的浪費','歡迎來到林歌神殿， $C 。你現在看到的帳篷，就是將來會蓋建築物的地方，但這樣的目標需要穩定的建築材料來源。我不能讓我的工人砍伐樹林裡的任何老樹，但我們在南方和西方的鄰居對森林就沒有這樣的敬畏了。$B$B我們將盜取戰歌伐木工砍伐的木材，從西邊的薩特要塞取回一些受汙染的木材。把木頭帶給樹瘤，他會淨化它們以做使用。','收集5塊薩提納爾魔化木材。','','去梣谷找戰歌伐木營地的納亞爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9518,'zhTW','毀滅間諜','戰歌伐木營地是使這片土地陷入備戰狀態的禍端。每當我們阻止他們的運作有所進展時，監督者高薩克就會命令他的伐木工加倍努力!$B$B現在，獸人砍的木材比他們會用到的還多，當他們的刀身砍進新的樹時，那些木頭就留在那裡腐爛!這對我們而言是公然的侮辱， $N ，我們要讓他們知道我們不會讓土地受到更多的毀滅!$B$B去吧，監督者高薩克和他的爪牙死掉之前都不要歇息!','在戰歌伐木營地殺死監督者高薩克，和任意12個部落。','','去梣谷找林歌神殿的哨兵盧希爾·星語。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9519,'zhTW','丟失的酒杯','我們西邊的地方現在叫做薩提納爾，它曾是我的族人建立的重要神殿。那裡面有一個無價的聖物，伊露恩酒杯，是伊露恩的祭司委託神殿守衛保管的。朝聖者曾前往神殿體驗酒杯傳說中的治療能量。$B$B這些故事或許只是無稽之談，但如果它們有任何一點真實性，那個聖物就可能讓受傷的森林恢復過來。我一定要知道真相， $N 。','取得伊露恩酒杯。','','去梣谷找林歌神殿的凱尼斯·靜風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9526,'zhTW','奪回冥火嶺','小傢伙，西南方有個屬於夜歌森林的區域，在最近被改稱為冥火嶺。看見惡魔佔據著那裡、腐蝕著那塊土地教人十分哀痛。$B$B你能做些什麼來幫忙奪回這片地嗎?$B$B我有一些特別為這種目的保留下來的種子。將它們帶去冥火嶺，種植到肥沃的土堆中。','將8顆樹苗種植在肥沃的土堆裡。','','去梣谷找林歌神殿的納亞爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9799,'zhTW','植物學家的跑腿任務','西邊的安曼牧場是當地主要的鞭笞者繁殖地。因為附近湖泊的地下水污染，植物學家泰瑞茲擔心一旦我們淨化湖泊，鞭笞者將無法再自己重新繁殖。$B$B前往安曼牧場摘一些受污染的花給我，或許我可以看看它們並想個辦法。你可以不尋常的紅色花瓣來辨別它們。','收集3朵被污染的花朵再回到安曼谷的失事地點找學徒米虛歐。','','去埃門谷找墜毀點的學徒維莎爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10302,'zhTW','暴躁突變者','來自艾克索達散發輻射的能量核心一直對這裡的環境造成浩劫。最明顯的效應是，它們附近開始出現一些奇怪的生物。$B$B也許我們能做些事情去幫助他們，但是現在，他們十足的數量已非我們的能力所能處理了。$B$B我要你去削減他們的數量，或許給我一點時間思考，我將有別的辦法對付它們。','殺死8個暴躁突變者，然後返回安曼谷的失事地點的植物學家泰瑞茲那裡。','','去找埃門谷墜毀點的植物學家塔蕾克絲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10303,'zhTW','血精靈','你必須消滅……血精靈……威脅。查明……他們目的……是甚麼!$B$B他們在我後面的山脊上。','殺死10個血精靈斥候，然後返回安曼谷裡暗影山脊的托蘭那裡。','','去埃門谷找暗影山的圖蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10517,'zhTW','哥爾迪姆，你的死期到了...','劍刃要塞的領導者叫哥爾迪姆，相信我…這個名字很適合他。$B$B但我不會低估他的，他畢竟成功提升了自己氏族的地位，現在成為弒龍者戈魯爾最信賴的氏族。如今他們支配著這些山脈。哥爾迪姆隨時都有一位隨扈跟在身邊，其中還有滴酒不沾的防衛者。$B$B為了希爾瓦納的安全，我需要你回去解決他。','殺掉劍刃要塞巨魔的首領，哥爾迪姆。','','去劍刃山脈找刀塔要塞的守備官烏里恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10712,'zhTW','飛行測試:魯安曠野','你好阿，$n。很高興又遇到你了!我有一個非常重要的任務!$B$B這是一個旋轉的虛空天氣風向儀。我需要你在飛行時帶幾個幫我閱讀上面的數據後再將它們交給我在魯安曠野的親戚。$B$B與瑞利談談後搭乘一架ZC號飛往魯安曠野去。在你飛行時，轉動這個風向儀!$B$B登陸後，帶著這個旋轉風向儀給歐瑪利‧贊普奈。$B$B祝你好運，$n。別遲到了!','與瑞利‧薩普納伯談談以使用ZC號。飛到魯安曠野的途中，轉動虛空天氣風向儀。將旋轉的虛空天氣風向儀送到永恆樹林給歐瑪利‧贊普奈。','發射到盧安荒野。','去劍刃山脈找常青林的歐瑪利·薩普納波。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11025,'zhTW','頂尖水晶','經過適當的事前準備，那些山區中的水晶就能展現出它的奇異能量，就好像我們在歐格利拉發現它有使人思緒清晰的能力。$B$B山上的生物都垂涎著那些水晶裂片，並且將其裂片使用於他們私人的用途之上。那些水晶的價值甚至還引起了一些商機。$B$B想協助我們的話，你必須先學習了解頂尖裂片。幫我找一些裂片回來。除了這裡的生物會攜帶頂尖裂片之外，有時候你也可以在鐮奪怪挖掘水晶的地方發現裂片。','裘阿洛要你收集5塊頂尖裂片，然後回到劍刃山脈上方的歐格利拉交給他。','','去劍刃山脈找奧格瑞拉的庫洛爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11408,'zhTW','為提洽里的巫毒釀酒廠而吶喊!','我們需要讓大家知道有關食人妖參加了啤酒節的事情。你得到力量谷的拍賣場外，還有榮譽谷、智慧谷以及精神谷的旗幟下大聲叫喊。不過我會讓事情簡單點，我會借你一頭競速山羊，為時4分鐘。$b$b不過小心點，哥布林可沒有在沿路上放蘋果，他們就是這麼小氣。','在力量谷的拍賣場外的旗杆下，榮譽谷、智慧谷與精神谷散佈有關啤酒節的訊息。','','去找杜洛塔的亞隆。','在拍賣場外叫賣','在榮譽穀叫賣','在智慧穀叫賣','在精神穀大喊',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11653,'zhTW','哈...你現在可沒那麼大囉!','這樣就可以應付她了，老大!接下來，我要你這麼做...$B$B帶著我的光束槍，朝著北邊前往瑪格默斯。如果我們想要有機會對抗那些怪物，我們必須減小他們的體型...就這麼辦。$B$B為了評估光束槍的效能，我要你在猛瑪象人身上的光束槍效果結束之前殺掉牠們。任何粉碎者或是配偶都可以，不過放過那些後代吧...他們還很小，不用擔心。','在5隻瑪格默斯粉碎者或瑪格默斯瑞卡的配偶身上檢測卡芙緹的超進階初體版微縮光束槍。在完成後，回到嘶軸簡易機場找她。','','去北風凍原找菲茲蘭克機場的機靈鬼沃比斯波基。','測試卡芙緹的光束槍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11694,'zhTW','洞穴裡的古怪','所以呢，雖然你已經處理了那些染疫野獸，但是我還是偷看了一下洞穴的內部。$B$B裡頭的教徒們正在進行瘟疫化!$B$B他們將某種有毒的混合物放在大鍋中釀煮著。我有一種平常用來解毒的粉末，我將它混合了其它的東西。我想這將可中和他們的釀煮物!$B$B帶著這個粉末前往其中一個洞穴試試看有沒有效。','潛伏在垂死獸穴南方的碧西‧扭柄要你對垂死獸穴瘟疫大鍋使用碧西的抑制粉末來中和它。','','去找北風凍原的比希·鉗柄。','中和瘟疫大鍋','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11698,'zhTW','不如徹底消滅天譴軍團','如果那些洞穴上方的教徒們可以在這場破壞中存活下來，那麼只能假定西邊那個倒坍的亡域當中仍充滿著天譴軍團。前方的池子也一定滿滿的都是天譴軍！$B$B雖然你人在塔爾拉瑪斯，$c，你覺得你可以殺光所有在那發現的巫妖王奴僕嗎？','摧毀20個位於塔爾拉瑪斯和膿瘡之池的天譴軍，不限種類。接著，回到北風凍原的垂死獸穴正南方找碧西‧扭柄。','','去找北風凍原的比希·鉗柄。','摧毀塔爾拉瑪斯的天譴軍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12233,'zhTW','處理種子','不，不……還是你拿著吧。$B$B你不會真的想讓我拿著它們吧？$B$B接下來你該這麼做……','不，不……這些東西你留著。$b$b在經歷了那些事之後，你該不會真的以為要由我來處理這些吧？$b$b你接下來要做的是……','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12452,'zhTW','晶紅龍殿的命運','把達莉亞的紅寶石胸針帶給賽里斯特拉茲，並告知他她的命運。','將妲莉雅的紅寶石墜飾交給賽利斯塔茲，並將妲莉雅之死告訴他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12502,'zhTW','食人妖巡邏:旗幟高揚','聽著，$c。這是銀白十字軍。我們的手下將會奮戰到底，無論狀況如何都毫無埋怨。$b$b有人說，我們已經在此戰役中部分傷亡慘重，而且我們已經好幾個月苦於只能小瞇一會兒或根本不能睡。無論我們接不接受，那對士氣有著嚴重打擊。$b$b或許情況看起來並沒有那麼嚴重，不過能夠看到我們的旌旗高舉在戰場中對我們的士兵來說無疑是一種安慰。帶著這些旌旗並在德拉克索璀的石臺上高舉它。','布蘭登上尉要你將銀白十字軍旌旗放置在德拉克索璀的德拉克瑞石臺上。','','去祖爾德拉克找達克索塔的布蘭頓上尉。','南邊銀白十字軍旌旗','北邊銀白十字軍旌旗','東邊銀白十字軍旌旗','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12509,'zhTW','食人妖巡邏:勇氣','終於，巡邏抵達了!$b$b這就是目前的狀況，$r。我們在這場戰役中失去了許多精良的士兵，所以必須召集我們的新兵來填捕空缺。$b$b我們剛經歷了一場慘烈的戰役，許多新兵根本沒準備好要面對這次的敵人。往後還會有更多的戰鬥，我需要他們將身心準備好遵從命令。$b$b要是有什麼是我無法忍受的，那就是懦弱了。或許你可能幫助他們找回勇氣，好讓他們繼續迎戰。','德拉克索璀的魯伯特上尉要你去替畏縮的十字軍新兵回復勇氣。','','去祖爾德拉克找達克索塔的魯伯特上尉。','回復新兵的勇氣','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12519,'zhTW','食人妖巡邏:你想要啥，一面勳章?','看著我，$r。我看起來像是有空寫報告的樣子嗎?$b$b我光是把該死的天譴軍擋在哨站外就快忙死了，他們還想要我搞文書工作!$b$b<嘆息>抱怨也沒用。我得把上一場戰鬥的死亡記錄送去給指揮官。$b$b你想幫忙嗎?去把附近所有死掉的食人妖身上的勳章拿來給我。那些應該差不多就夠了。','大競技場外的格隆戴爾上尉要你從附近的德拉克瑞屍體上收集7個德拉克瑞勳章。','','去祖爾德拉克找痛苦鬥獸場的格隆迪爾上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12541,'zhTW','食人妖巡邏:鍊金師的學徒','喔，你一定是那個他們承諾的巡邏兵。你來得正好。我們迫切地需要額外的人手。$b$b有個德拉克瑞囚犯被送來審問。在訊問開始之前，我需要有人幫忙我製作一份自白劑。$b$b製造自白劑是一項困難的工作，需要敏銳的直覺，完美的計時，每一步都需要臨機應變。$b$b當你準備好了就跟我講一聲，$r。記住，一切都是靠計時啊!','希伯伐洛克的鍊金師芬克斯坦要你協助他製作自白劑。$b$b你準備好要開始的時候就和他交談，然後遵循他的指示。','','去祖爾德拉克找赫布瓦羅的鍊金師菲肯斯坦。','完成自白劑','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12677,'zhTW','危險物質','荒疫水晶?!這該死的德拉庫魯究竟想要做什麼?$b$b顯然，他在做的事很重要。繼續完成他的要求，也許當他跟你更熟了以後，就會讓你知道他的計畫。$b$b在此期間，我們得調查這些水晶。$b$b當你進入沃塔魯斯的時候，試著趁沒人注意的時候弄來一些採收的水晶。$b$b小心點!處理那些水晶的時候你的偽裝有可能會消失。','黯黑守望的史戴芬要你去沃塔魯斯完成任何德拉庫魯要你做的任務。當你到那裡的時候，要去偷取5個採收的荒疫水晶。$b$b如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。','','去祖爾德拉克找黑鋒哨站的斯特凡·瓦杜。','完成德拉庫魯的任務','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12682,'zhTW','人跡未竟之地(DEPRECATED)','並非所有的遠征隊成員都是來狩獵取樂的，我們中的一部分人還肩負著重要的研究工作。$B$B冰封的諾森德中心竟然存在這樣一片熱帶天堂——休拉薩盆地真是不可思議的存在。如果我不能搞清楚這片土地的奧秘，就不配做個學者。$B$B這張地圖給你吧。','這次遠征隊裡並不是所有人都是來獵殺最大、最稀有的獵物的。我們之中有些人其實有正經事要做。$B$B這個地方的存在本身就令人費解——在諾森德的中央居然有一片熱帶樂園。如果我不花點心思試著了解這個地方，那我這個學者的頭銜可就名不副實了。$B$B拿著這些','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12825,'zhTW','表達謝意','[佔位文字] 使用迷你飛機對豺狼人首領實施自殺式衝撞。','用迷你飛機神風特攻豺狼人領袖。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12834 AND `locale` = 'zhTW';
