INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12837,'zhTW','貨在托爾那','[佔位文字] 向托爾回報。','向托爾回報','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12860,'zhTW','資料探勘','你組成的那個圓盤…是空的！那個奸詐的彌米爾一定把東西藏在別的地方了。找找看發明者的圖書館;你在那裡有看到資料庫嗎？$B$B也許那就是你拿圓盤要做的事情。嘗試用它靠近那些資料庫。或許它會檢索，然後重新存取資料。等你嘗試之後，再聯絡我，讓我知道你找到了什麼。在此同時，我會去找另一半的鑰匙。','用發明者圓盤檢索7份在資料庫裡的隱藏資料。','','使用布萊恩的通訊器聯絡布萊恩·銅須。$B$B如果你弄丟了聯絡器，你可以與冰霜堡的考古學家安多林重新要個新的。','取得隱藏資料','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12863,'zhTW','致謝','啊!謝謝你到這裡來$G小子:小女孩;。$B$B從你圓睜的雙眼和顫抖的雙手看來，我敢大膽地推測你是新來的。聽起來讓你見見我們親切的地主會是個好主意。$B$B我們有些多餘的醫療補給品...老實說，我們沒料到能夠擁有這麼舒適的據點。去把這個箱子拿給那邊的格洛梭，如果你願意的話，再幫他一把。我們實在受到很多照顧接待，因此不希望他們認為我們不知感激。','把醫療補給箱交給霜堡的格洛梭‧硬鬚。','','去風暴峭壁找冰霜堡的格羅薩·硬須。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13173,'zhTW','騷動之中','我們已經弄到了不少工人。他們會很有用的。$B$B我要你用眼睛控制其中一個工人返回挖掘場。現在整個營地都陷入了混亂，他們肯定會把當成你在襲擊中走散的工人，你不會露餡的。$B$B你要找出工廠的負責人並動手幹活。如果夠幸運的話，我們很快就能發現那些邪鐵的去向。我會通過眼睛關注你的。','我們抓到了不少工人，他們應該能派上用場。$B$B我要你用眼睛把其中一名工人帶回採石場。既然整座營地已經亂成一團，他們絕對沒辦法把你跟其他被攻擊打散的工人分辨出來。$B$B找到負責這次行動的人，然後開始工作。運氣好的話，我們很快就能查出那些薩隆邪鐵被運去哪裡了。我會透過眼睛在旁看著你。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13315,'zhTW','暗中偵察','一切都在計畫之中。我們策劃了一連串完美的計畫來奪下死亡之門。傷亡雖是必然， 但最終的勝利將屬於我們－咬緊牙關對付那些愛管閒事的部落...$b$b不論如何，我們的下一個需要關切的目標是荒寂之門。飛往那兒並試著熟悉敵人的據點。$b$b當你回來我會再給你進一步指示。','破天者號上的薩沙理安要你飛往荒寂之門，偵察門的南、中、北、西北區域。','','去冰冠冰川找破天號的薩薩里安。','前往奧多薩南部','前往奧多薩中部','前往奧多薩北部','前往奧多薩西北部',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13397,'zhTW','辛德拉苟莎之殞','你真的天生適合這行，$n。你瞧，通常當我指派任務給其他士兵。他們完成的機率大概一半一半，至於回來的機率...呃，大概要再少一點。$B$B但是你，永遠是使命必達。就像地精鐘錶一樣精準!$B$B總之呢，我還有任務給你。辛德拉苟莎之殞，就在山谷東邊。那邊有許多的教徒正蠢蠢欲動，更別提冰霜巨龍的紛擾。我要你去給我教訓那些傢伙。$B$B我討厭那些教徒。','破天者號上的薩沙理安要你在辛德拉苟莎之殞殺掉5個巨龍復生者、8個教徒墮落者以及3個維酷死靈領主。','','去冰冠冰川找破天號的薩薩里安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13423,'zhTW','衛冕','每個人都對你的表現印象深刻，姊妹。但是不要放鬆了戒心!每個迷於聲名的挑戰者都將會上前挑戰你的海茲戰后頭銜。$B$B給這些傲慢自大的傢伙一點教訓，讓她們見識一下你的戰后本色。','布倫希爾達村的『仲裁者』格瑞塔要求你擊敗六個挑戰者。','','去風暴峭壁找布倫希爾達村的仲裁者格蕾塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13424,'zhTW','重返深淵','要保持最好的騎術，你就得每天與其他海迪尼爾切磋。$B$B返回尖牙之淵，把你的技術展現給她們看。她們會很感激像你這樣高超的人將她們擊敗的。','布倫希爾達村的『仲裁者』格瑞塔要你到尖牙之淵使用冰喉族母韁繩，然後擊敗6頭海茲競技戰熊。','','去風暴峭壁找布倫希爾達村的仲裁者格蕾塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13713,'zhTW','驍士的挑戰','你幾乎已具備代表鐵爐堡參加技擊大賽的資格了。為了要證明你足以加入城市代表隊名單中，你必須要擊敗一位銀白十字軍的勇士。$B$B前往亭閣外的獸欄，裝備你的長槍並乘上坐騎。到聯賽場地西側的銀白驍士競技場找侍從丹尼。等你準備好之後，侍從會叫出你的對手。$B$B等戰鬥結束之後，我們再來談一談結果。','和侍從丹尼談談以召喚你的對手。一旦你擊敗銀白勇士，回到銀白聯賽場地去找菈娜‧頑錘。$B$B如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。','','去找冰冠冰川的拉娜·硬錘。','擊敗銀白勇士','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13931,'zhTW','又過了一年，又一個紀念品。','我們不但供應每個人啤酒，同時還贈送酒杯!只要用合法的方式就可以換取漂亮的紀念杯!這張兌換卷給你。$b$b跟啤酒節營地後方的布力克斯談話。他是個怪傢伙，甚至現在也還戴著那副護目鏡。他會幫你處理那張兌換券，而所有啤酒節的交易也都可以找他。','把啤酒節酒杯兌換券交給啤酒節營地後方的布力克斯‧修械。','','去找杜洛塔的布利克斯·菲克維特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14082,'zhTW','在艾克索達學習騎術','這本介紹著騎術訓練與購買坐騎的小手冊是阿露恩送來的。$B$B阿露恩就在藍謎島的艾克索達入口處。','到藍謎島的艾克索達外頭，把這本小手冊繳回給阿露恩。','','去找秘藍島的埃亞倫。','','','','',0);
