INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14083,'zhTW','在丹莫洛學習騎術','這本介紹著騎術訓練與購買坐騎的小手冊是奧薩姆‧鐵角送來的。$B$B奧薩姆就在丹莫洛的凍石農場，沿著鐵爐堡外的路向東走即可抵達。','到丹莫洛的凍石農場，把這本小手冊繳回給奧薩姆‧鐵角。','','去丹莫洛找凍石農場的奧薩姆·鐵角。','','','','',0);
