INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14084,'zhTW','在丹莫洛學習騎術','這本介紹著騎術訓練與購買坐騎的小手冊是賓吉‧羽哨送來的。$B$B賓吉就在鋼架補給站，丹莫洛卡拉諾斯的東北方。','到丹莫洛的鋼架補給站，把這本小手冊繳回給賓吉‧羽哨。','','去丹莫洛找鋼架補給站的賓吉·羽哨。','','','','',0);
