INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14085,'zhTW','在達納蘇斯學習騎術','這本介紹著騎術訓練與購買坐騎的小手冊是賈薩姆送來的。$B$B賈薩姆就在達納蘇斯的塞納里奧區。','到達納蘇斯的塞納里奧區，把這本小手冊繳回給賈薩姆。','','去達納蘇斯找貿易區的賈薩姆。','','','','',0);
