INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14087,'zhTW','在莫高雷學習騎術','這本介紹著騎術訓練與購買坐騎的小手冊是卡爾‧雷詠送來的。$B$B卡爾就在莫高雷的血蹄村。','到莫高雷的血蹄村，把這本小手冊繳回給卡爾‧雷詠。','','去莫高雷找血蹄村的卡爾·雷歌。','','','','',0);
