INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14089,'zhTW','在提里斯法林地學習騎術','這本介紹著騎術訓練與購買坐騎的小手冊是維爾瑪‧瓦納姆送來的。$B$B維爾瑪就在提里斯法林地的布瑞爾。','到提里斯法林地的布瑞爾，把這本小手冊繳回給維爾瑪‧瓦納姆。','','去提瑞斯法林地找布瑞爾的維爾瑪·瓦納姆。','','','','',0);
