INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14168,'zhTW','感激的亡者','能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。','拿一些亡者麵包給鐵爐堡墓地中興奮的地精靈魂。$B$B使用橘色金盞花可以看見這些隱形的靈魂。','','去找丹莫洛鐵爐堡大門附近的侏儒靈魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14170,'zhTW','感激的亡者','能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。','拿一些亡者麵包給達納蘇斯墓地中興奮的夜精靈靈魂。$B$B使用橘色金盞花可以看見這些隱形的靈魂。','','去泰達希爾找多蘭納爾的歡快的暗夜嚮導靈魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14203,'zhTW','浸水的配方','看起來這似乎是張調配烈酒的破舊配方。也許達拉然的「勸君更進一杯酒」的老闆對它會有興趣...','將浸水的配方交給達拉然城的克利斯蒂‧斯托克頓。','','去達拉然找再來一杯的克莉絲蒂·斯多克頓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24541,'zhTW','竊取香水','我就知道他們圖謀不軌!這東西含有某種思想控制的化學成分，但光憑這種小樣本，我仍無法掌握他們的把柄。我需要的是成品。

你可別大搖大擺的跑去跟他們買!我不想看你付給那些下流胚子任何一分錢。不，你必須不著痕跡的從他們的源頭下手。

我會把你偽裝成一個送貨員。我看到他們僱用的惡棍在大門外看守著一批囤貨。用跑的過去那邊，記得別停下來，不然他們會逮到你!他們會丟給你一個箱子。把它帶回來這裡。','當你偽裝成送貨員時，前往奧格瑪大門外的王冠化學製藥公司的囤貨區，把他們交給你的包裹帶回去給奧格瑪的警探史內卜‧凸栓。','在奧格瑪外潛入皇冠化學公司偷取香水包裹','到奧格瑪找警探史內卜‧凸栓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24549,'zhTW','影之哀傷...','至尊領主戴里恩·魔葛林要你把影之刃帶給他。','大領主莫格萊尼要你把暗影之鋒交給他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24656,'zhTW','竊取香水','我就知道他們圖謀不軌！這東西含有某種思想控制的化學成分，但光憑這種小樣本，我仍無法掌握他們的把柄。我需要的是成品。

你可別大搖大擺的跑去跟他們買！我不想看你付給那些下流胚子任何一分錢。不，你必須不著痕跡的從他們的源頭下手。

我會把你偽裝成一個送貨員。我看到他們僱用的惡棍在大門外看守著一批囤貨。用跑的過去那邊，記得別停下來，不然他們會逮到你！他們會丟給你一個箱子。把它帶回來這裡。','當你偽裝成送貨員時，前往暴風城大門外的王冠化學製藥公司的囤貨區，把他們交給你的包裹帶回去給暴風城的巡官史尼卜‧凸栓。','偷取皇冠藥劑公司的包裹，然後離開暴風城。','到暴風城找巡官史尼卜‧凸栓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24795,'zhTW','白銀誓盟的勝利','儘管菈娜薩爾女王對你冷嘲熱諷，你還是復原了奎爾德拉，$n。長久以來，取回奎爾德拉一直是我們的夢想。$B$B白銀誓盟與所有辛多雷欠你一份感恩之情。$B$B因為你是一個$c，劍刃似乎認為你缺乏劍術訓練，所以並沒有跟你產生連結。既然這樣，它的下一個主人會在哪裡呢？也許銀白十字軍可以找到合適的人。到北邊的銀白聯賽場地，以白銀誓盟的名義把劍交給審判者瑪瑞爾‧真心。','到銀白聯賽場地，把復原的奎爾德拉交給審判者瑪瑞爾‧真心。','','去找銀色比武場中銀色大帳的裁決者瑪蕾爾·圖哈特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24801,'zhTW','奪日者的勝利','為了奪日者與部落的榮耀，奎爾德拉終於復原了!這對我們對抗巫妖王所付出的努力而言是一大賜福。$B$B等你從太陽之井歸還之後，奪日者的領袖大法師埃薩‧奪日者邀請你見他一面。帶著奎爾德拉儘快前往達拉然的紫羅蘭城塞，$n。大法師希望能夠親自恭賀你!','到達拉然紫羅蘭城塞，把復原的奎爾德拉交給大法師埃薩‧奪日者。','','去達拉然的紫羅蘭城堡找大法師艾薩斯·奪日者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24872,'zhTW','受苦靈魂的安息','你跟你的同伴都帶著這個生命水晶。它內含了來自龍骨荒野的翠綠龍殿中強大的能量，而這也是我能夠長久抵抗此地黑暗魔法的獨家秘方。$B$B當你迎戰辛德拉苟莎的時候，一但她開始呈現虛弱的狀態，就讓你的夥伴們使用這些水晶來誘導出她體內的精華。如果你隨後擊敗了她就會獲得精華，接著就把它帶回到龍骨荒野的龍眠神殿交還。','使用生命水晶來保存辛德拉苟莎的精華。','','將辛達苟薩的靈魂交給龍骨荒野中龍眠神殿的卡雷苟斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24880,'zhTW','受苦靈魂的安息','你跟你的同伴都帶著這個生命水晶。它內含了來自龍骨荒野的翠綠龍殿中強大的能量，而這也是我能夠長久抵抗此地黑暗魔法的獨家秘方。$B$B當你迎戰辛德拉苟莎的時候，一但她開始呈現虛弱的狀態，就讓你的夥伴們使用這些水晶來誘導出她體內的精華。如果你隨後擊敗了她就會獲得精華，接著就把它帶回到龍骨荒野的龍眠神殿交還。','使用生命水晶來保存辛德拉苟莎的精華。','','將辛達苟薩的靈魂交給龍骨荒野中龍眠神殿的卡雷苟斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25253,'zhTW','末日預言','末日先驅走在暴風城的街道上，這已經不是什麼稀奇的事情了，不過最近出現的這群人讓我蠻擔心的。這些傢伙是有組織性的，在舊城區吸引了大批群眾目光，那邊似乎也是他們的集會場所。$B$B我想做點什麼，像是一口氣把他們包圍起來，或是打斷他們的活動之類的，不過這只會驅使他們躲在暗處偷偷活動。我們得找出更多的同黨。你願不願意去趟舊城區?去聽聽看末日預言者們到底在散佈些怎樣的訊息，盡量多收集一些關於他們理念的文宣品帶回來給我。','到舊城區聽聽末日預言者的演說，並且取得《靈魂所需的那把元素之火》、《「世界末日」對我來說代表什麼?》、《在註定毀滅的世界中找尋安全與寬慰》這幾份文宣。','','返回暴風城的貿易區，去找安頓上尉。','聽聽末日預言者的演說','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25283,'zhTW','研擬講稿','大工匠梅卡托克要我寫篇講稿，他要在開戰前發表一場演說，不過我分辨不出哪篇是好哪篇是壞。$B$B你想，你能不能幫我試一下，看看本地地精居民的反應？這裝置會投射出國王梅卡托克的影像，然後從每篇中挑幾句念出來。$B$B讓我知道哪篇比較好，沒問題吧？','對卡拉諾斯西邊的奧齊‧電環、鋼架補給站的米利‧羽哨、以及卡拉諾斯旅店外面的托格‧鏽鏈使用地精播放裝置。試過所有講稿之後，回去向托比‧柴吉爾回報。','','返回鋼架補給站，去見託比·速輪。','對奧齊·電環發表演說','對米利·羽哨發表演說','對托格·銹鏈發表演說','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25285,'zhTW','進進出出','新的機械坦克已經整備完畢，隨時可以發動攻擊。你準備好要來看看這些狠角色的能耐嗎?!喔你當然準備好了!$b$b首先呢我們要確定的是，你進去之後有辦法出來。在戰鬥中，如果你覺得坦克快要爆炸了，先逃出來再說!我看過許多地精留在裡面的下場...坦克爆炸開來，那些地精也跟著爆開來。$B$B來吧，我已經幫這台坦克添加了彈射座椅的升級。幫我測試一下，好嗎?','測試彈射用機械坦克上的彈射系統。','','讓崔德·火鑽隊長知道你順利地使用了彈射系統。','彈射系統測試完畢','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25290,'zhTW','滲透行動','現在已經很難讓這個奇怪教派遠離公眾視野了。關於他們的謠言已經傳遍了全城。我想讓你加入那個教派，儘量從他們中間獲取情報。$B$B在舊城區找到一個末日預言者，告訴他，你想要加入他們。那個末日預言者很可能會給你一件他們的制服，並讓你去他們的秘密據點，結識其它教徒。$N，按照他的指示去做。這是取得他們信任的唯一方法。','與暴風城舊城區中的一名末日預言者交談並加入末日教，然後穿上他給你的末日教派新兵長袍。','','轉至明鏡湖果園，向先知席蘭德拉報到。','加入末日教派','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25295,'zhTW','開火','安全系統已連線!發動機功能運作正常!現在我們需要的只剩確認槍械是否可以正常射擊。$b$b我想這應該不會太難，$n。背後那座山丘上有台機械坦克，上頭的子彈沒有殺傷力。只要朝附近的靶子射個幾發，然後向我回報就可以了。','利用附近的標的物來測試射擊用機械坦克的武器系統。','','向崔德·火鑽隊長報告你的結果。','武器系統測試完畢','','','',0);
