INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8403,'zhTW','自然屏障','銀翼哨兵正在和戰歌前鋒部隊爭奪這片森林。當然，銀翼哨兵保護森林的原因並非只有熱愛大自然這條理由。$B$B梣谷的森林對我們來說是一層天然的戰略屏障，可以抵抗大規模的進攻。如果沒有這片森林的話，阿斯特蘭納很快就會完全暴露在貧瘠之地的攻擊部隊面前。你願意參加對抗戰歌前鋒的戰鬥嗎？為了聯盟！','將3枚戰歌峽谷榮譽獎章交給戰場外的聯盟準將。','','去找聯盟準將。','','','','',0);
-- Fix zhTW quest_template_locale rows using zhCN-style zone names instead of the official zhTW client terms (Shattrath, Sholazar Basin, Wintergrasp, Ghostlands, Grizzly Hills, Howling Fjord, Orgrimmar, Exodar)
DELETE FROM `quest_template_locale` WHERE `ID` = 32 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (32,'zhTW','異種蠍的威脅','這是我要你去遞送的報告，馬上把它送到能夠對其內容有深入瞭解的那些人的手中。$B$B我知道一個名叫基爾茲賓·鼓眼的巨魔學者，他致力於研究卡利姆多大陸上的那些與艾澤拉斯生態格格不入的生物形態；他簡直是一本活的生物書！如果你想要知道我們面臨的是怎樣的威脅，以及如何解決這個威脅，那就把這份報告交給他吧，我們現在需要一切可以得到的説明。$B$B基爾茲賓應該住在奧格瑪暗巷區的第二層。','把報告帶給奧格瑪的基爾茲賓·鼓眼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8258,'zhTW','達克雷爾的威脅','死亡騎士達克雷爾主宰了通靈學院的屍骨儲藏所。他威脅要扭曲整個靈魂國度來達到他自己的目的，我們必須阻止他！這就是水晶球可以幫助你的地方。$B$B在屍骨儲藏所地下室的中心使用預言水晶球，以此來召喚達克雷爾的爪牙。擊敗這些爪牙，接下來死亡騎士就會出現了。$N，把他的徽記帶給我！只有他的死亡才可以將靈魂國度的局勢扭轉過來！','在通靈學院地下室的屍骨儲藏所的中心使用預言水晶球，然後與被召喚出來的幽靈作戰。擊敗這些幽靈之後，死亡騎士達克雷爾才會出現，你的任務就是擊敗他。$B$B把死亡騎士達克雷爾的徽記交給奧格瑪智慧穀的薩格尼。','','去找奧格瑪的薩格尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8367,'zhTW','無上的榮耀','與聯盟作戰是為部落效勞的莫大榮耀！那些在各條戰線上和聯盟作戰的士兵是我們最偉大的成員。我們要消滅我們的對手，而不是僅僅進行小規模的遭遇戰，我們要打精心準備的大戰。$B$B去每一條戰線上消滅聯盟吧！為了榮耀！為了部落！','在每個戰場上都取得1枚榮譽獎章，並將它們交給任意部落主城或撒塔斯城中的部落戰爭使者。','','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8371,'zhTW','共同的努力','我們並不是在獨自與部落交戰，$g小夥子:小姑娘;。$B$B如果我們可以取得勝利，那麼我們就可以使用部落的資源來在其它的戰場上對抗他們。反之，如果我們輸掉了這場戰爭，那麼在其它的戰場上，部落將會佔有優勢。$B$B聯盟需要更多你這種身經百戰、意志堅定的老兵！$N，當你在所有戰場上都與部落交戰之後再回到我這裡。','在每個戰場上都取得1枚榮譽獎章，並將它們交給任意聯盟主城、達拉然或撒塔斯城中的聯盟準將。','','去找聯盟準將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9168,'zhTW','戴索姆之心','我們的敵人躲在戴索姆深處，瘋狂地製造著強大而致命的亡靈士兵。那些令人憎惡的生物簡直就是完美的殺戮機器，達爾坎親手製造了他們，戴索姆的黑暗魔法力量令他們變得更加強大。$B$B轉至達爾坎的要塞消滅那些亡靈士兵，$N。我們不但要鞏固自己在鬼魂之地的立足處，還要防止敵人擴展他們的勢力範圍。','殺死8個達爾坎之眼，然後向鬼魂之地太陽聖殿的魔導師伊東尼斯覆命。','','到鬼魂之地找博學者艾度尼斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10560,'zhTW','沙塔爾的崇敬','<阿達爾所發出的平和而寧靜的音律略略轉向低沉與憂鬱。>$B$<你的眼前浮現了一座帶有明顯納魯風格的巨大建築，你知道那是風暴要塞，它現在已經被凱爾薩斯的軍隊佔領了。他們還把那裡的強大力量用於某些極端邪惡的目的。阿達爾承諾，在你為奪回風暴要塞做出應有的貢獻之後，將賦予你更重要的使命。>','撒塔斯城的阿達爾希望你通過擊敗風暴要塞內的凱爾薩斯的軍隊，在沙塔爾陣營中達到崇敬聲望。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11116 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11116,'zhTW','納魯的試煉：瑪瑟裡頓','想要證明你自己擁有獲得風暴鑰匙的資格，你必須首先完成四個試煉。$B$B現在，你只需要跨越最後一個障礙了，凡人。聚集一支軍隊，轉至地獄火堡壘深處，在瑪瑟裡頓的巢穴中殺出一條血路，進入中央的密室，殺死那個邪惡的腐蝕者！$B$B完成了這個任務，你就將獲得風暴鑰匙。','撒塔斯城的阿達爾要求你殺死瑪瑟裡頓。','','到地獄火半島找阿達歐。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11130,'zhTW','閃亮閃亮的東西！','過來過來，$G夥計:寶貝兒;！讓我老格裡伏塔看看那些閃亮閃亮的東西……$b$b嗯嗯，嘿，不錯不錯，但應該還有更好的。對，對，好上許多的。$b$b<格裡伏塔向你斜過身來，低聲耳語道。>$b$b很多地方呢，有許多許多寶貴的閃亮閃亮的小玩意，但你得知道哪裡有才行！不過今天呢，可就是你的幸運日了。我認識一個能幫你忙的傢伙，可以讓你找到無數亮閃閃的東西，多得你都拿不動。$b$b去吧，去找我的老朋友巴德，他就在祖阿曼附近。你呢，就跟他說是老格裡伏塔派你去的，他就會讓你參加他的新計畫啦。','格裡伏塔要求你將他的便箋交給鬼魂之地的巴德，他就在祖阿曼外。','','到鬼魂之地找霸德·奈德瑞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11444,'zhTW','[PH]啤酒廣場A','[PH]找一個啤酒節宣傳員交談，他會在達納蘇斯、艾克索達、撒塔斯城或暴風城外的啤酒廣場。取得一個免費的鹹脆餅。','[PH]在任何一個啤酒廣場和啤酒節宣傳員交談，並取得免費的鹹脆餅。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11445 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11445,'zhTW','[PH]啤酒廣場B','[PH]找一個啤酒節宣傳員交談，他會在達納蘇斯、艾克索達、撒塔斯城或暴風城外的啤酒廣場。取得一個免費的鹹脆餅。','[PH]在任何一個啤酒廣場和啤酒節宣傳員交談，並取得免費的鹹脆餅。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11463,'zhTW','北海海賊','過去的幾周中海賊對補給船隻的攻擊持續增加。我們僱用了一個哥布林間諜來協助我們的探員滲透進入可疑的海賊中。$B$B這一群北海掠劫者在加爾文暗礁的無賴角一帶活動。我們對他們了解有限，但我們知道希爾瓦娜斯想要他們領袖的人頭。$B$B你擁有很高的評價，$N.如果你接下這個任務，我們就可以讓軍隊的注意維持再對抗阿爾薩斯的部隊上。你願意幫忙嗎?','找到格瑞希克斯·斷紡，他在凜風峽灣的西南邊海岸，加爾文暗礁的最北端。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11487,'zhTW','美酒中的美酒','我知道像你這樣的$G小子:姑娘;最喜歡阻止衝突了，對吧？你想要讓你們的美酒節平平安安地辦完，不要出亂子。那麼我有一個提議……$B$B在這只酒杯中裝滿我們最棒的烈酒，然後把它交給奧格瑪外的美酒節組織者，這樣我們黑鐵矮人也算是參加了這個節日！全艾澤拉斯最棒的烈酒來自這裡！黑石山的深處！不要忘了這一點！','將黑鐵啤酒杯交給杜洛塔的塔波爾·斯威雷格。','','到杜洛塔找塔波爾·斯威雷格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11597,'zhTW','戰歌要塞的防禦','我們似乎總是在最糟糕的情形下相遇呢，甲蟲之王。自從我們上一次見面以後，你還一直在拯救世界嗎？$B$B<薩魯法爾輕聲笑了起來。>$B$B不管我們年輕的指揮官怎麼說，諾森德非常需要你的説明。$B$B如果能有一打像你這麼強大的士兵，我們現在已經在奧格瑪舒服地烤火了。$B$B去向戰歌要塞南門外的拉茲格爾大王報導吧。','向戰歌要塞南方小屋裡的拉茲格爾大王報到。','','向霸王瑞茲葛回報，他就在戰歌堡外的南方主要通道。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11997,'zhTW','再次向格裡安·斯托曼報到','月溪旅奉命轉至灰白之丘東北部，確保那裡的通行安全。他們在灰喉堡東北方、索爾莫丹西南方創建了一處營地。$B$B你應該認識月溪旅的領袖格裡安·斯托曼上尉吧？在對抗洛丹倫天災軍團的戰役中，格裡安立下了赫赫戰功。但他卻毅然決定離開戰場，返回西部荒野對抗迪菲亞兄弟會。','與月溪旅營地的格裡安·斯托曼上尉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12070 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12070,'zhTW','重整部隊','鐵之子使用他們的符文奴役了我許多的兄弟，用他們來突破鐸爾莫丹的圍城。我希望我們不必與他們作戰，但我們沒有選擇。$B$B我的巨人無法支撐太久這樣的攻擊。$B$B我對這片土靈裂片灌注了祝福的力量，以協助我們的盟友。帶著這個參與北方巨礫之丘的戰鬥，並且用這來穩定並且強化我們的同伴。$B$B殺死所有阻礙你的鐵矮人。','在巨礫之丘的戰鬥中使用大地裂片來重整灰白之丘巨人，殺死阻礙你的鐵矮人，然後向庫倫回報，他就在可以俯瞰鐸爾莫丹的山丘上。','','到灰白之丘的巨礫之丘找庫倫。','鼓舞灰白之丘巨人','殺死鐵符文復仇者','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12434,'zhTW','繼續尋找溶解劑','','','','去找灰白之丘的古圖爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12446,'zhTW','繼續尋找溶解劑','','','','去灰白之丘找風險灣的巴布芬克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12771,'zhTW','鐵爐堡','聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到鐵爐堡。麥格尼·銅須急於轉至諾森德參戰，這件聖物可以説明他達成目標。','拉莎莉爾主教要你將光明聖物交給鐵爐堡的國王麥格尼·銅須。','','到鐵爐堡找國王麥格尼·銅須。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12776,'zhTW','艾克索達','聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到艾克索達，交給聖光穹頂的先知維倫。他可以借用聖物的力量對抗阿爾薩斯的邪惡部隊。','拉莎莉爾主教要你將光明聖物交給艾克索達的維倫。','','到艾克索達找先知維倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12777,'zhTW','絕望的聯軍','親愛的$n，巫妖王在用疾病和侵略折磨著我們——部落和聯盟都深受其害。只有艾澤拉斯的這兩個偉大文明聯手，才有可能擊敗他。$B$B我們在撒塔斯城的聖光廣場結成了聯軍。$B$B為了幫助我們對抗巫妖王，請你到聖光廣場的新聯盟營地去，和拉莎莉爾主教談一談。$B$B願聖光保佑你，$n。','到撒塔斯城的聖光廣場去，與新聯盟營地中的拉莎莉爾主教談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12809,'zhTW','鐵爐堡','聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到鐵爐堡。侏儒區的大工匠梅卡托克正在期待著借助聖物的力量為聯盟效力。','拉莎莉爾主教要你將光明聖物交給鐵爐堡的大工匠梅卡托克。','','到鐵爐堡找大工匠梅卡托克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12812,'zhTW','奧格瑪','終於有重大突破了！我們的僵屍樣本在天災的影響下產生了新的特性，並結出了豐碩的果實……$B$B把這只盒子帶到奧格瑪去。裡面是一枚帶有僵屍疫病的徽記，上面還有我們添加的其它東西——一種反藥劑。這兩種將在徽記上相互作用，而我敢肯定，這枚徽記就是治癒疫病的關鍵。$B$B把這只盒子交給我的助手，藥劑師卡爾洛夫。他就在奧格瑪的薩爾酋長身邊。','大藥劑師普特雷斯要求你將雙天災腦質交給奧格瑪的藥劑師卡爾洛夫。','','到奧格瑪找藥劑師卡爾洛夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12817,'zhTW','調查艾克索達的天譴軍團','巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛艾克索達不受可惡的入侵者騷擾吧？$b $b外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！','從艾克索達外的天譴軍團身上，收集三個暗淡的亡域之石，並調查它們營地附近發光的符文法陣。然後回去找克瑞格中尉。','調查法陣','到艾克索達找克雷格爾上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13181,'zhTW','冬握之捷','指揮官桑奈希的腳下堆了這麼多的部落屍體，他一定很滿意，但是對驍勇遠征軍而言，控制冬握才是最重要的目標。你得確保我們能徹底控制冬握湖。$B$B不過，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。','在冬握戰場中獲勝，並向冬握湖的戰術軍官阿布拉米斯回報。你必須參與戰鬥才能擁有勝利的榮耀。','在冬握湖取得勝利','到冬握湖找戰術軍官阿布拉米斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13183,'zhTW','冬握之捷','雖然達多許必定會為我們痛宰敵人感到滿意，但掌控冬握堡壘才是我們的最終目的。不擇手段也要確保冬握湖是我們的。$B$B然而，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。','在冬握戰場中獲勝，並向冬握湖的戰術軍官科伊瑞斯回報。你必須要參與戰鬥才能擁有勝利的榮耀。','在冬握湖取得勝利','到冬握湖找戰術軍官科伊瑞斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13257,'zhTW','戰爭的使者','酋長需要你，勇士。奧格瑪進入了全城戒嚴狀態，一場不可避免的衝突迫在眉睫。酋長已經下令關閉所有的商店和服務設施，全面備戰。$B$B我不能透露更多的消息了——至少現在不能。在這樣的場合跟你談論局勢也不合適。$B$B酋長傳下令來，部落最強大的勇士必須立即趕往王座廳向他報到。去吧，$N！穿過傳送門返回奧格瑪，向薩爾報到。','轉至奧格瑪的格羅瑪什堡壘，向薩爾報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14086,'zhTW','馳騁在奧格瑪','這本關於騎乘訓練和坐騎購買的廣告小冊子是由基爾達派發出來的。$B$B你可以在奧格瑪的榮譽谷找到基爾達。','將這本小冊子交給奧格瑪榮耀谷的基爾達。','','到艾薩拉找基爾達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14100,'zhTW','大地之環的遺跡','$N，你已經掌握了許多技能，能夠自如地控制四大元素了。而你要努力去做的就是維持四大元素的平衡。只要經過不懈的聯繫，你就能只攜帶一枚聖物，而不必再攜帶全部四件圖騰了。$B$B同奧格瑪智慧谷的戈圖拉·林風談談，在那裡繼續磨礪你控制元素的技藝吧。','將你的四大元素圖騰交給奧格瑪的戈圖拉·林風。','','到奧格瑪找戈圖拉·林風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14169,'zhTW','死者的感激','真高興能再次見到朋友和親人，不過也許我做得有些太誇張了……我已經吃光了他們為我準備的一切！$B$B能不能幫我一個忙，再給我拿來一些那種美味的悼念糕餅？我會非常感激你的……$B$B我想，那邊的查普曼正在出售食譜。','弄到悼念糕餅，並把它交給艾克索達墓地的歡快的德萊尼靈魂。$B$B你必須使用一朵橙菊，才能看到那個隱形的靈魂。','','到秘藍島找歡快的德萊尼靈魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14179,'zhTW','戰鬥的召喚：風暴之眼','對抗部落的戰鬥是沒有盡頭的，$N。即使在外域，對於地盤的爭奪和世代積累的仇恨同樣引發了一場場戰鬥。$B$B現在，進入風暴之眼，為聯盟奪取輝煌的勝利，就像我們在艾澤拉斯做的一樣。','在風暴之眼戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟準將覆命。','風暴之眼的勝利','去找聯盟準將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14182,'zhTW','戰鬥的召喚：風暴之眼','我們要在所有地方將敵人擊潰，無論是在艾澤拉斯還是外域。$B$B絕不能允許聯盟在風暴之眼取得優勢。我們要在今天打敗他們……等到明天，一切都太遲了！','在風暴之眼戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','風暴之眼的勝利','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14353,'zhTW','邪惡的盟友','看樣子，瑪克林就在剃刀高地外面。我們必須將他消滅。$b$b我在奧格瑪的線人告訴我，他們的偵察兵在那裡發現了一些奇怪的跡象。那裡的野豬人身上發生了一些怪異的現象，他們的力量比以前強大了許多。不管天災軍團在那裡做了什麼，我們必須立刻阻止他們。$b$b找到那個瑪克林，消滅他。然後回來向我報告。','將瑪克林大師的信物交給幽暗城的布拉貢·血拳。','','回幽暗城的皇家區找貝拉戈·血拳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14441,'zhTW','加爾魯什的親筆簽名','他們說加爾魯什·地獄咆哮是部落最偉大的英雄之一！等我長大了，我也要成為部落的一名英雄！$B$B你認識加爾魯什嗎，$N？你能幫我個忙嗎？能不能幫我要到一份他的親筆簽名？我不知道該如何開口問他，他那樣偉大的人可能不會理我這樣的人……但你可以！你是一名冒險者，就像他一樣！我敢說他一定會毫不猶豫地給你簽名的！$B$B求求你了？','轉至奧格瑪，為你所監護的兒童取得加爾魯什·地獄咆哮的親筆簽名。','','去找獸人孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25228,'zhTW','災難預言','奧格瑪的街道上出現了一幫傢伙，他們滿嘴都是災難即將降臨的蠢話。這在奧格瑪本不算什麼新鮮事。但這幫傢伙卻讓我相當擔憂。他們的行動很有組織性。暗巷區的許多人都受到了他們的影響。他們的勢力在那裡發展得相當迅速。$B$B我考慮過將他們剿除，或者制止他們的活動。但貿然行動只會讓他們轉入地下。我們需要對他們有更多瞭解。你能不能到暗巷區去，聽聽那些末日預言者都在傳播些什麼？你最好能找到一些與他們的理念相關的文字情報。','在暗巷區聽取一名末日預言者的演講，並取得名為《靈魂之元素火焰》、《萬物的終結對我有何意義？》和《在毀滅的世界中尋找安全與舒適》的小冊子。','','回到奧格瑪的力量谷向血衛士托雷克回報。','聽聽末日預言者的演說','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25254,'zhTW','及時的標記','我們要採取行動，讓公眾對那個預言毀滅的教派失去興趣。但在我瞭解這個組織的幕後操控者之前，我很難決定該如何對這個組織下手。$B$B我已經讓我的部下在奧格瑪行人最密集的地方做好了標記。帶上這些佈告，把它們張貼在有這種標記的地方。它們對於那些下定決心的追隨者們不會有多大作用。但它畢竟是揭露這個教派邪惡面的第一步。部落的敵人已經很多了。所以我們現在更不能任由這些傢伙四處散佈謊言。','在力量穀、暗巷區或者榮譽穀各處張貼5張報警佈告。','','返回奧格瑪的力量穀，去找血衛士托雷克。','告示設置完畢','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25288,'zhTW','滲透行動','關於那個奇怪教派的傳聞正在奧格瑪的街巷間四處流傳。但對於它的來源和所作所為，卻沒有人清楚。$N，現在只有一個辦法能夠查清楚這群傢伙的底細。你要去加入他們。$B$B在暗巷區找到一個末日預言者，告訴他你想要入夥。如果你的運氣好，他們會把你引薦給他們的一個領導人，然後你就能知道他們的藏身之地了。你要穿上末日預言者給你的衣服，這樣你才能進入他們的秘密據點。','同奧格瑪暗巷區的一名末日預言者交談，加入他們的教派，然後穿上信徒長袍。','','到奧格瑪外面的野豬農場找監督者金塔克。','加入末日教派','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25293,'zhTW','失蹤人口','除了那個神秘教派在城市中散佈的混亂和猜疑之外，我們還收到了無數關於失蹤人口的報告。人們的母親、父親、兄弟姐妹都在無緣無故地消失。我有一種感覺，這些失蹤的人可能都在那個教派位於城外的某個基地中。如果我給你一些失蹤者的名字，你是否能在那個教派的一座營地中找到他們？那座營地就在奧格瑪南邊的野豬農場。如果你要進入那座營地，首先要從暗巷區的末日預言者手中得到一件信徒長袍。','穿上教派偽裝，同杜洛塔野豬農場中的教徒卡加恩、教徒艾格塔、教徒托卡和教徒洛卡迦交談。','','到奧格瑪找血衛士托雷克。','和教徒卡嘎恩交談。','和教徒阿格塔交談。','和教徒托卡交談。','和教徒羅卡嘎交談。',0);
-- Fix remaining zhTW quest_template_locale rows (previously complete, not part of earlier gap/zone-name batches) still using zhCN-style zone names
DELETE FROM `quest_template_locale` WHERE `ID` = 286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (286,'zhTW','歸還雕像','你把這個木桶從垃圾裡拖了出來，剛一打開它，一尊精心包裹在稻草中的銀制小刻像就掉了出來。這是一個頭髮很長的年輕聖騎士高舉戰錘的樣子。$B$B這一定就是米奈希爾刻像了!你必須馬上把它交還給米奈希爾港的卡爾·波蘭。','到濕地的米奈希爾港，將米奈希爾雕像還給卡爾·波蘭。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (292,'zhTW','帕雷斯之眼','打開箱子之後，你看到了一顆發黑的寶珠，它還在閃爍著可怕的光芒。這就是菲茲莫斯所說的寶藏:一顆被詛咒的帕雷斯之眼。$B$B把被詛咒的帕雷斯之眼交給住在米奈希爾港的矮人牧師戈羅林·鋼眉，請他驅除附著在它上面的詛咒。','到濕地的米奈希爾港，把被詛咒的帕雷斯之眼交給戈羅林·鋼眉。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (306,'zhTW','尋找挖掘隊','這太恐怖啦!我們剛剛發現了一些十分稀有的古物，而且正在把這些巨大的骸骨挖掘出來，這個時候，可怕的事就發生了，在我們反應過來之前，多到數不清的雜斑迅猛龍沖進了挖掘場，咬死了許多人!$B$B勇敢非凡的奧莫爾救下了我和勘察員，並一直把我們護送到了一處藏身之所。現在我們被徹底困在這裡了，逃也逃不出去，我們努力工作的成果也全毀了。$B$B給，把這封信帶回去交給我親愛的塔雷爾，我已經在信裡把事情跟他解釋清楚了。','到濕地的米奈希爾港，把麥琳的信件交給塔雷爾·石紋。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (632,'zhTW','薩多爾大橋','很顯然，可憐的老伊本瑟遭遇到了黑鐵矮人的伏擊，已經戰死了。但你突然注意到了他緊握著的拳頭中似乎有一張皺皺的羊皮紙。$B$B將這條令人沮喪的消息告訴拉格·加瑪森，並把你的發現報告給他。','到濕地的丹莫德向拉格·加瑪森回報，並將你在伊本瑟屍體上找到的羊皮紙交給他看看。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5649,'zhTW','部族的傳統','啊，朋友。我們之所以加入部落，是因為他們對我們很好。他們彼此忠誠，他們教會我們很多東西——比如榮耀。但是我們的一些傳統正在逐漸失去。也許獸人不認同我們所有的傳統，但是這並不妨礙我們秘密地延續它們。$B$B你知道這些，所以我派你去找剃刀嶺的泰金。她會向你教授更多關於我們歷史的東西，她會向你教授更多關於我們部族的東西。當你準備好了之後，就去找她。','與杜洛塔的泰金談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11486,'zhTW','美酒中的美酒','我知道像你這樣的$G小子:姑娘;最喜歡阻止衝突了，對吧？你想要讓你們的美酒節平平安安地辦完，不要出亂子。那麼我有一個提議……$B$B在這只酒杯中裝滿我們最棒的烈酒，然後把它交給鐵爐堡外的美酒節組織者，這樣我們黑鐵矮人也算是參加了這個節日！全艾澤拉斯最棒的烈酒來自這裡！黑石山的深處！不要忘了這一點！','將黑鐵啤酒杯交給丹莫洛的埃菲庫格·鐵桶。','','到丹莫洛找埃菲庫格·鐵桶。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12278,'zhTW','每月啤酒俱樂部','會員享有優惠。成為「每月啤酒俱樂部」的會員，表示你有管道獲得到最新、最青的啤酒。$B$B帶著你的「每月啤酒」俱樂部會員表格給拉金‧雷酒，他就在鐵爐堡的石火旅店中。','把「每月啤酒」俱樂部會員表格帶給拉金‧雷酒，他就在鐵爐堡的石火旅店中。','','到鐵爐堡的石火旅店找丹莫洛的拉金‧雷酒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13932,'zhTW','又是一年美酒飄香時。','美酒節除了賽羊會外，還有一項傳統，那就是飲酒狂歡！如果你有時間的話，就將這張禮品券交給貝爾比吧。她就在美酒節營地的後面。要是你看不見她，沒關係，她一定會看見你的。$B$B無論如何，將禮品券交給她，你就能免費領到一隻美酒節酒杯。她還出售各種美酒哦。','在美酒節營地的貝爾比處兌換禮品券。','','去找丹莫洛的貝爾比。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14167,'zhTW','死者的感激','真高興能再次見到朋友和親人，不過也許我做得有些太誇張了……我已經吃光了他們為我準備的一切！$B$B能不能幫我一個忙，再給我拿來一些那種美味的悼念糕餅？我會非常感激你的……$B$B我想，那邊的查普曼正在出售食譜。','弄到悼念糕餅，並把它交給鐵爐堡墓地的歡快的矮人靈魂。$B$B你必須使用一朵橙菊，才能看到那個隱形的靈魂。','','到丹莫洛鐵爐堡大門找附近的歡快的矮人靈魂。','','','','',0);
